	/**
	 * Reads the ref-count marker without creating any LMDB named database. This is deliberately the first database
	 * operation after opening an existing environment: opening a missing named database with {@code MDB_CREATE} is a
	 * write transaction, so validation must happen before the normal auxiliary-database bootstrap.
	 */
	private static RefCountMarkerStatus inspectRefCountMarkerBeforeStartupWrites(long environment,
			LmdbStoreFormat format, boolean newNativeGeneration) throws IOException {
		long txn = 0;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_txn_begin(environment, NULL, MDB_RDONLY, pp));
			txn = pp.get(0);
			RetiredValueIdStore.validateMetadataSchema(txn, format, newNativeGeneration);
			IntBuffer dbiHandle = stack.mallocInt(1);
			int rc = mdb_dbi_open(txn, (String) null, 0, dbiHandle);
			if (rc == MDB_NOTFOUND) {
				IntBuffer refCountsHandle = stack.mallocInt(1);
				rc = mdb_dbi_open(txn, "ref_counts", 0, refCountsHandle);
				if (rc == MDB_NOTFOUND) {
					return new RefCountMarkerStatus(true, false, mdb_txn_id(txn));
				}
				E(rc);
				return new RefCountMarkerStatus(false, false, mdb_txn_id(txn));
			}
			E(rc);

			MDBStat stat = MDBStat.malloc(stack);
			E(mdb_stat(txn, dbiHandle.get(0), stat));
			boolean mainDatabaseEmpty = stat.ms_entries() == 0L;
			long nativeTransactionId = mdb_txn_id(txn);

			IntBuffer refCountsHandle = stack.mallocInt(1);
			rc = mdb_dbi_open(txn, "ref_counts", 0, refCountsHandle);
			if (rc == MDB_NOTFOUND) {
				return new RefCountMarkerStatus(mainDatabaseEmpty, false, nativeTransactionId);
			}
			E(rc);
			// Once the named count DB exists, a missing marker must trigger reconciliation even when the main
			// dictionary is
			// empty. This covers raw count or RDF-star index imports into a fresh environment and old stores that
			// predate
			// the marker; only an environment with no count DB at all is definitely new.
			boolean emptyStore = false;

			MDBVal markerKey = MDBVal.calloc(stack);
			markerKey.mv_data(stack.bytes(new byte[] { REFCOUNT_MARKER_KEY }));
			MDBVal markerValue = MDBVal.calloc(stack);
			rc = mdb_get(txn, refCountsHandle.get(0), markerKey, markerValue);
			if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
				E(rc);
			}
			if (rc == MDB_SUCCESS && format.isLegacy()
					&& markerValue.mv_data().remaining() == REF_COUNTS_VERSION.length
					&& markerValue.mv_data().get(markerValue.mv_data().position()) == REF_COUNTS_VERSION[0]) {
				// The format-2 writer's completion marker predates native transaction/CRC validation. Recognize
				// that historical schema, but never treat it as clean: rebuild counts from active dictionary owners.
				return new RefCountMarkerStatus(false, false, nativeTransactionId);
			}
			if (rc == MDB_SUCCESS) {
				validateRefCountMarkerSchema(markerValue.mv_data());
			}
			boolean valid = rc == MDB_SUCCESS && isValidRefCountMarker(markerValue.mv_data(), nativeTransactionId);
			return new RefCountMarkerStatus(emptyStore, valid, nativeTransactionId,
					rc == MDB_SUCCESS && format.isLegacy());
		} finally {
			if (txn != 0) {
				mdb_txn_abort(txn);
			}
		}
	}

	static boolean isValidRefCountMarker(ByteBuffer marker, long nativeTransactionId) {
		if (marker == null || marker.remaining() != REFCOUNT_MARKER_BYTES) {
			return false;
		}
		byte[] bytes = new byte[marker.remaining()];
		marker.duplicate().get(bytes);
		ByteBuffer encoded = ByteBuffer.wrap(bytes);
		if (encoded.getInt() != REFCOUNT_MARKER_MAGIC || encoded.get() != REFCOUNT_MARKER_VERSION
				|| encoded.get() != REFCOUNT_MARKER_CLEAN || encoded.getLong() != nativeTransactionId) {
			return false;
		}
		CRC32 checksum = new CRC32();
		checksum.update(bytes, 0, bytes.length - Integer.BYTES);
		return encoded.getInt() == (int) checksum.getValue();
	}

	private static void validateRefCountMarkerSchema(ByteBuffer marker) throws IOException {
		if (marker == null || marker.remaining() < Integer.BYTES + 1) {
			throw new IOException("Unsupported ValueStore ref-count metadata schema");
		}
		ByteBuffer encoded = marker.duplicate();
		if (encoded.getInt() != REFCOUNT_MARKER_MAGIC || encoded.get() != REFCOUNT_MARKER_VERSION) {
			throw new IOException("Unsupported ValueStore ref-count metadata schema");
		}
	}

	private static byte[] encodeRefCountMarker(byte state, long nativeTransactionId) {
		ByteBuffer encoded = ByteBuffer.allocate(REFCOUNT_MARKER_BYTES);
		encoded.putInt(REFCOUNT_MARKER_MAGIC);
		encoded.put(REFCOUNT_MARKER_VERSION);
		encoded.put(state);
		encoded.putLong(nativeTransactionId);
		CRC32 checksum = new CRC32();
		checksum.update(encoded.array(), 0, encoded.position());
		encoded.putInt((int) checksum.getValue());
		return encoded.array();
	}

	FreshValueSession startFreshValueSessionIfEmpty() throws IOException {
		if (!canStartFreshValueSession()) {
			return null;
		}
		FreshValueSession session = new FreshValueSession();
		activeFreshValueSession = session;
		return session;
	}

	/** Tests the same fresh-dictionary eligibility without claiming a session or mutating dictionary state. */
	boolean canStartFreshValueSession() throws IOException {
		if (format.isLegacy() || freeIdsAvailable) {
			return false;
		}
		return readTransaction(env, (stack, txn) -> {
			PointerBuffer cursorHandle = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, dbi, cursorHandle));
			long cursor = cursorHandle.get(0);
			try {
				MDBVal key = MDBVal.malloc(stack);
				key.mv_data(stack.bytes(ID_KEY));
				MDBVal value = MDBVal.malloc(stack);
				int rc = mdb_cursor_get(cursor, key, value, MDB_SET_RANGE);
				return rc == MDB_NOTFOUND || key.mv_data().get(0) != ID_KEY;
			} finally {
				mdb_cursor_close(cursor);
			}
		});
	}

	void discardFreshValueSession(FreshValueSession session) {
		if (activeFreshValueSession == session) {
			activeFreshValueSession = null;
		}
	}

	void commitFreshValueTransaction(FreshValueSession session) {
		if (session != null) {
			clearFreshValueTransaction(session);
		}
	}

	void rollbackFreshValueTransaction(FreshValueSession session) {
		if (session == null) {
			return;
		}
		for (int i = session.provisionalValues.size() - 1; i >= 0; i--) {
			session.valueIds.removeKey(session.provisionalValues.get(i));
		}
		for (int i = session.provisionalNamespaces.size() - 1; i >= 0; i--) {
			session.namespaceIds.removeKey(session.provisionalNamespaces.get(i));
		}
		for (int i = session.provisionalFirstLargeHashes.size() - 1; i >= 0; i--) {
			session.firstLargeValueIds.remove(session.provisionalFirstLargeHashes.get(i));
		}
		var referenceIds = session.provisionalReferenceDeltas.keysView().longIterator();
		while (referenceIds.hasNext()) {
			long id = referenceIds.next();
			long count = session.referenceCounts.addToValue(id, -session.provisionalReferenceDeltas.get(id));
			if (count == 0) {
				session.referenceCounts.removeKey(id);
			}
		}
		clearFreshValueTransaction(session);
	}

	private void clearFreshValueTransaction(FreshValueSession session) {
		session.provisionalValues.clear();
		session.provisionalNamespaces.clear();
		session.provisionalFirstLargeHashes.clear();
		session.provisionalReferenceDeltas.clear();
	}

