	void setReplayDecision(TxnReplayPolicy.Decision decision) {
		replayDecision = decision;
	}

	void clearReplayDecision(TxnReplayPolicy.Decision decision) {
		if (replayDecision == decision && (decision == null || !decision.failed())) {
			replayDecision = null;
		}
	}

	private void checkReplayFailure() throws IOException {
		TxnReplayPolicy.Decision decision = replayDecision;
		if (decision != null) {
			decision.check();
		}
	}

	/**
	 * Conservative dictionary demand of buffered statements whose values were never inspected: every position is
	 * assumed to be a new record of bounded size. The exact preflight at prepare sizes the actual values.
	 */
	long estimateAdvisoryWriteBytes(long statementCount) {
		return saturatedEstimateMultiply(statementCount, DictionaryByteEstimate.UNINSPECTED_STATEMENT_BYTES);
	}

	/**
	 * Returns the dictionary ID of a value this store already holds under its current revision, or
	 * {@link LmdbValue#UNKNOWN_ID} when writing the value may add a record. Mirrors the own-value fast path of
	 * {@link #getId(Value, boolean)} without resolving a lazy value or touching the native environment.
	 */
	long storedValueId(Value value) {
		if (!(value instanceof LmdbValue lmdbValue) || lmdbValue.getSemanticVersion() == LmdbValue.UNKNOWN_ID) {
			return LmdbValue.UNKNOWN_ID;
		}
		LmdbValue.InternalIdentity identity = lmdbValue.getInternalIdentity();
		if (identity == null || identity.revision() == null || identity.revision().getValueStore() != this) {
			return LmdbValue.UNKNOWN_ID;
		}
		WriterPublication publication = writerPublication;
		boolean ownsNativeWriter = writeTxn != 0 && writeTxnOwner == Thread.currentThread();
		if (publication != null && (publication.owner != Thread.currentThread() || !ownsNativeWriter)) {
			return LmdbValue.UNKNOWN_ID;
		}
		return revision.equals(identity.revision()) ? identity.id() : LmdbValue.UNKNOWN_ID;
	}

	long estimateWriteBytes(List<Statement> statements) {
		// A single statement needs no distinct-count sketch: counting its few repeated fields is conservative.
		DictionaryByteEstimate estimate = new DictionaryByteEstimate(statements.size() > 1, this::storedValueId);
		for (Statement statement : statements) {
			estimate.add(statement.getSubject());
			estimate.add(statement.getPredicate());
			estimate.add(statement.getObject());
			estimate.add(statement.getContext());
		}
		return saturatedEstimateAdd(128L, estimate.bytes());
	}

	/** Flat-buffer admission cost; does not allocate a hash set for every ordinary add. */
	static long estimatedRetainedBytes(Statement statement) {
		long bytes = 128L;
		bytes = saturatedEstimateAdd(bytes, estimatedRetainedBytes(statement.getSubject()));
		bytes = saturatedEstimateAdd(bytes, estimatedRetainedBytes(statement.getPredicate()));
		bytes = saturatedEstimateAdd(bytes, estimatedRetainedBytes(statement.getObject()));
		return saturatedEstimateAdd(bytes, estimatedRetainedBytes(statement.getContext()));
	}

	private static long estimatedRetainedBytes(Value value) {
		long bytes = 0L;
		Value checkpoint = value;
		long power = 1L;
		long length = 0L;
		// Triple terms can nest in object position. Brent's identity check needs no set or model hash.
		while (value instanceof TripleTerm triple) {
			bytes = saturatedEstimateAdd(bytes, 64L);
			bytes = saturatedEstimateAdd(bytes, estimatedRetainedScalarBytes(triple.getSubject()));
			bytes = saturatedEstimateAdd(bytes, estimatedRetainedScalarBytes(triple.getPredicate()));
			value = triple.getObject();
			if (value == checkpoint) {
				throw new IllegalArgumentException("Cyclic triple term cannot be estimated");
			}
			if (++length == power) {
				checkpoint = value;
				power = power > Long.MAX_VALUE / 2L ? Long.MAX_VALUE : power * 2L;
				length = 0L;
			}
		}
		return saturatedEstimateAdd(bytes, estimatedRetainedScalarBytes(value));
	}

	private static long estimatedRetainedScalarBytes(Value value) {
		if (value == null) {
			return 0L;
		}
		if (value instanceof TripleTerm) {
			throw new IllegalArgumentException("A triple term cannot be a subject, predicate or datatype");
		}
		if (value instanceof Literal literal) {
			long bytes = saturatedEstimateAdd(96L, saturatedEstimateMultiply(literal.getLabel().length(), 2L));
			IRI datatype = literal.getDatatype();
			if (datatype != null) {
				bytes = saturatedEstimateAdd(bytes,
						saturatedEstimateAdd(64L, saturatedEstimateMultiply(datatype.stringValue().length(), 2L)));
			}
			String language = literal.getLanguage().orElse(null);
			return language == null ? bytes
					: saturatedEstimateAdd(bytes, saturatedEstimateAdd(32L, language.length() * 2L));
		}
		return saturatedEstimateAdd(64L, saturatedEstimateMultiply(value.stringValue().length(), 2L));
	}

	long estimateWriteBytes(SailSource.WritePreflight preflight) {
		return saturatedEstimateAdd(estimateWriteBytes(preflight.statements()), estimateWriteMetadataBytes(preflight));
	}

	/** One pass over the input: the observer sees every statement, so callers can count without a second cursor. */
	long estimateWriteBytes(StatementInput input, Consumer<Statement> observer) {
		long statementEstimate = 128L;
		try (CloseableIteration<Statement> statements = input.openCursor()) {
			DictionaryByteEstimate estimate = estimateStatements(statements, observer, this::storedValueId);
			if (estimate != null) {
				statementEstimate = saturatedEstimateAdd(statementEstimate, estimate.bytes());
			}
		}
		input.validate();
		return saturatedEstimateAdd(statementEstimate, estimateWriteMetadataBytes(input.metadata()));
	}

	/** Statements fingerprinted exactly before a streamed estimate starts sampling subject runs. */
	static final int EXACT_PREFIX_STATEMENTS = 8192;
	/** After the exact prefix, one in this many subject runs is fingerprinted; the rest are sized without hashing. */
	static final int SAMPLE_INTERVAL = 8;

	/**
	 * Feeds every statement of a streamed input to a distinct-aware dictionary estimate. Returns {@code null} for an
	 * empty input.
	 */
	static DictionaryByteEstimate estimateStatements(Iterator<Statement> statements, Consumer<Statement> observer) {
		return estimateStatements(statements, observer, value -> LmdbValue.UNKNOWN_ID);
	}

	/**
	 * As {@link #estimateStatements(Iterator, Consumer)}, with values the dictionary already holds (per
	 * {@code storedId}) costing nothing and never being resolved.
	 */
	static DictionaryByteEstimate estimateStatements(Iterator<Statement> statements, Consumer<Statement> observer,
			ToLongFunction<Value> storedId) {
		if (!statements.hasNext()) {
			return null;
		}
		Statement statement = statements.next();
		boolean moreStatements = statements.hasNext();
		DictionaryByteEstimate estimate = new DictionaryByteEstimate(moreStatements, storedId);
		long index = 0L;
		long run = 0L;
		Resource previousSubject = null;
		do {
			observer.accept(statement);
			Resource subject = statement.getSubject();
			if (subject != previousSubject && (previousSubject == null || !subject.equals(previousSubject))) {
				// Grouped input (one subject, many statements) is sampled per subject run, so a sampled run
				// contributes all of its statements and subject cardinality extrapolates correctly.
				run++;
				previousSubject = subject;
			}
			if (index < EXACT_PREFIX_STATEMENTS || run % SAMPLE_INTERVAL == 0L) {
				estimate.add(subject);
				estimate.add(statement.getPredicate());
				estimate.add(statement.getObject());
				estimate.add(statement.getContext());
			} else {
				estimate.skip(subject);
				estimate.skip(statement.getPredicate());
				estimate.skip(statement.getObject());
				estimate.skip(statement.getContext());
			}
			index++;
			if (!moreStatements) {
				break;
			}
			statement = statements.next();
			moreStatements = statements.hasNext();
		} while (true);
		return estimate;
	}

	private long estimateWriteMetadataBytes(SailSource.WritePreflight preflight) {
		long estimate = 0L;
		for (SailSource.NamespaceUpdate namespace : preflight.addedNamespaces()) {
			long serializedBytes = DictionaryByteEstimate.utf8UpperBound(namespace.prefix())
					+ DictionaryByteEstimate.utf8UpperBound(namespace.name()) + 32L;
			estimate = saturatedEstimateAdd(estimate,
					saturatedEstimateAdd(saturatedEstimateMultiply(serializedBytes, 4L), 256L));
		}
		if (preflight.statementCleared() || !preflight.clearedContexts().isEmpty()
				|| preflight.namespaceCleared() || !preflight.removedNamespacePrefixes().isEmpty()) {
			estimate = saturatedEstimateAdd(estimate, LmdbUtil.MIN_FREE_SPACE);
		}
		return estimate;
	}

	boolean requiresResizeForEstimatedWrite(long estimatedWriteBytes) throws IOException {
		if (!autoGrow) {
			return false;
		}
		return growthPolicy.requiresGrowth(mapSize, occupiedBytes(), estimatedWriteBytes);
	}

	long occupiedBytes() throws IOException {
		long stamp = txnManager.acquireMetadataReadBarrier();
		try (MemoryStack stack = stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.calloc(stack);
			E(mdb_env_info(env, info));
			long nextPageNo = info.me_last_pgno() == Long.MAX_VALUE ? Long.MAX_VALUE : info.me_last_pgno() + 1L;
			return saturatedEstimateMultiply(nextPageNo, pageSize);
		} finally {
			txnManager.releaseMetadataReadBarrier(stamp);
		}
	}

	boolean growMapForEstimatedWrite(long estimatedWriteBytes, LmdbSailStore.MapGrowthAttempt growthAttempt)
			throws IOException {
		if (!autoGrow || writeTxn != 0) {
			return false;
		}
		StampedLongAdderLockManager lockManager = txnManager.lockManager();
		long stamp;
		try {
			stamp = lockManager.writeLock();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException("Interrupted while preparing the ValueStore map for a buffered write", e);
		}
		try {
			if (writeTxn != 0 || !requiresResizeForEstimatedWrite(estimatedWriteBytes)) {
				return false;
			}
			detachStableReadSnapshots(growthAttempt);
			txnManager.deactivate();
			try {
				long nextPageNo;
				try (MemoryStack stack = stackPush()) {
					MDBEnvInfo info = MDBEnvInfo.calloc(stack);
					E(mdb_env_info(env, info));
					nextPageNo = info.me_last_pgno() == Long.MAX_VALUE ? Long.MAX_VALUE : info.me_last_pgno() + 1L;
				}
				long currentFootprint = saturatedEstimateMultiply(nextPageNo, pageSize);
				long projectedFootprint = saturatedEstimateAdd(currentFootprint, estimatedWriteBytes);
				long resizedMapSize = growthPolicy.grownMapSize(mapSize, pageSize, projectedFootprint);
				if (growthAttempt != null) {
					growthAttempt.markMapResized(LmdbSailStore.MapResizeKind.VALUE_STORE);
				}
				E(mdb_env_set_mapsize(env, resizedMapSize));
				mapSize = resizedMapSize;
				nativeMapGeneration++;
				return true;
			} finally {
				txnManager.activate();
			}
		} finally {
			lockManager.unlockWrite(stamp);
		}
	}

	private static long saturatedEstimateAdd(long left, long right) {
		return Long.MAX_VALUE - left < right ? Long.MAX_VALUE : left + right;
	}

	private static long saturatedEstimateMultiply(long left, long right) {
		return right != 0 && left > Long.MAX_VALUE / right ? Long.MAX_VALUE : left * right;
	}

	private LmdbSailStore.MapGrowthAttempt beginMapGrowthAttempt() throws IOException {
		LmdbSailStore.MapGrowthAttemptSupplier supplier = mapGrowthAttemptSupplier;
		return supplier == null ? null : supplier.begin();
	}

	void setMapGrowthAttemptSupplier(LmdbSailStore.MapGrowthAttemptSupplier supplier) {
		mapGrowthAttemptSupplier = supplier;
	}

	void setMapGrowthRequestListener(LmdbSailStore.MapGrowthRequestListener listener) {
		mapGrowthRequestListener = listener;
	}

	void setResizeCheckpointListener(Runnable resizeCheckpointListener) {
		this.resizeCheckpointListener = resizeCheckpointListener;
	}

	private void incrementRefCount(MemoryStack stack, long writeTxn, byte[] data) throws IOException {
		// literals have a datatype id and URIs have a namespace id
		if (data[0] == LITERAL_VALUE || data[0] == URI_VALUE) {
			// skip type marker
			long id = Varint.readUnsigned(ByteBuffer.wrap(data, 1, data.length - 1));
			long cached = refCountsTxCache.get(id);
			long current = cached == UNKNOWN_REF_COUNT ? readRefCount(stack, writeTxn, id) : cached;
			refCountsTxCache.put(id, Math.addExact(current, 1L));
		}
	}

	private void incrementRefCount(MemoryStack stack, long writeTxn, long id) throws IOException {
		long cached = refCountsTxCache.get(id);
		long current = cached == UNKNOWN_REF_COUNT ? readRefCount(stack, writeTxn, id) : cached;
		refCountsTxCache.put(id, Math.addExact(current, 1L));
	}

	private boolean decrementRefCount(MemoryStack stack, long writeTxn, long id) throws IOException {
		long cached = refCountsTxCache.get(id);
		long current = cached == UNKNOWN_REF_COUNT ? readRefCount(stack, writeTxn, id) : cached;
		// An absent persisted count is already zero; it must not become a negative cached reference.
		long updated = current == 0L ? 0L : Math.subtractExact(current, 1L);
		refCountsTxCache.put(id, updated);
		return updated == 0L;
	}

	private long readRefCount(MemoryStack stack, long writeTxn, long id) throws IOException {
		stack.push();
		try {
			MDBVal idVal = MDBVal.calloc(stack);
			MDBVal dataVal = MDBVal.calloc(stack);
			ByteBuffer idBb = idBuffer(stack).put(ID_KEY);
			Varint.writeUnsigned(idBb, id);
			idVal.mv_data(idBb.flip());
			int rc = mdb_get(writeTxn, refCountsDbi, idVal, dataVal);
			if (rc == MDB_NOTFOUND) {
				return 0L;
			}
			E(rc);
			try {
				return Varint.readUnsigned(dataVal.mv_data());
			} catch (RuntimeException malformed) {
				throw new IOException("Malformed ValueStore ref-count record for ID " + id, malformed);
			}
		} finally {
			stack.pop();
		}
	}

	private void updateRefCounts(MemoryStack stack, long writeTxn) throws IOException {
		try {
			stack.push();
			MDBVal idVal = MDBVal.calloc(stack);
			ByteBuffer idBb = idBuffer(stack);
			ByteBuffer countBb = stack.malloc(Long.BYTES + 1);
			MDBVal dataVal = MDBVal.calloc(stack);
			for (Long2LongMap.Entry entry : refCountsTxCache.long2LongEntrySet()) {
				long count = entry.getLongValue();
				idBb.clear();
				idBb.put(ID_KEY);
				Varint.writeUnsigned(idBb, entry.getLongKey());
				idVal.mv_data(idBb.flip());
				if (count <= 0) {
					// delete count entry
					E(mdb_del(writeTxn, refCountsDbi, idVal, null));
				} else {
					// update count
					countBb.clear();
					Varint.writeUnsigned(countBb, count);
					dataVal.mv_data(countBb.flip());
					E(mdb_put(writeTxn, refCountsDbi, idVal, dataVal, 0));

				}
			}
		} finally {
			stack.pop();
		}
	}

	/**
	 * Recounts the internal references - the datatype of every literal, the namespace of every IRI and the components
	 * of every triple term - unless {@link StoreProperties#REF_COUNTS_VERSION_KEY} records that the persisted counts
	 * are current. Before that version, adding a reference ignored the count persisted by earlier transactions, so a
	 * count only covered the references added by the last transaction that touched the id, and a datatype, namespace or
	 * triple-term component could be garbage collected while still referenced. Runs once; if the version is not
	 * recorded (a crash right after the commit) the recount simply repeats. Must run after
	 * {@link #freeUnusedIdsOnStartup()}, so every scanned value is still in use.
	 */

	/**
	 * Finds (and optionally creates) the id of an encoded value. The data-to-id direction is keyed by
	 * {@link #lookupKey(byte[])}; format 2 keeps the old writer's raw reverse keys, while canonical RDF matching uses
	 * the semantic owner lookup. The id-to-data direction stores {@code data} as given.
	 */
	private long findId(byte[] data, boolean create) throws IOException {
		return findId(data, create, CoreDatatype.NONE);
	}

	private long findId(byte[] data, byte[] key, long languageRange, boolean create) throws IOException {
		Long id = readTransaction(env,
				(stack, txn) -> findIdInTransaction(data, key, languageRange, create, CoreDatatype.NONE, stack, txn));
		return id == null ? LmdbValue.UNKNOWN_ID : id;
	}

	private long findId(byte[] data, boolean create, CoreDatatype coreDatatype) throws IOException {
		return findId(data, create, coreDatatype, null);
	}

	private long findId(byte[] data, boolean create, CoreDatatype coreDatatype, ValueLookupContext lookup)
			throws IOException {
		Long id = readTransaction(env, (stack, txn) -> {
			if (lookup != null) {
				lookup.captureScope(txn);
			}
			if (!create) {
				try (ValueOverlayRegistry.SnapshotLease overlay = borrowValueOverlay(txn)) {
					if (overlay != null) {
						OptionalLong hit = lookupKey(data) == data ? overlay.findId(data) : OptionalLong.empty();
						if (hit.isPresent()) {
							return hit.getAsLong();
						}
					}
				}
			}
			return findIdInTransaction(data, create, coreDatatype, stack, txn);
		});
		return id != null ? id : LmdbValue.UNKNOWN_ID;
	}

	Long findIdInTransaction(byte[] data, boolean create, CoreDatatype coreDatatype,
			MemoryStack stack, long txn) throws IOException {
		byte[] key = lookupKey(data);
		return findIdInTransaction(data, key, lookupLanguageRange(key), create, coreDatatype, stack, txn);
	}

	private Long findIdInTransaction(byte[] data, byte[] key, long languageRange, boolean create,
			CoreDatatype coreDatatype, MemoryStack stack, long txn) throws IOException {
		if (key.length <= MAX_KEY_SIZE) {
			MDBVal keyVal = MDBVal.calloc(stack).mv_data(stack.bytes(key));
			MDBVal dataVal = key == data ? keyVal : MDBVal.calloc(stack).mv_data(stack.bytes(data));
			MDBVal idVal = MDBVal.calloc(stack);
			if (mdb_get(txn, dbi, keyVal, idVal) == MDB_SUCCESS) {
				return data2id(idVal.mv_data());
			}
			long alternativeId = findAlternativeIriId(data, stack, txn);
			if (alternativeId != LmdbValue.UNKNOWN_ID) {
				return alternativeId;
			}
			if (!create) {
				return null;
			}
			// id was not found, create a new one
			reserveStoredValueCapacity(stack, txn, data);

			long newId = nextId(data[0], coreDatatype);
			writeTransaction((stack2, writeTxn) -> {
				idVal.mv_data(id2data(idBuffer(stack), newId).flip());

				E(mdb_put(writeTxn, dbi, keyVal, idVal, 0));
				E(mdb_put(writeTxn, dbi, idVal, dataVal, 0));
				retainLegacyLanguageOwnerKey(stack2, writeTxn, data, key, newId);
				recordCompressedValueChange(newId);

				// update ref count if necessary
				incrementRefCount(stack2, writeTxn, data);
				return null;
			});
			return newId;
		} else {
			MDBVal idVal = MDBVal.calloc(stack);

			long dataHash = hash(key);
			int maxHashKeyLength = 2 + 2 * Long.BYTES + 2;
			ByteBuffer hashBb = stack.malloc(maxHashKeyLength);
			hashBb.put(HASH_KEY);
			Varint.writeUnsigned(hashBb, dataHash);
			int hashLength = hashBb.position();
			hashBb.flip();

			MDBVal hashVal = MDBVal.calloc(stack);
			hashVal.mv_data(hashBb);
			MDBVal dataVal = MDBVal.calloc(stack);

			// ID of first value is directly stored with hash as key
			if (mdb_get(txn, dbi, hashVal, dataVal) == MDB_SUCCESS) {
				idVal.mv_data(dataVal.mv_data());
				if (mdb_get(txn, dbi, idVal, dataVal) == MDB_SUCCESS
						&& payloadMatchesKey(dataVal.mv_data(), key, languageRange)) {
					return data2id(idVal.mv_data());
				}
			} else {
				// no value for hash exists
				long alternativeId = findAlternativeIriId(data, stack, txn);
				if (alternativeId != LmdbValue.UNKNOWN_ID) {
					return alternativeId;
				}
				if (!create) {
					return null;
				}

				reserveStoredValueCapacity(stack, txn, data);

				long newId = nextId(data[0], coreDatatype);
				writeTransaction((stack2, writeTxn) -> {
					dataVal.mv_size(data.length);
					idVal.mv_data(id2data(idBuffer(stack), newId).flip());
					// store mapping of hash -> ID
					E(mdb_put(writeTxn, dbi, hashVal, idVal, 0));
					// store mapping of ID -> data
					E(mdb_put(writeTxn, dbi, idVal, dataVal, MDB_RESERVE));
					dataVal.mv_data().put(data);
					retainLegacyLanguageOwnerKey(stack2, writeTxn, data, key, newId);
					recordCompressedValueChange(newId);

					// update ref count if necessary
					incrementRefCount(stack2, writeTxn, data);
					return null;
				});
				return newId;
			}

			// test existing entries for hash key against given value
			hashBb.put(0, HASHID_KEY);
			hashVal.mv_data(hashBb);

			long cursor = 0;
			try {
				PointerBuffer pp = stack.mallocPointer(1);
				E(mdb_cursor_open(txn, dbi, pp));
				cursor = pp.get(0);

				// iterate all entries for hash value
				if (mdb_cursor_get(cursor, hashVal, dataVal, MDB_SET_RANGE) == MDB_SUCCESS) {
					do {
						if (compareRegion(hashVal.mv_data(), 0, hashBb, 0, hashLength) != 0) {
							break;
						}

						// use only ID part of key for lookup of data
						ByteBuffer hashIdBb = hashVal.mv_data();
						hashIdBb.position(hashLength);
						idVal.mv_data(hashIdBb);
						if (mdb_get(txn, dbi, idVal, dataVal) == MDB_SUCCESS
								&& payloadMatchesKey(dataVal.mv_data(), key, languageRange)) {
							// id was found if stored value is equal to requested value
							return data2id(hashIdBb);
						}
					} while (mdb_cursor_get(cursor, hashVal, dataVal, MDB_NEXT) == MDB_SUCCESS);
				}
			} finally {
				if (cursor != 0) {
					mdb_cursor_close(cursor);
				}
			}

			long alternativeId = findAlternativeIriId(data, stack, txn);
			if (alternativeId != LmdbValue.UNKNOWN_ID) {
				return alternativeId;
			}
			if (!create) {
				return null;
			}

			// id was not found, create a new one
			reserveStoredValueCapacity(stack, txn, data);

			long newId = nextId(data[0], coreDatatype);
			writeTransaction((stack2, writeTxn) -> {
				// encode ID
				ByteBuffer idBb = id2data(idBuffer(stack), newId).flip();
				idVal.mv_data(idBb);

				// encode hash and ID
				hashBb.limit(hashBb.capacity());
				hashBb.position(hashLength);
				hashBb.put(idBb);
				idBb.rewind();
				hashBb.flip();
				hashVal.mv_data(hashBb);

				// store mapping of hash+ID -> []
				dataVal.mv_data(stack.bytes());
				E(mdb_put(writeTxn, dbi, hashVal, dataVal, 0));

				dataVal.mv_size(data.length);
				// store mapping of ID -> data
				E(mdb_put(writeTxn, dbi, idVal, dataVal, MDB_RESERVE));
				dataVal.mv_data().put(data);
				retainLegacyLanguageOwnerKey(stack2, writeTxn, data, key, newId);
				recordCompressedValueChange(newId);

				// update ref count if necessary
				incrementRefCount(stack2, writeTxn, data);
				return null;
			});
			return newId;
		}
	}

	/** Resolve the same lexical IRI even when its writer preserved a different namespace/local-name boundary. */
	private long findAlternativeIriId(byte[] data, MemoryStack stack, long txn) throws IOException {
		if (data[0] != URI_VALUE) {
			return LmdbValue.UNKNOWN_ID;
		}
		stack.push();
		try {
			ByteBuffer encoded = ByteBuffer.wrap(data);
			encoded.position(1);
			long namespaceId = Varint.readUnsignedHeap(encoded);
			MDBVal key = MDBVal.malloc(stack);
			key.mv_data(id2data(idBuffer(stack), namespaceId).flip());
			MDBVal namespace = MDBVal.malloc(stack);
			int rc = probeIriAlternative(txn, key, namespace);
			if (rc == MDB_NOTFOUND) {
				throw new IOException("Missing namespace record for IRI namespace ID " + namespaceId);
			}
			E(rc);
			ByteBuffer namespaceData = namespace.mv_data();
			if (!namespaceData.hasRemaining() || namespaceData.get(namespaceData.position()) != NAMESPACE_VALUE) {
				throw new IOException("Invalid namespace record for IRI namespace ID " + namespaceId);
			}
			int namespaceLength = namespaceData.remaining() - 1;
			byte[] lexical = new byte[namespaceLength + encoded.remaining()];
			namespaceData.position(namespaceData.position() + 1);
			namespaceData.get(lexical, 0, namespaceLength);
			encoded.get(lexical, namespaceLength, encoded.remaining());
			return findAlternativeIriId(lexical, namespaceLength, namespaceId, stack, txn);
		} finally {
			stack.pop();
		}
	}

	private long findAlternativeIriId(IRI iri, ValueLookupContext lookup) throws IOException {
		byte[] lexical = iri.stringValue().getBytes(StandardCharsets.UTF_8);
		return readTransaction(env, (stack, txn) -> {
			if (lookup != null) {
				lookup.captureScope(txn);
			}
			return findAlternativeIriId(lexical, -1, LmdbValue.UNKNOWN_ID, stack, txn);
		});
	}

	/**
	 * Short namespace keys form a lexicographic prefix tree in the existing dictionary. A predecessor that is not a
	 * prefix lets us jump straight to its common prefix; a matched namespace lets us continue with a shorter bound.
	 * Long namespace keys are hash indexed. Compute their prefix hashes once, without copying or reencoding prefixes.
	 */
	private long findAlternativeIriId(byte[] lexical, int excludedNamespaceLength, long excludedNamespaceId,
			MemoryStack stack, long txn)
			throws IOException {
		try (AlternativeIriLookup lookup = new AlternativeIriLookup(lexical, stack, txn)) {
			long result = lookup.find(excludedNamespaceLength, excludedNamespaceId);
			lookup.publish();
			return result;
		}
	}

	private static boolean isUtf8Boundary(byte[] lexical, int length) {
		return length == lexical.length || (lexical[length] & 0xC0) != 0x80;
	}

	/** Fixed native buffers and a mutable prefix query belong to one dictionary snapshot, never to a shared cache. */
	private final class AlternativeIriLookup implements AutoCloseable {
		private final byte[] lexical;
		private final long txn;
		private final MemoryStack stack;
		private final MDBVal key;
		private final MDBVal value;
		private MDBVal id;
		private ByteBuffer namespacePrefix;
		private ByteBuffer iriPrefix;
		private ByteBuffer hashKey;
		private ByteBuffer smallKey;
		private ByteBuffer boundKey;
		private PointerBuffer cursorHandle;
		private final CRC32 crc = new CRC32();
		private final Object generation = valueLookupGeneration;
		private final ValueStoreRevision lookupRevision = revision;
		private final ReverseIdCache.State<NamespaceKey> cacheState = namespaceIDCache.state();
		private final Object scope;
		private final NamespaceKey.Prefix namespaceQuery;
		private int namespaceSeparator;
		private boolean namespaceSlashPhase;
		private NamespacePrefixProof reusedProof;
		private int reuseLimit = -1;
		private boolean reused;
		private int examinedFrom;
		private int[] presentLengths;
		private long[] presentIds;
		private int presentCount;
		private long namespaceCursor;
		private long hashCursor;

		private AlternativeIriLookup(byte[] lexical, MemoryStack stack, long txn) {
			this.lexical = lexical;
			this.txn = txn;
			this.stack = stack;
			key = MDBVal.malloc(stack);
			value = MDBVal.malloc(stack);
			scope = valueLookupScope(generation, txn);
			namespaceQuery = scope == null ? null
					: new NamespaceKey.Prefix(lexical, MAX_SHARED_VALUE_CACHE_LEXICAL_CHARS);
			examinedFrom = lexical.length + 1;
			if (namespaceQuery != null) {
				selectNamespaceProof();
			}
		}

		private long find(int excludedNamespaceLength, long excludedNamespaceId) throws IOException {
			int directLimit = MAX_KEY_SIZE - 1;
			if (lexical.length > directLimit) {
				namespacePrefix = stack.bytes(NAMESPACE_VALUE);
				int[] prefixHashes = new int[lexical.length - directLimit];
				crc.update(NAMESPACE_VALUE);
				for (int i = 0; i < lexical.length; i++) {
					crc.update(lexical[i]);
					if (i >= directLimit) {
						prefixHashes[i - directLimit] = (int) crc.getValue();
					}
				}
				int length = lexical.length;
				while (length > directLimit) {
					if (canReuse(length)) {
						long iriId = reuseNamespaces(length, excludedNamespaceLength);
						if (iriId != LmdbValue.UNKNOWN_ID) {
							return iriId;
						}
						length = reusedProof.minimumLength() - 1;
						if (length < 0) {
							return LmdbValue.UNKNOWN_ID;
						}
						continue;
					}
					if (isUtf8Boundary(lexical, length)) {
						long namespaceId = length == excludedNamespaceLength ? excludedNamespaceId
								: findRecord(namespacePrefix, 0, length,
										Integer.toUnsignedLong(prefixHashes[length - directLimit - 1]));
						examinedFrom = Math.min(examinedFrom, length);
						if (namespaceId != LmdbValue.UNKNOWN_ID) {
							recordNamespace(length, namespaceId);
							if (length != excludedNamespaceLength) {
								long iriId = findIri(length, namespaceId);
								if (iriId != LmdbValue.UNKNOWN_ID) {
									return iriId;
								}
							}
						}
					}
					length--;
				}
				if (reused && reusedProof.minimumLength() <= directLimit) {
					return findDirectNamespaces(reusedProof.minimumLength() - 1, excludedNamespaceLength);
				}
			}
			return findDirectNamespaces(Math.min(directLimit, lexical.length), excludedNamespaceLength);
		}

		private long findDirectNamespaces(int bound, int excludedNamespaceLength) throws IOException {
			if (bound < 0) {
				return LmdbValue.UNKNOWN_ID;
			}
			while (bound >= 0) {
				while (!isUtf8Boundary(lexical, bound)) {
					bound--;
				}
				if (canReuse(bound)) {
					long iriId = reuseNamespaces(bound, excludedNamespaceLength);
					if (iriId != LmdbValue.UNKNOWN_ID) {
						return iriId;
					}
					bound = reusedProof.minimumLength() - 1;
					continue;
				}
				if (namespaceCursor == 0) {
					E(mdb_cursor_open(txn, dbi, cursorHandle()));
					namespaceCursor = cursorHandle.get(0);
					boundKey = stack.malloc(MAX_KEY_SIZE);
				}
				boundKey.clear();
				boundKey.put(NAMESPACE_VALUE).put(lexical, 0, bound).flip();
				key.mv_data(boundKey);
				int rc = seekIriAlternative(namespaceCursor, key, value, MDB_SET_RANGE);
				if (rc == MDB_NOTFOUND) {
					rc = seekIriAlternative(namespaceCursor, key, value, MDB_LAST);
				} else {
					E(rc);
					if (key.mv_data().compareTo(boundKey) != 0) {
						rc = seekIriAlternative(namespaceCursor, key, value, MDB_PREV);
					}
				}
				if (rc == MDB_NOTFOUND) {
					examinedFrom = 0;
					return LmdbValue.UNKNOWN_ID;
				}
				E(rc);
				ByteBuffer candidate = key.mv_data();
				int position = candidate.position();
				if (!candidate.hasRemaining() || candidate.get(position) != NAMESPACE_VALUE) {
					examinedFrom = 0;
					return LmdbValue.UNKNOWN_ID;
				}
				int length = candidate.remaining() - 1;
				int common = 0;
				while (common < length && common < lexical.length
						&& candidate.get(position + 1 + common) == lexical[common]) {
					common++;
				}
				if (common == length) {
					long namespaceId = data2id(value.mv_data());
					examinedFrom = Math.min(examinedFrom, length);
					recordNamespace(length, namespaceId);
					if (length != excludedNamespaceLength) {
						long iriId = findIri(length, namespaceId);
						if (iriId != LmdbValue.UNKNOWN_ID) {
							return iriId;
						}
					}
					bound = length - 1;
				} else {
					bound = Math.min(bound - 1, common);
				}
				examinedFrom = Math.min(examinedFrom, bound + 1);
			}
			return LmdbValue.UNKNOWN_ID;
		}

		private boolean cacheIsCurrent() {
			return scope != null && valueLookupGeneration == generation && namespaceIDCache.isCurrent(cacheState)
					&& sameRevision(lookupRevision, revision);
		}

		/** URIUtil's first '#', otherwise last '/', otherwise last ':' rule, then the genuine parent namespaces. */
		private int resetNamespaceBoundaries() {
			namespaceQuery.reset();
			namespaceSeparator = -1;
			for (int i = 0; i < lexical.length; i++) {
				if (lexical[i] == '#') {
					namespaceSeparator = i;
					break;
				}
			}
			namespaceSlashPhase = true;
			if (namespaceSeparator < 0) {
				namespaceSeparator = previousSeparator((byte) '/', lexical.length);
				if (namespaceSeparator < 0) {
					namespaceSlashPhase = false;
					namespaceSeparator = previousSeparator((byte) ':', lexical.length);
				}
			}
			return namespaceSeparator < 0 ? -1 : namespaceSeparator + 1;
		}

		private int nextNamespaceBoundary() {
			int previousBound = namespaceSeparator;
			if (namespaceSlashPhase) {
				namespaceSeparator = previousSeparator((byte) '/', previousBound);
				if (namespaceSeparator < 0) {
					namespaceSlashPhase = false;
					namespaceSeparator = previousSeparator((byte) ':', previousBound);
				}
			} else {
				namespaceSeparator = previousSeparator((byte) ':', previousBound);
			}
			return namespaceSeparator < 0 ? -1 : namespaceSeparator + 1;
		}

		private void selectNamespaceProof() {
			for (int length = resetNamespaceBoundaries(); length >= 0; length = nextNamespaceBoundary()) {
				namespaceQuery.shorten(length);
				if (namespaceQuery.canRetain()) {
					ReverseIdCache.Entry<NamespaceKey> cached = namespaceIDCache.get(cacheState, namespaceQuery,
							ValuePosition.NONE);
					if (cached instanceof NamespaceEntry namespace && namespace.proof != reusedProof
							&& namespace.proof.scope() == scope
							&& sameRevision(cached.revision(), lookupRevision) && cacheIsCurrent()
							&& namespace.proof.covers(length)) {
						int common = namespace.proof.commonPrefixLength(lexical);
						if (common > reuseLimit || common == reuseLimit
								&& namespace.proof.minimumLength() < reusedProof.minimumLength()) {
							reusedProof = namespace.proof;
							reuseLimit = common;
						}
					}
				}
			}
		}

		private int previousSeparator(byte separator, int exclusiveEnd) {
			for (int i = exclusiveEnd - 1; i >= 0; i--) {
				if (lexical[i] == separator) {
					return i;
				}
			}
			return -1;
		}

		private boolean canReuse(int length) {
			return !reused && reusedProof != null && length <= reuseLimit && reusedProof.covers(length)
					&& cacheIsCurrent();
		}

		private long reuseNamespaces(int upperLength, int excludedNamespaceLength) throws IOException {
			reused = true;
			examinedFrom = Math.min(examinedFrom, reusedProof.minimumLength());
			// Record every present answer before a URI match can return early. The proof already examined this
			// whole interval in this exact native snapshot, including its shorter prefixes.
			int firstNew = presentCount;
			for (int i = 0; i < reusedProof.presentCount(); i++) {
				int length = reusedProof.presentLength(i);
				if (length <= upperLength) {
					recordNamespace(length, reusedProof.presentId(i));
				}
			}
			for (int i = firstNew; i < presentCount; i++) {
				if (presentLengths[i] != excludedNamespaceLength) {
					long iriId = findIri(presentLengths[i], presentIds[i]);
					if (iriId != LmdbValue.UNKNOWN_ID) {
						return iriId;
					}
				}
			}
			return LmdbValue.UNKNOWN_ID;
		}

		private void recordNamespace(int length, long namespaceId) {
			if (namespaceQuery == null) {
				return;
			}
			assert presentCount == 0 || presentLengths[presentCount - 1] > length;
			if (presentLengths == null) {
				presentLengths = new int[4];
				presentIds = new long[4];
			} else if (presentCount == presentLengths.length) {
				presentLengths = Arrays.copyOf(presentLengths, presentCount * 2);
				presentIds = Arrays.copyOf(presentIds, presentCount * 2);
			}
			presentLengths[presentCount] = length;
			presentIds[presentCount++] = namespaceId;
		}

		private void publish() {
			if (namespaceQuery == null || !cacheIsCurrent()) {
				return;
			}
			int length = resetNamespaceBoundaries();
			if (length < 0 || valueLookupScope(generation, txn) != scope) {
				return;
			}
			int retainedLimit = namespaceQuery.retainedByteLength();
			if (examinedFrom > retainedLimit) {
				return;
			}
			NamespacePrefixProof proof = NamespacePrefixProof.copyOf(lexical, retainedLimit, examinedFrom,
					presentLengths, presentIds, presentCount, scope);
			for (; length >= 0; length = nextNamespaceBoundary()) {
				if (!cacheIsCurrent()) {
					return;
				}
				namespaceQuery.shorten(length);
				if (namespaceQuery.canRetain() && proof.covers(length)) {
					ReverseIdCache.Entry<NamespaceKey> cached = namespaceIDCache.get(cacheState, namespaceQuery,
							ValuePosition.NONE);
					NamespaceKey retained = cached == null ? namespaceQuery.retainedKey() : cached.key();
					long namespaceId = proof.namespaceId(length);
					namespaceIDCache.putEntry(cacheState, new NamespaceEntry(retained, namespaceId,
							lookupRevision, namespaceId == LmdbValue.UNKNOWN_ID ? scope : null, proof),
							ValuePosition.NONE);
				}
			}
		}

		private long findIri(int namespaceLength, long namespaceId) throws IOException {
			if (iriPrefix == null) {
				iriPrefix = stack.malloc(1 + MAX_UNSIGNED_ID_BYTES);
			}
			iriPrefix.clear().put(URI_VALUE);
			Varint.writeUnsigned(iriPrefix, namespaceId);
			iriPrefix.flip();
			crc.reset();
			for (int i = 0; i < iriPrefix.remaining(); i++) {
				crc.update(iriPrefix.get(i));
			}
			int suffixLength = lexical.length - namespaceLength;
			// Each existing namespace requires its own encoded IRI hash: dense prefix dictionaries can have a
			// quadratic sum of suffix lengths, while namespace prefix hashing and the probe count stay linear.
			crc.update(lexical, namespaceLength, suffixLength);
			return findRecord(iriPrefix, namespaceLength, suffixLength, crc.getValue());
		}

		private long findRecord(ByteBuffer prefix, int offset, int length, long hash) throws IOException {
			int recordLength = prefix.remaining() + length;
			if (recordLength <= MAX_KEY_SIZE) {
				if (smallKey == null) {
					smallKey = stack.malloc(MAX_KEY_SIZE);
				}
				smallKey.clear();
				for (int i = prefix.position(); i < prefix.limit(); i++) {
					smallKey.put(prefix.get(i));
				}
				smallKey.put(lexical, offset, length).flip();
				key.mv_data(smallKey);
				int rc = probeIriAlternative(txn, key, value);
				if (rc == MDB_NOTFOUND) {
					return LmdbValue.UNKNOWN_ID;
				}
				E(rc);
				return data2id(value.mv_data());
			}
			if (hashKey == null) {
				hashKey = stack.malloc(2 + 2 * Long.BYTES + 2);
			}
			hashKey.clear().put(HASH_KEY);
			Varint.writeUnsigned(hashKey, hash);
			hashKey.flip();
			int hashLength = hashKey.remaining();
			key.mv_data(hashKey);
			int rc = probeIriAlternative(txn, key, value);
			if (rc == MDB_NOTFOUND) {
				return LmdbValue.UNKNOWN_ID;
			}
			E(rc);
			if (id == null) {
				id = MDBVal.malloc(stack);
			}
			id.mv_data(value.mv_data());
			rc = probeIriAlternative(txn, id, value);
			if (rc != MDB_NOTFOUND) {
				E(rc);
				if (matchesAlternativeRecord(value.mv_data(), prefix, lexical, offset, length)) {
					return data2id(id.mv_data());
				}
			}
			hashKey.put(0, HASHID_KEY);
			key.mv_data(hashKey);
			if (hashCursor == 0) {
				E(mdb_cursor_open(txn, dbi, cursorHandle()));
				hashCursor = cursorHandle.get(0);
			}
			rc = seekIriAlternative(hashCursor, key, value, MDB_SET_RANGE);
			while (rc != MDB_NOTFOUND) {
				E(rc);
				ByteBuffer candidate = key.mv_data();
				if (candidate.remaining() < hashLength || compareRegion(candidate, 0, hashKey, 0, hashLength) != 0) {
					break;
				}
				ByteBuffer candidateId = candidate.duplicate();
				candidateId.position(hashLength);
				id.mv_data(candidateId);
				int candidateRc = probeIriAlternative(txn, id, value);
				if (candidateRc != MDB_NOTFOUND) {
					E(candidateRc);
					if (matchesAlternativeRecord(value.mv_data(), prefix, lexical, offset, length)) {
						return data2id(candidateId);
					}
				}
				rc = seekIriAlternative(hashCursor, key, value, MDB_NEXT);
			}
			return LmdbValue.UNKNOWN_ID;
		}

		private PointerBuffer cursorHandle() {
			if (cursorHandle == null) {
				cursorHandle = stack.mallocPointer(1);
			}
			return cursorHandle;
		}

		@Override
		public void close() {
			if (namespaceCursor != 0) {
				mdb_cursor_close(namespaceCursor);
			}
			if (hashCursor != 0) {
				mdb_cursor_close(hashCursor);
			}
		}
	}

	private static final class NamespaceEntry extends ReverseIdCache.Entry<NamespaceKey> {
		private final NamespacePrefixProof proof;

		private NamespaceEntry(NamespaceKey key, long id, ValueStoreRevision revision, Object negativeScope,
				NamespacePrefixProof proof) {
			super(key, id, key.spellingHash(), revision, negativeScope);
			this.proof = proof;
		}
	}

	private static boolean matchesAlternativeRecord(ByteBuffer record, ByteBuffer prefix, byte[] lexical, int offset,
			int length) {
		int prefixLength = prefix.remaining();
		if (record.remaining() != prefixLength + length) {
			return false;
		}
		for (int i = 0; i < prefixLength; i++) {
			if (record.get(record.position() + i) != prefix.get(prefix.position() + i)) {
				return false;
			}
		}
		for (int i = 0; i < length; i++) {
			if (record.get(record.position() + prefixLength + i) != lexical[offset + i]) {
				return false;
			}
		}
		return true;
	}

	int probeIriAlternative(long txn, MDBVal key, MDBVal value) {
		return mdb_get(txn, dbi, key, value);
	}

	int seekIriAlternative(long cursor, MDBVal key, MDBVal value, int operation) {
		return mdb_cursor_get(cursor, key, value, operation);
	}

	private void findIds(byte[][] data, CoreDatatype[] coreDatatypes, int[] indexes, long[] ids, int count)
			throws IOException {
		findIdsCaptured(data, coreDatatypes, indexes, ids, count);
	}

	/**
	 * Reserves the complete encoded dictionary batch before either batch writer is entered. The encoded values already
	 * contain their namespace/datatype IDs; pending reference deltas and the next-ID record are included in the same
	 * footprint so a checkpoint cannot split this operation.
	 */
	private void reserveBatchValueCapacity(MemoryStack stack, long txn, byte[][] data, int count) throws IOException {
		if (!autoGrow || count == 0) {
			return;
		}

		PreparedValueFootprint footprint = new PreparedValueFootprint();
		for (int i = 0; i < count; i++) {
			byte[] value = data[i];
			footprint.addStoredRecord(value.length, pageSize);
			addLegacyLanguageOwnerKeyReservation(footprint, value);
			if (value.length > 0 && (value[0] == LITERAL_VALUE || value[0] == URI_VALUE)) {
				footprint.addReference();
			}
		}
		addNextIdFootprint(footprint);
		addPendingRefCountFootprint(footprint);
		if (footprint.referencePuts > 0) {
			// The normal store has already opened this DB, but include its catalog descriptor in the conservative batch
			// footprint for the same commit metadata accounted for by fresh-value reservation.
			footprint.addNamedDatabase("ref_counts");
		}

		resizeForAllocation(txn, preparedValueReservation(stack, txn, footprint));
	}

	private int[] sortedStoreOrder(byte[][] data, int count) {
		int[] order = new int[count];
		long[] primaryStoreKeys = new long[count];
		long[] secondaryStoreKeys = new long[count];
		for (int i = 0; i < count; i++) {
			order[i] = i;
			primaryStoreKeys[i] = primaryStoreSortKey(data[i]);
			secondaryStoreKeys[i] = secondaryStoreSortKey(data[i]);
		}
		int[] scratchOrder = new int[count];
		long[] scratchKeys = new long[count];
		int[] counts = new int[256];
		int[] offsets = new int[256];
		LeadingFieldSorters.lsdRadixSort(order, secondaryStoreKeys, count, scratchOrder, scratchKeys, counts,
				offsets);
		for (int i = 0; i < count; i++) {
			primaryStoreKeys[i] = primaryStoreSortKey(data[order[i]]);
		}
		LeadingFieldSorters.lsdRadixSort(order, primaryStoreKeys, count, scratchOrder, scratchKeys, counts, offsets);
		return order;
	}

	private long primaryStoreSortKey(byte[] data) {
		if (data.length <= MAX_KEY_SIZE) {
			return leadingStoreKey(data, 0);
		}
		return ((long) HASH_KEY << 56) | hash(data);
	}

	private long secondaryStoreSortKey(byte[] data) {
		if (data.length <= MAX_KEY_SIZE) {
			return leadingStoreKey(data, Long.BYTES);
		}
		return 0;
	}

	private long leadingStoreKey(byte[] data, int offset) {
		if (offset >= data.length) {
			return 0;
		}
		long key = 0;
		int length = Math.min(data.length - offset, Long.BYTES);
		for (int i = 0; i < length; i++) {
			key = (key << Byte.SIZE) | (data[offset + i] & 0xFFL);
		}
		return key << ((Long.BYTES - length) * Byte.SIZE);
	}

	private long currentWriteTxn(long fallbackTxn) {
		return writeTxn != 0 ? writeTxn : fallbackTxn;
	}

	private boolean bufferEquals(ByteBuffer buffer, byte[] data) {
		if (buffer.remaining() != data.length) {
			return false;
		}
		int position = buffer.position();
		for (int i = 0; i < data.length; i++) {
			if (buffer.get(position + i) != data[i]) {
				return false;
			}
		}
		return true;
	}

	private boolean matchesLookupKey(ByteBuffer stored, byte[] lookup) {
		return payloadMatchesKey(stored, lookup, lookupLanguageRange(lookup));
	}

	private void findIdsCaptured(byte[][] data, CoreDatatype[] coreDatatypes, int[] indexes, long[] ids, int count)
			throws IOException {
		// Keep the branch's key-local batch order without retaining native cursors across a resize checkpoint.
		byte[][] keys = lookupKeys(data, count);
		int[] order = count > 1 ? sortedStoreOrder(keys, count) : null;
		long[] hashes = new long[count];
		for (int i = 0; i < count; i++) {
			hashes[i] = data[i].length > MAX_KEY_SIZE ? hash(keys[i]) : 0L;
		}
		readTransaction(env, (stack, admitted) -> {
			// Complete the whole-batch capacity reservation in the same owned callback before any native lookup.
			// It can checkpoint the writer; each row below therefore obtains the current handle again.
			reserveBatchValueCapacity(stack, admitted, data, count);
			// Cursor-free on purpose: a tracked decision may resize the map in place while allocating, which
			// commits and restarts the writer transaction. Only Java-owned bytes and freshly re-read handles
			// survive that boundary, so every row re-reads writeTxn and nothing native is retained across rows.
			MDBVal keyVal = MDBVal.calloc(stack);
			MDBVal idVal = MDBVal.calloc(stack);
			MDBVal dataVal = MDBVal.calloc(stack);
			ByteBuffer idBytes = idBuffer(stack);
			ByteBuffer hashBytes = stack.malloc(2 + 2 * Long.BYTES + 2);
			for (int position = 0; position < count; position++) {
				int index = order == null ? position : order[position];
				byte[] encoded = data[index];
				byte[] lookup = keys[index];
				boolean hashed = encoded.length > MAX_KEY_SIZE;
				stack.push();
				try {
					long txn = writeTxn != 0 ? writeTxn : admitted;
					idVal.clear();
					dataVal.clear();
					if (hashed) {
						hashBytes.clear();
						hashBytes.put(HASH_KEY);
						Varint.writeUnsigned(hashBytes, hashes[index]);
						keyVal.mv_data(hashBytes.flip());
					} else {
						keyVal.mv_data(stack.bytes(lookup));
					}
					if (mdb_get(txn, dbi, keyVal, idVal) == MDB_SUCCESS) {
						// Copy the ID before another native operation. Returned MDBVal data belongs to LMDB.
						long found = data2id(idVal.mv_data());
						if (!hashed || mdb_get(txn, dbi, idVal, dataVal) == MDB_SUCCESS
								&& matchesLookupKey(dataVal.mv_data(), lookup)) {
							ids[indexes[index]] = found;
							continue;
						}
						// Collision scans and HASHID_KEY allocation retain their authoritative scalar path.
						ids[indexes[index]] = findId(encoded, true, coreDatatypes[index]);
						continue;
					}
					resizeForAllocation(txn, 2L * encoded.length + 2L * (2L + Long.BYTES));
					long alternativeId = findAlternativeIriId(encoded, stack, txn);
					if (alternativeId != LmdbValue.UNKNOWN_ID) {
						ids[indexes[index]] = alternativeId;
						continue;
					}
					long id = nextId(encoded[0], coreDatatypes[index]);
					writeTransaction((writeStack, activeTxn) -> {
						idBytes.clear();
						idVal.mv_data(id2data(idBytes, id).flip());
						E(mdb_put(activeTxn, dbi, keyVal, idVal, 0));
						if (hashed) {
							dataVal.mv_size(encoded.length);
							E(mdb_put(activeTxn, dbi, idVal, dataVal, MDB_RESERVE));
							dataVal.mv_data().put(encoded);
						} else {
							MDBVal encodedVal = lookup == encoded ? keyVal
									: MDBVal.calloc(writeStack).mv_data(writeStack.bytes(encoded));
							E(mdb_put(activeTxn, dbi, idVal, encodedVal, 0));
						}
						retainLegacyLanguageOwnerKey(writeStack, activeTxn, encoded, lookup, id);
						recordCompressedValueChange(id);
						incrementRefCount(writeStack, activeTxn, encoded);
						return null;
					});
					ids[indexes[index]] = id;
				} finally {
					stack.pop();
				}
			}
			return null;
		});
	}

	private LmdbTripleTerm id2tripleTerm(long id, LmdbTripleTerm value) throws IOException {
		return id2tripleTerm(id, value, currentReadRevision(id));
	}

	private LmdbTripleTerm id2tripleTerm(long id, LmdbTripleTerm value, ValueStoreRevision valueRevision)
			throws IOException {
		return readTransaction(env, (stack, txn) -> {
			final var index = tripleTermCspoIndex;

			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, index.getDB(true), pp));
			long cursor = pp.get(0);
			try {
				if (tripleTermCursorObserver != null) {
					tripleTermCursorObserver.accept(1);
				}

				MDBVal keyVal = MDBVal.malloc(stack);
				// use calloc to get an empty data value
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				index.getMinKey(keyBuf, -1, -1, -1, id);
				keyBuf.flip();
				keyVal.mv_data(keyBuf);

				int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
				if (rc == MDB_SUCCESS && index.createMatcher(-1, -1, -1, id).matches(keyVal.mv_data())) {
					long[] quad = new long[4];
					index.keyToQuad(keyVal.mv_data(), quad);
					if (value != null) {
						value.setFromInitializedValue(new LmdbTripleTerm(completedRevision(valueRevision),
								(Resource) getLazyValue(quad[0], valueRevision),
								(IRI) getLazyValue(quad[1], valueRevision), getLazyValue(quad[2], valueRevision), id));
						return value;
					} else {
						return new LmdbTripleTerm(completedRevision(valueRevision),
								(Resource) getLazyValue(quad[0], valueRevision),
								(IRI) getLazyValue(quad[1], valueRevision), getLazyValue(quad[2], valueRevision), id);
					}
				}
				return null;
			} finally {
				mdb_cursor_close(cursor);
				if (tripleTermCursorObserver != null) {
					tripleTermCursorObserver.accept(-1);
				}
			}
		});
	}

	private LmdbTripleTerm id2tripleTerm(ReadSnapshot snapshot, long txn, long id, LmdbTripleTerm value)
			throws IOException {
		snapshot.ensureValid();
		final TripleIndex index = tripleTermCspoIndex;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, index.getDB(true), pp));
			long cursor = pp.get(0);
			try {
				MDBVal keyVal = MDBVal.malloc(stack);
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				index.getMinKey(keyBuf, -1, -1, -1, id);
				keyBuf.flip();
				keyVal.mv_data(keyBuf);

				int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
				if (rc != MDB_SUCCESS || !index.createMatcher(-1, -1, -1, id).matches(keyVal.mv_data())) {
					return null;
				}
				long[] quad = new long[4];
				index.keyToQuad(keyVal.mv_data(), quad);
				LmdbTripleTerm decoded = new LmdbTripleTerm(snapshot.completedRevision(),
						(Resource) getLazyValue(snapshot, quad[0]),
						(IRI) getLazyValue(snapshot, quad[1]),
						getLazyValue(snapshot, quad[2]), id);
				if (value != null) {
					value.setFromInitializedValue(decoded);
					return value;
				}
				return decoded;
			} finally {
				mdb_cursor_close(cursor);
			}
		}
	}

	long findTripleTermId(long subj, long pred, long obj, boolean create) throws IOException {
		return findTripleTermId(subj, pred, obj, create, null);
	}

	private long findTripleTermId(long subj, long pred, long obj, boolean create, ValueLookupContext lookup)
			throws IOException {
		if (create && writeTxn != 0 && !isWriteTransactionOwner()) {
			return withWriterLookupContext((stack, txn) -> findTripleTermId(subj, pred, obj, true, lookup));
		}
		return readTransaction(env, (stack, txn) -> {
			if (lookup != null) {
				lookup.captureScope(txn);
			}
			final TripleIndex mainIndex = tripleTermSpocIndex;

			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, mainIndex.getDB(true), pp));
			long cursor = pp.get(0);
			if (tripleTermCursorObserver != null) {
				tripleTermCursorObserver.accept(1);
			}
			try {
				MDBVal keyVal = MDBVal.malloc(stack);
				// use calloc to get an empty data value
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				mainIndex.getMinKey(keyBuf, subj, pred, obj, -1);
				keyBuf.flip();
				keyVal.mv_data(keyBuf);

				int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
				if (rc == MDB_SUCCESS && mainIndex.createMatcher(subj, pred, obj, -1).matches(keyVal.mv_data())) {
					var bb = keyVal.mv_data();
					return Varint.readUnsigned(bb, Varint.calcLengthUnsigned(subj) + Varint.calcLengthUnsigned(pred) +
							Varint.calcLengthUnsigned(obj));
				}

				if (!create) {
					return LmdbValue.UNKNOWN_ID;
				}
			} finally {
				mdb_cursor_close(cursor);
				if (tripleTermCursorObserver != null) {
					tripleTermCursorObserver.accept(-1);
				}
			}

			// The lookup cursor is closed before reserving the complete RDF-star operation. A resize may checkpoint and
			// replace the active writer, so reservation must finish before the mutation callback captures its handle.
			reserveTripleTermCapacity(stack, txn);
			return writeTransaction((stack2, writeTxn) -> {
				incrementRefCount(stack2, writeTxn, subj);
				incrementRefCount(stack2, writeTxn, pred);
				incrementRefCount(stack2, writeTxn, obj);

				long id = nextId(TRIPLE_VALUE);
				MDBVal keyVal = MDBVal.malloc(stack2);
				MDBVal dataVal = MDBVal.calloc(stack2);
				ByteBuffer keyBuf = stack2.malloc(TripleIndex.MAX_KEY_LENGTH);
				for (TripleIndex index : tripleTermIndexes) {
					keyBuf.clear();
					index.toKey(keyBuf, subj, pred, obj, id);
					keyVal.mv_data(keyBuf.flip());
					E(mdb_put(writeTxn, index.getDB(true), keyVal, dataVal, 0));
				}
				return id;
			});
		});
	}

	private long findTripleTermId(ReadSnapshot snapshot, long txn, long subj, long pred, long obj) throws IOException {
		if (snapshot != null) {
			snapshot.ensureValid();
		}
		try (MemoryStack stack = stackPush()) {
			final TripleIndex mainIndex = tripleTermSpocIndex;
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, mainIndex.getDB(true), pp));
			long cursor = pp.get(0);
			try {
				MDBVal keyVal = MDBVal.malloc(stack);
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				mainIndex.getMinKey(keyBuf, subj, pred, obj, -1);
				keyVal.mv_data(keyBuf.flip());
				int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
				if (rc == MDB_SUCCESS && mainIndex.createMatcher(subj, pred, obj, -1).matches(keyVal.mv_data())) {
					ByteBuffer found = keyVal.mv_data();
					return Varint.readUnsigned(found, Varint.calcLengthUnsigned(subj)
							+ Varint.calcLengthUnsigned(pred) + Varint.calcLengthUnsigned(obj));
				}
				return LmdbValue.UNKNOWN_ID;
			} finally {
				mdb_cursor_close(cursor);
			}
		}
	}

	/** Finds a value ID in the supplied dictionary generation without consulting mutable ValueStore caches. */
	long getId(ReadSnapshot snapshot, Value value, int positionMask) throws IOException {
		ValuePosition.validateMask(positionMask);
		return getId(snapshot, value);
	}

	long getStatementId(ReadSnapshot snapshot, Value value, int positionMask) throws IOException {
		ValuePosition.validateMask(positionMask);
		return getStatementId(snapshot, value);
	}

	long getId(ReadSnapshot snapshot, Value value) throws IOException {
		snapshot.ensureValid();
		if (snapshot.valueStore() != this) {
			throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
		}
		if (value instanceof PreparedLmdbValue.Prepared prepared) {
			return snapshot.valuePreparer.resolve(prepared);
		}
		long knownId = knownSnapshotId(snapshot, value);
		if (knownId != LmdbValue.UNKNOWN_ID) {
			return knownId;
		}
		long cachedId = snapshot.cachedLookup(value);
		if (cachedId != LmdbValue.UNKNOWN_ID) {
			return cachedId;
		}
		// Caller getters may initialize escaped lazy values, which borrow a paired native transaction. Capture
		// lexical fields and nested components before either the native barrier or the transaction monitor.
		SnapshotValueLookup lookup = captureSnapshotLookup(snapshot, value);
		SnapshotLookupKey lookupKey = snapshot.canCacheLookup() ? snapshotLookupKey(lookup) : null;
		long stamp;
		try {
			stamp = txnManager.lockManager().readLock();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException("Interrupted while looking up a ValueStore snapshot value", e);
		}
		try {
			synchronized (snapshot.txnRef()) {
				snapshot.ensureValid();
				if (!snapshot.dictionaryDetached()) {
					long id = getId(snapshot, snapshot.txnRef().get(), lookup);
					snapshot.cacheLookup(value, lookupKey, id);
					return id;
				}
			}
		} finally {
			txnManager.lockManager().unlockRead(stamp);
		}
		return readTransaction(env, (stack, txn) -> getId(snapshot, txn, lookup));
	}

	/**
	 * Resolves an input for the paired statement index. The pinned triple reader filters later appended IDs; its epoch
	 * reservation prevents ID reuse. Dictionary enumeration and point lookup use the stricter getId contract.
	 */
	long getStatementId(ReadSnapshot snapshot, Value value) throws IOException {
		if (snapshot.valueStore() != this) {
			throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
		}
		if (value instanceof PreparedLmdbValue.Prepared prepared) {
			PreparedLmdbValue.State state = prepared.state();
			if (state.owner == snapshot.preparationOwner) {
				PreparedLmdbValue.Proof proof = state.proof;
				if (proof.generation() == snapshot.preparationGeneration && proof.generation().live) {
					// The caller admitted this snapshot for the whole lookup; a live statement proof is final.
					return proof.identity().id();
				}
			}
			// The preparer validates and admits the snapshot once while resolving the prepared identity.
			return snapshot.valuePreparer.resolve(prepared, true);
		}
		snapshot.ensureValid();
		if (value instanceof LmdbValue nativeValue && nativeValue.getSemanticVersion() != LmdbValue.UNKNOWN_ID) {
			long id = knownStatementId(snapshot, nativeValue.getInternalIdentity());
			if (id != LmdbValue.UNKNOWN_ID) {
				return id;
			}
		}
		return getId(snapshot, value);
	}

	private long knownStatementId(ReadSnapshot snapshot, LmdbValue.InternalIdentity identity) throws IOException {
		snapshot.ensureValid();
		return knownStatementIdAdmitted(snapshot, identity);
	}

	/** As {@link #knownStatementId} for a caller that validated the snapshot itself and re-validates afterwards. */
	private long knownStatementIdAdmitted(ReadSnapshot snapshot, LmdbValue.InternalIdentity identity) {
		ValueStoreRevision.Lazy paired = snapshot.stableRevision;
		ValueEpoch epoch = paired == null ? null : paired.idEpoch();
		if (identity.id() == LmdbValue.UNKNOWN_ID || identity.revision().getValueStore() != this
				|| !snapshot.hasStableIds() || epoch == null || !epoch.protectedIds
				|| !completedRevision(identity.revision()).equals(snapshot.completedRevision())) {
			return LmdbValue.UNKNOWN_ID;
		}
		ensureAssociationReadable(identity.revision());
		if (identity.revision() instanceof ValueStoreRevision.Lazy lazy && lazy.association() != null
				&& lazy.association().state != NativeValueAssociation.State.COMMITTED) {
			return LmdbValue.UNKNOWN_ID;
		}
		return identity.id();
	}

	private long knownSnapshotId(ReadSnapshot snapshot, Value value) throws IOException {
		if (snapshot != null && value instanceof LmdbValue lmdbValue
				&& lmdbValue.getSemanticVersion() != LmdbValue.UNKNOWN_ID) {
			return knownSnapshotId(snapshot, lmdbValue.getInternalIdentity());
		}
		return LmdbValue.UNKNOWN_ID;
	}

	private long knownSnapshotId(ReadSnapshot snapshot, LmdbValue.InternalIdentity identity) throws IOException {
		if (identity.id() != LmdbValue.UNKNOWN_ID && identity.revision().getValueStore() == this
				&& completedRevision(identity.revision()).equals(snapshot.completedRevision())) {
			long stamp = txnManager.acquireReadBarrier();
			try {
				synchronized (snapshot.txnRef()) {
					snapshot.ensureValid();
					// A shared epoch can include ready values appended after this native reader began.
					// An already-present same-epoch ID keeps its association; later absent IDs need lexical lookup.
					if (!snapshot.hasStableIds() || snapshot.dictionaryDetached()
							|| ValueIds.isInlined(identity.id())
							|| containsValueId(snapshot.txnRef().get(), identity.id())) {
						return identity.id();
					}
				}
			} finally {
				txnManager.lockManager().unlockRead(stamp);
			}
		}
		return LmdbValue.UNKNOWN_ID;
	}

	/** Checks native resolution membership without decoding values or invoking caller/model getters. */
	private boolean containsValueId(long txn, long id) throws IOException {
		try (MemoryStack stack = stackPush()) {
			MDBVal key = MDBVal.malloc(stack);
			MDBVal data = MDBVal.calloc(stack);
			if (ValueIds.getIdType(id) != ValueIds.T_TRIPLE) {
				key.mv_data(id2data(idBuffer(stack), id).flip());
				int rc = mdb_get(txn, dbi, key, data);
				if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
					E(rc);
				}
				return rc == MDB_SUCCESS;
			}
			TripleIndex index = tripleTermCspoIndex;
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, index.getDB(true), pointer));
			long cursor = pointer.get(0);
			try {
				ByteBuffer keyBuffer = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				index.getMinKey(keyBuffer, -1, -1, -1, id);
				key.mv_data(keyBuffer.flip());
				int rc = mdb_cursor_get(cursor, key, data, MDB_SET_RANGE);
				if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
					E(rc);
				}
				return rc == MDB_SUCCESS && Varint.readUnsigned(key.mv_data()) == id;
			} finally {
				mdb_cursor_close(cursor);
			}
		}
	}

	private long findLegacyLiteralInTransaction(MemoryStack stack, long txn, Literal requested) throws IOException {
		PointerBuffer pointer = stack.mallocPointer(1);
		E(mdb_cursor_open(txn, dbi, pointer));
		long cursor = pointer.get(0);
		long visited = 0L;
		try {
			MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(new byte[] { ID_KEY }));
			MDBVal value = MDBVal.calloc(stack);
			for (int rc = mdb_cursor_get(cursor, key, value, MDB_SET_RANGE); rc == MDB_SUCCESS
					&& isIdKey(key.mv_data()); rc = mdb_cursor_get(cursor, key, value, MDB_NEXT)) {
				visited++;
				long id = data2id(key.mv_data().duplicate());
				if (ValueIds.getIdType(id) != ValueIds.T_LITERAL) {
					continue;
				}
				byte[] data = copyValue(value);
				if (!isLiveReverseOwner(stack, txn, id, data)) {
					continue;
				}
				ByteBuffer record = ByteBuffer.wrap(data);
				record.get();
				Varint.readUnsignedHeap(record);
				int tag = record.get() & 0xFF;
				int direction = tag >>> 6;
				int length = direction == 3 ? Math.toIntExact(Varint.readUnsignedHeap(record)) : tag & 0x3F;
				if (direction == 3) {
					direction = tag & 0x3F;
				}
				if (length == 0) {
					continue;
				}
				String language = new String(data, record.position(), length, StandardCharsets.UTF_8);
				String label = new String(data, record.position() + length,
						data.length - record.position() - length, StandardCharsets.UTF_8);
				Literal.BaseDirection base = direction == 1 ? Literal.BaseDirection.LTR
						: direction == 2 ? Literal.BaseDirection.RTL : Literal.BaseDirection.NONE;
				if (requested.equals(createLiteral(label, language, base))) {
					return id;
				}
			}
			return LmdbValue.UNKNOWN_ID;
		} finally {
			mdb_cursor_close(cursor);
			observeLegacySemanticScan(visited);
		}
	}

	/** Resolves only already-captured fields within the caller's admitted dictionary transaction. */
	private long findLegacyLiteralInTransaction(long txn, SnapshotLiteral literal) throws IOException {
		if (!format.isLegacy() || languageTagKeyMode != LanguageTagKeyMode.CANONICAL
				|| literal.languageData() == null) {
			return LmdbValue.UNKNOWN_ID;
		}
		Literal requested = createLiteral(new String(literal.labelData(), StandardCharsets.UTF_8),
				new String(literal.languageData(), StandardCharsets.UTF_8), literal.baseDirection());
		try (MemoryStack stack = stackPush()) {
			return findLegacyLiteralInTransaction(stack, txn, requested);
		}
	}

	private SnapshotValueLookup captureSnapshotLookup(ReadSnapshot snapshot, Value value) throws IOException {
		if (snapshot != null && value instanceof PreparedLmdbValue.Prepared prepared) {
			return new SnapshotKnownId(snapshot.valuePreparer.resolve(prepared));
		}
		long knownId = knownSnapshotId(snapshot, value);
		if (knownId != LmdbValue.UNKNOWN_ID) {
			return new SnapshotKnownId(knownId);
		}
		if (value.isTripleTerm()) {
			TripleTerm tripleTerm = (TripleTerm) value;
			return new SnapshotTriple(captureSnapshotLookup(snapshot, tripleTerm.getSubject()),
					captureSnapshotLookup(snapshot, tripleTerm.getPredicate()),
					captureSnapshotLookup(snapshot, tripleTerm.getObject()));
		}
		if (value instanceof Literal literal
				&& !(format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
						&& LegacySemanticScope.containsLanguage(value))) {
			long packed = format.tryInline(literal);
			if (packed != LmdbValue.UNKNOWN_ID) {
				return new SnapshotKnownId(packed);
			}
		}

		return switch (value.getType()) {
		case Value.Type.IRI -> {
			IRI iri = (IRI) value;
			byte[] namespaceBytes = iri.getNamespace().getBytes(StandardCharsets.UTF_8);
			byte[] namespaceData = new byte[namespaceBytes.length + 1];
			namespaceData[0] = NAMESPACE_VALUE;
			System.arraycopy(namespaceBytes, 0, namespaceData, 1, namespaceBytes.length);
			yield new SnapshotIRI(namespaceData, iri.getLocalName().getBytes(StandardCharsets.UTF_8));
		}
		case Value.Type.BNode -> new SnapshotEncodedValue(bnode2data((BNode) value, false));
		case Value.Type.Literal -> {
			Literal literal = (Literal) value;
			IRI datatype = literal.getDatatype();
			yield new SnapshotLiteral(datatype == null ? null : captureSnapshotLookup(snapshot, datatype),
					literal.getLabel().getBytes(StandardCharsets.UTF_8),
					canonicalLanguage(literal.getLanguage()).map(s -> s.getBytes(StandardCharsets.UTF_8)).orElse(null),
					literal.getBaseDirection());
		}
		default -> throw new IllegalArgumentException("value parameter should be a URI, BNode or Literal");
		};
	}

	private sealed interface SnapshotValueLookup {
	}

	private record SnapshotKnownId(long id) implements SnapshotValueLookup {
	}

	private record SnapshotEncodedValue(byte[] data) implements SnapshotValueLookup {
	}

	private record SnapshotIRI(byte[] namespaceData, byte[] localNameData) implements SnapshotValueLookup {
	}

	private record SnapshotLiteral(SnapshotValueLookup datatype, byte[] labelData, byte[] languageData,
			Literal.BaseDirection baseDirection) implements SnapshotValueLookup {
	}

	private record SnapshotTriple(SnapshotValueLookup subject, SnapshotValueLookup predicate,
			SnapshotValueLookup object)
			implements SnapshotValueLookup {
	}

	/**
	 * Builds a lexical fingerprint from the same owned fields used by the native miss, without calling the caller
	 * again. Known-ID components are deliberately not decoded just to populate an optional memo.
	 */
	private static SnapshotLookupKey snapshotLookupKey(SnapshotValueLookup lookup) {
		return switch (lookup) {
		case SnapshotKnownId ignored -> null;
		case SnapshotIRI iri -> new SnapshotIRIKey(
				new String(iri.namespaceData(), 1, iri.namespaceData().length - 1, StandardCharsets.UTF_8)
						+ new String(iri.localNameData(), StandardCharsets.UTF_8));
		case SnapshotEncodedValue encoded -> encoded.data()[0] == BNODE_VALUE
				? new SnapshotBNodeKey(new String(encoded.data(), 1, encoded.data().length - 1, StandardCharsets.UTF_8))
				: null;
		case SnapshotLiteral literal -> {
			SnapshotLookupKey datatype = literal.datatype() == null ? null : snapshotLookupKey(literal.datatype());
			yield literal.datatype() != null && datatype == null ? null
					: new SnapshotLiteralKey(datatype, new String(literal.labelData(), StandardCharsets.UTF_8),
							literal.languageData() == null ? null
									: new String(literal.languageData(), StandardCharsets.UTF_8),
							literal.baseDirection());
		}
		case SnapshotTriple triple -> {
			SnapshotLookupKey subject = snapshotLookupKey(triple.subject());
			SnapshotLookupKey predicate = snapshotLookupKey(triple.predicate());
			SnapshotLookupKey object = snapshotLookupKey(triple.object());
			yield subject == null || predicate == null || object == null ? null
					: new SnapshotTripleKey(subject, predicate, object);
		}
		};
	}

	private sealed interface SnapshotLookupKey {
		/** Caller getters run only before native admission and never under a native transaction monitor. */
		boolean matches(Value value);
	}

	private record SnapshotIRIKey(String iri) implements SnapshotLookupKey {
		@Override
		public boolean matches(Value value) {
			return value instanceof IRI input && iri.equals(input.stringValue());
		}
	}

	private record SnapshotBNodeKey(String id) implements SnapshotLookupKey {
		@Override
		public boolean matches(Value value) {
			return value instanceof BNode input && id.equals(input.getID());
		}
	}

	private record SnapshotLiteralKey(SnapshotLookupKey datatype, String label, String language,
			Literal.BaseDirection direction) implements SnapshotLookupKey {
		@Override
		public boolean matches(Value value) {
			if (!(value instanceof Literal input) || !label.equals(input.getLabel())
					|| !Objects.equals(language, input.getLanguage().orElse(null))
					|| direction != input.getBaseDirection()) {
				return false;
			}
			IRI inputDatatype = input.getDatatype();
			return datatype == null ? inputDatatype == null : datatype.matches(inputDatatype);
		}
	}

	private record SnapshotTripleKey(SnapshotLookupKey subject, SnapshotLookupKey predicate, SnapshotLookupKey object)
			implements SnapshotLookupKey {
		@Override
		public boolean matches(Value value) {
			return value instanceof TripleTerm input && subject.matches(input.getSubject())
					&& predicate.matches(input.getPredicate()) && object.matches(input.getObject());
		}
	}

	private record SnapshotLookupEntry(Value value, SnapshotLookupKey key, long id) {
	}

	/** Bounded identity slots; the holder never owns a snapshot or any native memory. */
	private static final class SnapshotLookupCache {
		private static final SnapshotLookupEntry[] DISABLED_ENTRIES = new SnapshotLookupEntry[0];
		private volatile SnapshotLookupEntry[] entries;
		private final int mask;

		private SnapshotLookupCache(int capacity) {
			entries = new SnapshotLookupEntry[capacity];
			mask = capacity > 0 && Integer.bitCount(capacity) == 1 ? capacity - 1 : -1;
		}

		private int index(Value value, int length) {
			int hash = System.identityHashCode(value);
			return mask >= 0 ? hash & mask : Math.floorMod(hash, length);
		}

		private SnapshotLookupEntry get(Value value) {
			SnapshotLookupEntry[] current = entries;
			if (current.length == 0) {
				return null;
			}
			SnapshotLookupEntry entry = (SnapshotLookupEntry) SNAPSHOT_LOOKUP_ELEMENT.getAcquire(current,
					index(value, current.length));
			return entry != null && entry.value() == value ? entry : null;
		}

		private void put(Value value, SnapshotLookupKey key, long id) {
			SnapshotLookupEntry[] current = entries;
			if (current.length != 0) {
				SNAPSHOT_LOOKUP_ELEMENT.setRelease(current, index(value, current.length),
						new SnapshotLookupEntry(value, key, id));
			}
		}

		private void disable() {
			// The snapshot has already disconnected this holder. In-flight operations may finish on their
			// captured array, but cannot repopulate this retired holder or retain its unused capacity.
			entries = DISABLED_ENTRIES;
		}
	}

	private long getId(ReadSnapshot snapshot, long txn, SnapshotValueLookup lookup) throws IOException {
		if (snapshot != null) {
			snapshot.ensureValid();
		}
		return switch (lookup) {
		case SnapshotKnownId known -> known.id();
		case SnapshotEncodedValue encoded -> findId(snapshot, txn, encoded.data());
		case SnapshotIRI iri -> {
			byte[] data = uri2data(snapshot, txn, iri);
			long found = data == null ? LmdbValue.UNKNOWN_ID : findId(snapshot, txn, data);
			if (found != LmdbValue.UNKNOWN_ID) {
				yield found;
			}
			byte[] lexical = new byte[iri.namespaceData().length - 1 + iri.localNameData().length];
			System.arraycopy(iri.namespaceData(), 1, lexical, 0, iri.namespaceData().length - 1);
			System.arraycopy(iri.localNameData(), 0, lexical, iri.namespaceData().length - 1,
					iri.localNameData().length);
			try (MemoryStack stack = stackPush()) {
				yield findAlternativeIriId(lexical, -1, LmdbValue.UNKNOWN_ID, stack, txn);
			}
		}
		case SnapshotLiteral literal -> {
			byte[] data = literal2data(snapshot, txn, literal);
			long found = data == null ? LmdbValue.UNKNOWN_ID : findId(snapshot, txn, data);
			yield found == LmdbValue.UNKNOWN_ID ? findLegacyLiteralInTransaction(txn, literal) : found;
		}
		case SnapshotTriple triple -> {
			long subj = getId(snapshot, txn, triple.subject());
			long pred = getId(snapshot, txn, triple.predicate());
			long obj = getId(snapshot, txn, triple.object());
			yield subj == LmdbValue.UNKNOWN_ID || pred == LmdbValue.UNKNOWN_ID || obj == LmdbValue.UNKNOWN_ID
					? LmdbValue.UNKNOWN_ID
					: findTripleTermId(snapshot, txn, subj, pred, obj);
		}
		};
	}

	private byte[] uri2data(ReadSnapshot snapshot, long txn, SnapshotIRI uri) throws IOException {
		long nsID = findId(snapshot, txn, uri.namespaceData());
		if (nsID == LmdbValue.UNKNOWN_ID) {
			return null;
		}
		byte[] localNameData = uri.localNameData();
		int nsIDLength = Varint.calcLengthUnsigned(nsID);
		byte[] uriData = new byte[1 + nsIDLength + localNameData.length];
		uriData[0] = URI_VALUE;
		Varint.writeUnsigned(ByteBuffer.wrap(uriData, 1, nsIDLength), nsID);
		ByteArrayUtil.put(localNameData, uriData, 1 + nsIDLength);
		return uriData;
	}

	private byte[] literal2data(ReadSnapshot snapshot, long txn, SnapshotLiteral literal) throws IOException {
		long datatypeID = literal.datatype() == null ? 0 : getId(snapshot, txn, literal.datatype());
		if (datatypeID == LmdbValue.UNKNOWN_ID) {
			return null;
		}
		byte[] langData = literal.languageData();
		int langLength = langData == null ? 0 : langData.length;
		byte[] labelData = literal.labelData();
		int datatypeIDLength = Varint.calcLengthUnsigned(datatypeID);
		boolean extended = langLength > 0x3F;
		int extendedLengthBytes = extended ? Varint.calcLengthUnsigned(langLength) : 0;
		byte[] data = new byte[2 + datatypeIDLength + extendedLengthBytes + langLength + labelData.length];
		ByteBuffer bb = ByteBuffer.wrap(data);
		bb.put(LITERAL_VALUE);
		Varint.writeUnsigned(bb, datatypeID);
		Literal.BaseDirection baseDirection = literal.baseDirection();
		int directionValue = baseDirection == null ? 0 : switch (baseDirection) {
		case LTR -> 1;
		case RTL -> 2;
		default -> 0;
		};
		if (extended) {
			bb.put((byte) (0xC0 | directionValue));
			Varint.writeUnsigned(bb, langLength);
		} else {
			bb.put((byte) (directionValue << 6 | langLength));
		}
		if (langData != null) {
			bb.put(langData);
		}
		bb.put(labelData);
		return data;
	}

	private long findId(ReadSnapshot snapshot, long txn, byte[] data) throws IOException {
		if (snapshot != null) {
			snapshot.ensureValid();
		}
		byte[] key = lookupKey(data);
		long languageRange = lookupLanguageRange(key);
		// An exact payload match proves the same dictionary identity. A miss still consults the physical key,
		// including legacy byte-exact keys and current-format canonical language matching.
		try (ValueOverlayRegistry.SnapshotLease overlay = borrowValueOverlay(txn)) {
			if (overlay != null) {
				OptionalLong hit = overlay.findId(data);
				if (hit.isPresent()) {
					snapshotIdOverlayHits.increment();
					return hit.getAsLong();
				}
			}
		}
		snapshotIdDictionaryReads.increment();
		try (MemoryStack stack = stackPush()) {
			MDBVal dataVal = MDBVal.calloc(stack);
			MDBVal idVal = MDBVal.calloc(stack);
			if (key.length <= MAX_KEY_SIZE) {
				dataVal.mv_data(stack.bytes(key));
				return mdb_get(txn, dbi, dataVal, idVal) == MDB_SUCCESS ? data2id(idVal.mv_data())
						: LmdbValue.UNKNOWN_ID;
			}

			long dataHash = hash(key);
			ByteBuffer hashBb = stack.malloc(2 + Long.BYTES + 2);
			hashBb.put(HASH_KEY);
			Varint.writeUnsigned(hashBb, dataHash);
			int hashLength = hashBb.position();
			hashBb.flip();
			MDBVal hashVal = MDBVal.calloc(stack);
			hashVal.mv_data(hashBb);
			if (mdb_get(txn, dbi, hashVal, dataVal) == MDB_SUCCESS) {
				ByteBuffer candidateId = dataVal.mv_data().duplicate();
				idVal.mv_data(candidateId);
				if (mdb_get(txn, dbi, idVal, dataVal) == MDB_SUCCESS
						&& payloadMatchesKey(dataVal.mv_data(), key, languageRange)) {
					return data2id(candidateId);
				}
			}

			hashBb.put(0, HASHID_KEY);
			hashVal.mv_data(hashBb);
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, dbi, pp));
			long cursor = pp.get(0);
			try {
				int rc = mdb_cursor_get(cursor, hashVal, dataVal, MDB_SET_RANGE);
				while (rc == MDB_SUCCESS && compareRegion(hashVal.mv_data(), 0, hashBb, 0, hashLength) == 0) {
					ByteBuffer candidateId = hashVal.mv_data().duplicate();
					candidateId.position(hashLength);
					idVal.mv_data(candidateId);
					if (mdb_get(txn, dbi, idVal, dataVal) == MDB_SUCCESS
							&& payloadMatchesKey(dataVal.mv_data(), key, languageRange)) {
						return data2id(candidateId);
					}
					rc = mdb_cursor_get(cursor, hashVal, dataVal, MDB_NEXT);
				}
				return LmdbValue.UNKNOWN_ID;
			} finally {
				mdb_cursor_close(cursor);
			}
		}
	}

	public RecordIterator getTripleTerms(long subj, long pred, long obj) throws IOException {
		Txn txn = txnManager.createReadTxn();
		try {
			return getTripleTermRecords(txn, subj, pred, obj, true, null);
		} catch (Throwable e) {
			txn.close();
			throw e;
		}
	}

	/** Enumerates term indexes from a dataset-owned dictionary snapshot. */
	RecordIterator getTripleTerms(Txn txn, long subj, long pred, long obj) throws IOException {
		return getTripleTerms(txn, subj, pred, obj, null);
	}

	RecordIterator getTripleTerms(Txn txn, long subj, long pred, long obj, Consumer<RecordIterator> onClose)
			throws IOException {
		return getTripleTermRecords(txn, subj, pred, obj, false, onClose);
	}

	private RecordIterator getTripleTermRecords(Txn txn, long subj, long pred, long obj, boolean ownsTxn,
			Consumer<RecordIterator> onClose)
			throws IOException {
		TripleIndex index = TripleIndex.getBestIndex(tripleTermIndexes, subj, pred, obj, -1);
		boolean doRangeSearch = index.getPatternScore(subj, pred, obj, -1) > 0;
		return new LmdbRecordIterator(index, doRangeSearch, subj, pred, obj, -1, true, txn) {
			private final AtomicBoolean transactionClosed = new AtomicBoolean();

			@Override
			public void close() {
				if (transactionClosed.compareAndSet(false, true)) {
					try {
						super.close();
					} finally {
						try {
							if (ownsTxn) {
								txn.close();
							}
						} finally {
							if (onClose != null) {
								onClose.accept(this);
							}
						}
					}
				}
			}
		};
	}

	TxnManager getTxnManager() {
		return txnManager;
	}

	/** Detaches ordinary paired dictionary readers before resetting native map handles. */
	private void detachStableReadSnapshots(LmdbSailStore.MapGrowthAttempt growthAttempt) {
		LmdbSailStore.MapGrowthToken token = growthAttempt == null ? null : growthAttempt.token();
		for (ReadSnapshot snapshot : readSnapshots) {
			snapshot.detachStableDictionary(token);
		}
	}

	/** Reserves an untracked read transaction for a caller-owned dictionary snapshot. */
	ReadSnapshotReservation reserveReadSnapshot() throws IOException {
		return new ReadSnapshotReservation(txnManager.reserveReadTxn(false));
	}

	class ReadSnapshotReservation implements AutoCloseable {
		private TxnManager.ReaderReservation reservation;

		ReadSnapshotReservation(TxnManager.ReaderReservation reservation) {
			this.reservation = reservation;
		}

		synchronized ReadSnapshot start() throws IOException {
			return start(null);
		}

		/** Waits outside its native barrier, retaining only the caller-owned triple capability across admission. */
		synchronized ReadSnapshot start(Txn tripleTxn) throws IOException {
			while (true) {
				try {
					return tryStart(tripleTxn);
				} catch (ValueReadAdmissionException notAdmitted) {
					awaitValueReaderAdmission();
					reservation = txnManager.reserveReadTxn(false);
				}
			}
		}

		/**
		 * Captures shared ID retention atomically with native admission. A caller holding publication or paired-reader
		 * resources must unwind all of them on ValueReadAdmissionException before waiting and reserving again.
		 */
		synchronized ReadSnapshot tryStart(Txn tripleTxn) throws IOException {
			if (reservation == null) {
				throw new IllegalStateException(
						"ValueStore read snapshot reservation has already been consumed or closed");
			}
			if (tripleTxn != null) {
				if (tripleTxn.snapshotRevision() < 0) {
					throw new IllegalStateException("Stable dictionary IDs require a pinned TripleStore reader");
				}
				tripleTxn.ensureSnapshotValid();
			}
			TxnManager.ReaderReservation reserved = reservation;
			ReadSnapshot[] captured = new ReadSnapshot[1];
			ValueReadScope scope = new ValueReadScope(null);
			try {
				ReadSnapshot snapshot = reserved.startPinned(null, txn -> {
					captured[0] = new ReadSnapshot(txn, scope.captured, tripleTxn);
					return captured[0];
				}, scope::open);
				reservation = null;
				return snapshot;
			} catch (IOException | RuntimeException | Error e) {
				reservation = null;
				if (captured[0] != null) {
					try {
						captured[0].close();
					} catch (Error cleanupFailure) {
						if (cleanupFailure != e) {
							e.addSuppressed(cleanupFailure);
						}
					} catch (RuntimeException cleanupFailure) {
						if (cleanupFailure != e) {
							e.addSuppressed(cleanupFailure);
						}
					}
				}
				reserved.close();
				throw e;
			} finally {
				// The snapshot owns its own reservation before native start releases the short gate.
				scope.releaseReservation();
			}
		}

		@Override
		public void close() {
			TxnManager.ReaderReservation reserved;
			synchronized (this) {
				reserved = reservation;
				reservation = null;
			}
			if (reserved != null) {
				reserved.close();
			}
		}
	}

	Function<Value, Value> valuePreparer(ReadSnapshot snapshot) {
		return snapshot.valuePreparer;
	}

	Function<Value, Value> valueCapturer(ReadSnapshot snapshot) {
		return snapshot.valuePreparer.capturer;
	}

	/** One dictionary view's preparation service; models retain only its metadata-only owner and generation. */
	private final class ValuePreparer implements Function<Value, Value> {
		private volatile ReadSnapshot snapshot;
		private LmdbSailStore.MapResizeKind retiredKind;
		private final OwnedValueCapturer capturer = new OwnedValueCapturer() {
			@Override
			public Value apply(Value value) {
				return captureExternal(value);
			}

			@Override
			public boolean owns(Value value) {
				ReadSnapshot current = snapshot;
				if (current == null) {
					return false;
				}
				if (value instanceof PreparedLmdbValue.Prepared prepared) {
					return prepared.state().owner == current.preparationOwner;
				}
				return isNativeOfSnapshot(current, value);
			}
		};

		/**
		 * A lazy shell of this paired snapshot's own dictionary epoch is already a proven statement value: the record
		 * read that produced it established its ID under the pinned triple reader, exactly the
		 * {@link ReadSnapshot#provesStatementIds} conditions a later lookup would check again.
		 */
		private boolean isNativeOfSnapshot(ReadSnapshot current, Value value) {
			if (!(value instanceof LmdbValue nativeValue) || value instanceof PreparedLmdbValue.Prepared
					|| nativeValue.getSemanticVersion() == LmdbValue.UNKNOWN_ID) {
				return false;
			}
			LmdbValue.InternalIdentity identity = nativeValue.getInternalIdentity();
			return identity.id() != LmdbValue.UNKNOWN_ID && identity.revision() instanceof ValueStoreRevision.Lazy lazy
					&& current.provesStatementIds(lazy);
		}

		private ValuePreparer(ReadSnapshot snapshot) {
			this.snapshot = snapshot;
		}

		private ReadSnapshot liveSnapshot() throws IOException {
			ReadSnapshot current = snapshot;
			if (current == null) {
				LmdbSailStore.MapResizeKind invalidated = retiredKind;
				if (invalidated != null) {
					throw new LmdbSailStore.MapResizeConflictException(invalidated,
							"ValueStore map changed while the read snapshot was pinned; retry the transaction");
				}
				throw new IOException("ValueStore read snapshot is closed; retry the read operation");
			}
			current.ensureValid();
			current.checkLookupAdmission();
			return current;
		}

		@Override
		public Value apply(Value value) {
			if (value == null) {
				return null;
			}
			if (isPreparedForLiveGeneration(value)) {
				// Per-row join probes re-prepare the same values; a live statement proof already answers them.
				return value;
			}
			ReadSnapshot proving = snapshot;
			if (proving != null && isNativeOfSnapshot(proving, value)) {
				// Statement values read under this paired snapshot are looked up by their proven ID as they are.
				return value;
			}
			try {
				// One validity and admission check covers both the capture and the identity resolution of the value.
				ReadSnapshot current = liveSnapshot();
				PreparedLmdbValue.Prepared prepared = (PreparedLmdbValue.Prepared) capture(current, value);
				if (prepared != value && current.hasStableIds()) {
					// Captured just now and not tracked by the snapshot, so no other thread can hold it yet.
					resolveAdmitted(current, prepared.state(), true);
				} else {
					resolve(current, prepared, true);
				}
				return prepared;
			} catch (IOException failure) {
				throw new SailException(failure);
			}
		}

		private boolean isPreparedForLiveGeneration(Value value) {
			if (!(value instanceof PreparedLmdbValue.Prepared prepared)) {
				return false;
			}
			ReadSnapshot current = snapshot;
			if (current == null) {
				return false;
			}
			PreparedLmdbValue.State state = prepared.state();
			if (state.owner != current.preparationOwner) {
				return false;
			}
			PreparedLmdbValue.Proof proof = state.proof;
			return proof.generation() == current.preparationGeneration && proof.generation().live;
		}

		private Value capture(Value value) {
			if (value == null) {
				return null;
			}
			ReadSnapshot current = snapshot;
			if (current != null) {
				if (value instanceof PreparedLmdbValue.Prepared prepared) {
					if (prepared.state().owner == current.preparationOwner) {
						// Already owned by this snapshot: no lookup follows, so no admission check is needed.
						return prepared;
					}
				} else if (isNativeOfSnapshot(current, value)) {
					// A shell of this snapshot's own epoch keeps its canonical identity and deferred payload.
					return value;
				}
			}
			try {
				return capture(liveSnapshot(), value);
			} catch (IOException failure) {
				throw new SailException(failure);
			}
		}

		/**
		 * Captures values crossing the query-result boundary without resolving a previously exposed cold native value.
		 * Lookup preparation remains in {@link #apply(Value)}; it may need a current-generation semantic copy instead.
		 */
		private Value captureExternal(Value value) {
			if (value == null) {
				return null;
			}
			ReadSnapshot current = snapshot;
			if (current != null) {
				if (value instanceof PreparedLmdbValue.Prepared prepared
						&& prepared.state().owner == current.preparationOwner) {
					// Preserve the established same-owner prepared-value fast path.
					return value;
				}
				if (isNativeOfSnapshot(current, value)) {
					return value;
				}
			}
			try {
				return capture(liveSnapshot(), value, true);
			} catch (IOException failure) {
				throw new SailException(failure);
			}
		}

		private Value capture(ReadSnapshot current, Value value) {
			return capture(current, value, false);
		}

		private Value capture(ReadSnapshot current, Value value, boolean preserveExternalColdNativeValues) {
			if (value == null) {
				return null;
			}
			Value owned = capturedBy(current, value, preserveExternalColdNativeValues);
			if (owned != null) {
				return owned;
			}
			try {
				// Caller values may be arbitrarily deep or share children. Identity maps avoid invoking their
				// recursive equality/hash methods and retain one semantic copy of each input in this capture.
				IdentityHashMap<Value, Value> completed = new IdentityHashMap<>();
				IdentityHashMap<Value, Boolean> active = new IdentityHashMap<>();
				ArrayDeque<CaptureFrame> pending = new ArrayDeque<>();
				pending.push(new CaptureFrame(current, value));
				active.put(value, Boolean.TRUE);
				while (!pending.isEmpty()) {
					CaptureFrame frame = pending.peek();
					if (frame.children != null && frame.nextChild < frame.children.length) {
						Value child = frame.children[frame.nextChild];
						Value captured = completed.get(child);
						if (captured == null) {
							captured = capturedBy(current, child, preserveExternalColdNativeValues);
						}
						if (captured != null) {
							frame.capturedChildren[frame.nextChild++] = captured;
							continue;
						}
						if (active.put(child, Boolean.TRUE) != null) {
							throw new IllegalArgumentException("Cyclic RDF value cannot be captured");
						}
						pending.push(new CaptureFrame(current, child));
						continue;
					}
					Value payload = frame.payload;
					if (frame.children != null) {
						payload = frame.type == Value.Type.TripleTerm
								? createTripleTerm((Resource) frame.capturedChildren[0],
										(IRI) frame.capturedChildren[1], frame.capturedChildren[2])
								: createLiteral(frame.label, (IRI) frame.capturedChildren[0]);
					}
					PreparedLmdbValue.Prepared prepared = PreparedLmdbValue.create(new PreparedLmdbValue.State(
							current.preparationOwner, frame.type, frame.identity, payload));
					if (!current.hasStableIds() && payload == null) {
						current.trackLazyValue(prepared);
					}
					completed.put(frame.original, prepared);
					active.remove(frame.original);
					pending.pop();
				}
				return completed.get(value);
			} catch (IOException failure) {
				throw new SailException(failure);
			}
		}

		private Value capturedBy(ReadSnapshot current, Value value, boolean preserveExternalColdNativeValues) {
			if (preserveExternalColdNativeValues && value instanceof LmdbValue nativeValue
					&& !(value instanceof PreparedLmdbValue.Prepared) && nativeValue.isExternallyOwned()
					&& !nativeValue.isInitialized()) {
				LmdbValue.InternalIdentity identity = nativeValue.getInternalIdentity();
				if (identity.id() != LmdbValue.UNKNOWN_ID && identity.revision() != null) {
					// This value already owns the deferred decode capability that made it externally readable. Keep the
					// exact cold node; initialized/mutable composites and prepared wrappers still follow semantic
					// capture.
					return value;
				}
			}
			return capturedBy(current, value);
		}

		private Value capturedBy(ReadSnapshot current, Value value) {
			if (value instanceof PreparedLmdbValue.Prepared prepared) {
				return prepared.state().owner == current.preparationOwner ? value : null;
			}
			return isNativeOfSnapshot(current, value) ? value : null;
		}

		/** Captures the current node's payload once; children are composed only after their own frames complete. */
		private final class CaptureFrame {
			private final Value original;
			private final Value.Type type;
			private final LmdbValue.InternalIdentity identity;
			private Value payload;
			private Value[] children;
			private Value[] capturedChildren;
			private String label;
			private int nextChild;

			private CaptureFrame(ReadSnapshot current, Value value) throws IOException {
				original = value;
				Value source;
				LmdbValue.InternalIdentity capturedIdentity;
				if (value instanceof LmdbValue nativeValue
						&& nativeValue.getSemanticVersion() != LmdbValue.UNKNOWN_ID
						&& (capturedIdentity = nativeValue.getInternalIdentity()).id() != LmdbValue.UNKNOWN_ID) {
					// Copy ready fields without recursively capturing children or decoding a cold native shell.
					source = nativeValue.copyInitializedValue(Function.identity());
					type = switch (ValueIds.getIdType(capturedIdentity.id())) {
					case ValueIds.T_URI -> Value.Type.IRI;
					case ValueIds.T_BNODE -> Value.Type.BNode;
					case ValueIds.T_TRIPLE -> Value.Type.TripleTerm;
					default -> Value.Type.Literal;
					};
					if (source == null && capturedIdentity.revision() instanceof ValueStoreRevision.Default
							&& capturedIdentity.revision().equals(current.completedRevision())) {
						capturedIdentity = new LmdbValue.InternalIdentity(capturedIdentity.id(),
								scopedRevision(current.revision()));
					}
				} else {
					capturedIdentity = new LmdbValue.InternalIdentity(LmdbValue.UNKNOWN_ID,
							current.completedRevision());
					type = value.getType();
					source = value;
				}
				identity = capturedIdentity;
				if (source instanceof IRI iri) {
					payload = createIRI(iri.stringValue());
				} else if (source instanceof BNode bnode) {
					payload = createBNode(bnode.getID());
				} else if (source instanceof Literal literal) {
					label = literal.getLabel();
					Optional<String> language = literal.getLanguage();
					if (language.isPresent()) {
						payload = createLiteral(label, language.get(), literal.getBaseDirection());
					} else {
						children = new Value[] { literal.getDatatype() };
					}
				} else if (source instanceof TripleTerm triple) {
					children = new Value[] { triple.getSubject(), triple.getPredicate(), triple.getObject() };
				}
				if (children != null) {
					capturedChildren = new Value[children.length];
				}
			}
		}

		private long resolve(PreparedLmdbValue.Prepared prepared) throws IOException {
			return resolve(prepared, false);
		}

		private long resolve(PreparedLmdbValue.Prepared prepared, boolean statement) throws IOException {
			return resolve(liveSnapshot(), prepared, statement);
		}

		private long resolve(ReadSnapshot current, PreparedLmdbValue.Prepared prepared, boolean statement)
				throws IOException {
			if (prepared.state().owner != current.preparationOwner) {
				return resolve(current, (PreparedLmdbValue.Prepared) capture(current, prepared), statement);
			}
			PreparedLmdbValue.State state = prepared.state();
			PreparedLmdbValue.Proof proof = statement ? state.proof : state.dictionaryProof;
			if (proof.generation() == current.preparationGeneration && proof.generation().live) {
				return proof.identity().id();
			}
			synchronized (state) {
				return resolveAdmitted(current, state, statement);
			}
		}

		/**
		 * Resolves under the caller's exclusive access to {@code state} (its monitor, or a value nobody else holds);
		 * {@code current} was validated and admitted by the caller immediately before.
		 */
		private long resolveAdmitted(ReadSnapshot current, PreparedLmdbValue.State state, boolean statement)
				throws IOException {
			boolean admitted = true;
			while (true) {
				if (!admitted) {
					current = liveSnapshot();
				}
				admitted = false;
				PreparedLmdbValue.Generation generation = current.preparationGeneration;
				PreparedLmdbValue.Proof proof = statement ? state.proof : state.dictionaryProof;
				if (proof.generation() == generation && generation.live) {
					return proof.identity().id();
				}
				LmdbValue.InternalIdentity candidate = state.proof.identity();
				long id = statement ? knownStatementIdAdmitted(current, candidate)
						: knownSnapshotId(current, candidate);
				boolean dictionaryValidated = !statement;
				if (id == LmdbValue.UNKNOWN_ID) {
					// This virtual call keeps the ordinary native lookup seam and mutable-caller contract intact.
					id = getId(current, state.payload());
					dictionaryValidated = true;
				}
				current.ensureValid();
				if (generation != current.preparationGeneration || !generation.live) {
					continue;
				}
				ValueStoreRevision preparedRevision = state.payload == null
						? scopedRevision(current.revision())
						: current.completedRevision();
				LmdbValue.InternalIdentity identity = candidate.id() == id && candidate.revision() == preparedRevision
						? candidate
						: new LmdbValue.InternalIdentity(id, preparedRevision);
				PreparedLmdbValue.Proof resolved = new PreparedLmdbValue.Proof(generation, identity);
				if (dictionaryValidated) {
					state.dictionaryProof = resolved;
				}
				// An absent old dictionary record does not revoke a safe statement-index association.
				if (statement || state.proof.generation() != generation
						|| state.proof.identity().id() == LmdbValue.UNKNOWN_ID) {
					state.proof = resolved;
				}
				return id;
			}
		}
	}

	/** A write-commit-stable reader whose lifetime is owned by the caller. */
	final class ReadSnapshot implements AutoCloseable {
		private final PreparedLmdbValue.Owner preparationOwner = new PreparedLmdbValue.Owner();
		private volatile PreparedLmdbValue.Generation preparationGeneration = new PreparedLmdbValue.Generation(
				preparationOwner);
		private final ValuePreparer valuePreparer = new ValuePreparer(this);
		private final Txn txn;
		private final long transactionVersion;
		private final long nativeTransactionId;
		private final long nativeMapGeneration;
		private final ValueStoreRevision.Snapshot revision;
		private final EpochReservation epochReservation;
		private volatile boolean closed;
		private volatile Thread closingThread;
		private volatile boolean abandonUnobserved;
		private volatile LmdbSailStore.MapResizeKind retiredKind;
		private volatile Txn stableTripleTxn;
		private volatile ValueStoreRevision.Lazy stableRevision;
		private volatile boolean dictionaryDetached;
		private volatile boolean termSnapshotUsed;
		private volatile LmdbSailStore.MapGrowthToken dictionaryGrowthToken;
		private volatile SnapshotLookupCache lookupCache;

		private ReadSnapshot(Txn txn, ValueStoreRevision.Lazy capturedRevision, Txn tripleTxn) {
			this.epochReservation = tripleTxn == null ? null : lazyRevisions.reserve(capturedRevision);
			if (tripleTxn != null && epochReservation == null) {
				throw new SailException("The dictionary epoch was released during paired snapshot admission");
			}
			this.txn = txn;
			this.transactionVersion = txn.version();
			this.nativeTransactionId = mdb_txn_id(txn.get());
			this.nativeMapGeneration = ValueStore.this.nativeMapGeneration;
			if (tripleTxn != null) {
				stableRevision = capturedRevision;
				stableTripleTxn = tripleTxn;
				capturedRevision.preferSnapshot(this);
			}
			txn.setSnapshotBound();
			this.revision = new ValueStoreRevision.Snapshot(ValueStore.this, this);
			readSnapshots.add(this);
		}

		/** Verifies the authoritative TripleStore capability supplied at dictionary admission. */
		void retainStableIds(Txn tripleTxn) {
			synchronized (txn) {
				if (closed || stableTripleTxn != tripleTxn || tripleTxn.snapshotRevision() < 0) {
					throw new IllegalStateException(
							"Stable dictionary IDs require their pinned TripleStore reader at admission");
				}
				tripleTxn.ensureSnapshotValid();
			}
		}

		boolean hasStableIds() {
			return stableTripleTxn != null;
		}

		/** Exact admitted pair identity; valid logical dictionary detachment keeps its stable triple authority. */
		boolean isPairedWith(Txn tripleTxn) {
			return tripleTxn != null && !closed && retiredKind == null && stableTripleTxn == tripleTxn
					&& tripleTxn.snapshotRevision() >= 0L && tripleTxn.isNativeActive();
		}

		PreparedLmdbValue.Generation preparationGeneration() {
			return preparationGeneration;
		}

		/** The {@link ValueStore#knownStatementId} conditions, minus the ID, for a value revision read from here. */
		boolean provesStatementIds(ValueStoreRevision.Lazy lazy) {
			ValueStoreRevision.Lazy paired = stableRevision;
			ValueEpoch epoch = paired == null ? null : paired.idEpoch();
			ValueEpoch own = lazy.idEpoch();
			if (lazy.getValueStore() != ValueStore.this || !hasStableIds() || epoch == null || !epoch.protectedIds
					|| own != null && !own.protectedIds
					|| !ValueStore.completedRevision(lazy).equals(completedRevision())) {
				return false;
			}
			NativeValueAssociation association = lazy.association();
			return association == null || association.state == NativeValueAssociation.State.COMMITTED;
		}

		boolean isCurrent() {
			if (hasStableIds()) {
				try {
					ensureValid();
					return true;
				} catch (IOException | SailException e) {
					return false;
				}
			}
			if (closed || txn.isClosed() || txn.version() != transactionVersion) {
				return false;
			}
			try {
				txn.ensureSnapshotValid();
				return true;
			} catch (SailException e) {
				return false;
			}
		}

		void ensureValid() throws IOException {
			LmdbSailStore.MapResizeKind invalidated = retiredKind;
			if (invalidated != null && closingThread != Thread.currentThread()) {
				throw new LmdbSailStore.MapResizeConflictException(invalidated,
						"ValueStore map changed while the read snapshot was pinned; retry the transaction");
			}
			if ((closed && closingThread != Thread.currentThread()) || !hasStableIds() && txn.isClosed()) {
				throw new IOException("ValueStore read snapshot is closed; retry the read operation");
			}
			Txn horizon = stableTripleTxn;
			if (horizon != null) {
				horizon.ensureSnapshotValid();
				return;
			}
			try {
				txn.ensureSnapshotValid();
			} catch (SailConflictException e) {
				throw e;
			} catch (SailException e) {
				throw new IOException(e.getMessage(), e);
			}
			if (txn.version() != transactionVersion) {
				throw new LmdbSailStore.MapResizeConflictException(LmdbSailStore.MapResizeKind.VALUE_STORE,
						"ValueStore map changed while the read snapshot was pinned; retry the transaction");
			}
		}

		void abandonUnobserved() {
			abandonUnobserved = true;
		}

		boolean hasNativeTxn() {
			return requiresStableTermMembership() && txn.isNativeActive();
		}

		boolean requiresStableTermMembership() {
			return (!hasStableIds() || termSnapshotUsed) && !dictionaryDetached;
		}

		LmdbSailStore.MapGrowthToken dictionaryGrowthToken() {
			return dictionaryGrowthToken;
		}

		boolean dictionaryDetached() {
			return dictionaryDetached;
		}

		long nativeMapGeneration() {
			return nativeMapGeneration;
		}

		/** Holds the ordinary native read barrier while declaring this view dependent on dictionary membership. */
		void requireTermSnapshot() throws IOException {
			requireTermSnapshot(Runnable::run);
		}

		void requireTermSnapshot(Consumer<Runnable> membershipDeclaration) throws IOException {
			long stamp = txnManager.acquireReadBarrier();
			try {
				synchronized (txn) {
					ensureValid();
					if (dictionaryDetached) {
						throw new LmdbSailStore.MapResizeConflictException(LmdbSailStore.MapResizeKind.VALUE_STORE,
								"ValueStore term membership changed while the read snapshot was pinned; retry the transaction");
					}
					membershipDeclaration.accept(() -> termSnapshotUsed = true);
					txn.ensureSnapshotValid();
				}
			} finally {
				txnManager.lockManager().unlockRead(stamp);
			}
		}

		/** Called under ValueStore's exclusive native barrier, after all in-flight dictionary reads leave. */
		private void detachStableDictionary(LmdbSailStore.MapGrowthToken token) {
			synchronized (txn) {
				if (!closed && hasStableIds() && !termSnapshotUsed && !dictionaryDetached) {
					disableLookupCache();
					preparationGeneration.live = false;
					preparationGeneration = new PreparedLmdbValue.Generation(preparationOwner);
					dictionaryGrowthToken = token;
					dictionaryDetached = true;
					txn.invalidateAndReset(LmdbSailStore.MapResizeKind.VALUE_STORE);
					txn.close();
				}
			}
		}

		void retireForMapResize(LmdbSailStore.MapResizeKind kind) {
			retiredKind = kind;
			close();
		}

		Txn txnRef() {
			return txn;
		}

		ValueStoreRevision revision() {
			ValueStoreRevision.Lazy stable = stableRevision;
			return stable == null ? revision : stable;
		}

		ValueStoreRevision completedRevision() {
			return ValueStore.completedRevision(revision());
		}

		ValueStore valueStore() {
			return ValueStore.this;
		}

		void trackLazyValue(LmdbValue value) throws IOException {
			synchronized (txn) {
				ensureValid();
				revision.track(value);
			}
		}

		private long cachedLookup(Value value) throws IOException {
			SnapshotLookupCache cache = lookupCache;
			if (cache == null || cache == DISABLED_SNAPSHOT_LOOKUP_CACHE) {
				return LmdbValue.UNKNOWN_ID;
			}
			SnapshotLookupEntry entry = cache.get(value);
			if (entry == null) {
				return LmdbValue.UNKNOWN_ID;
			}
			checkLookupAdmission();
			boolean matches = entry.key().matches(value);
			// A caller getter can race close, detach, cancellation or a native generation change.
			ensureValid();
			checkLookupAdmission();
			return matches && lookupCache == cache ? entry.id() : LmdbValue.UNKNOWN_ID;
		}

		private boolean canCacheLookup() {
			return snapshotLookupCacheCapacity > 0 && lookupCache != DISABLED_SNAPSHOT_LOOKUP_CACHE;
		}

		private void checkLookupAdmission() throws IOException {
			if (Thread.currentThread().isInterrupted()) {
				throw new IOException("Interrupted while looking up a ValueStore snapshot value",
						new InterruptedException());
			}
			QueryExecutionDeadline deadline = QueryExecutionDeadline.current();
			if (deadline != null && deadline.remainingMillis() <= 0L) {
				throw new QueryInterruptedException("Query evaluation took too long");
			}
		}

		private void cacheLookup(Value value, SnapshotLookupKey key, long id) {
			if (key == null || id == LmdbValue.UNKNOWN_ID || snapshotLookupCacheCapacity == 0) {
				return;
			}
			SnapshotLookupCache cache = lookupCache;
			if (cache == null) {
				SnapshotLookupCache candidate = new SnapshotLookupCache(snapshotLookupCacheCapacity);
				cache = (SnapshotLookupCache) SNAPSHOT_LOOKUP_CACHE.compareAndExchange(this, null, candidate);
				if (cache == null) {
					cache = candidate;
				}
			}
			if (cache != DISABLED_SNAPSHOT_LOOKUP_CACHE) {
				cache.put(value, key, id);
			}
		}

		private void disableLookupCache() {
			SnapshotLookupCache cache = (SnapshotLookupCache) SNAPSHOT_LOOKUP_CACHE.getAndSet(this,
					DISABLED_SNAPSHOT_LOOKUP_CACHE);
			if (cache != null && cache != DISABLED_SNAPSHOT_LOOKUP_CACHE) {
				cache.disable();
			}
		}

		@Override
		public synchronized void close() {
			boolean interrupted = false;
			long readStamp;
			while (true) {
				try {
					readStamp = txnManager.lockManager().readLock();
					break;
				} catch (InterruptedException e) {
					interrupted = true;
				}
			}
			try {
				boolean materialize;
				synchronized (txn) {
					if (closed) {
						return;
					}
					materialize = !hasStableIds() && !abandonUnobserved && isCurrent();
					closingThread = Thread.currentThread();
					closed = true;
					disableLookupCache();
					preparationGeneration.live = false;
					// Publish only the terminal invalidation authority before releasing the native snapshot reference.
					valuePreparer.retiredKind = retiredKind;
					valuePreparer.snapshot = null;
				}
				try {
					if (materialize) {
						// Do not hold the Txn monitor while initializing values: LmdbValue.init() takes the value
						// monitor
						// before it resolves through this Txn, so reversing that order here could deadlock.
						revision.materializeTrackedValues();
					}
				} finally {
					synchronized (txn) {
						closingThread = null;
						LmdbSailStore.MapResizeKind invalidated = retiredKind;
						try {
							if (!dictionaryDetached) {
								if (invalidated != null) {
									txn.invalidateAndReset(invalidated);
								}
								txn.close();
							}
						} finally {
							try {
								revision.release(this);
							} finally {
								stableRevision = null;
								readSnapshots.remove(this);
								if (epochReservation != null) {
									epochReservation.close();
								}
							}
						}
					}
				}
			} finally {
				txnManager.lockManager().unlockRead(readStamp);
				if (interrupted) {
					Thread.currentThread().interrupt();
				}
			}
		}
	}

	LmdbValue getLazyValue(ReadSnapshot snapshot, long id) throws IOException {
		return getLazyValue(snapshot, id, ValuePosition.NONE);
	}

	LmdbValue getLazyValue(ReadSnapshot snapshot, long id, int positionMask) throws IOException {
		ValuePosition.validateMask(positionMask);
		if (snapshot.valueStore() != this) {
			throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
		}
		synchronized (snapshot.txnRef()) {
			snapshot.ensureValid();
			if (snapshot.hasStableIds()) {
				return getLazyValue(id, positionedRevision(snapshot.revision(), positionMask));
			}
			ValueStoreRevision valueRevision = positionMask == ValuePosition.NONE ? snapshot.revision()
					: new ValueStoreRevision.Position(snapshot.revision(), positionMask);
			int idType = ValueIds.getIdType(id);
			LmdbValue value = switch (idType) {
			case ValueIds.T_URI -> new LmdbIRI(valueRevision, id);
			case ValueIds.T_DOUBLE, ValueIds.T_LITERAL, ValueIds.T_CORE_LITERAL -> new LmdbLiteral(valueRevision, id);
			case ValueIds.T_BNODE -> new LmdbBNode(valueRevision, id);
			case ValueIds.T_TRIPLE -> new LmdbTripleTerm(valueRevision, id);
			default -> {
				if (ValueIds.isInlined(id)) {
					yield new LmdbLiteral(valueRevision, id);
				}
				throw new IOException("Unsupported value with id=" + id + " and id type " + idType);
			}
			};
			snapshot.revision.track(value);
			return value;
		}
	}

	LmdbValue getValue(ReadSnapshot snapshot, long id) throws IOException {
		return getValue(snapshot, id, ValuePosition.NONE);
	}

	LmdbValue getValue(ReadSnapshot snapshot, long id, int positionMask) throws IOException {
		ValuePosition.validateMask(positionMask);
		long stamp;
		try {
			stamp = txnManager.lockManager().readLock();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException("Interrupted while reading ValueStore snapshot", e);
		}
		try {
			synchronized (snapshot.txnRef()) {
				snapshot.ensureValid();
				if (snapshot.valueStore() != this) {
					throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
				}
				if (!snapshot.dictionaryDetached()) {
					return positionResolvedValue(getValue(snapshot, snapshot.txnRef().get(), id), positionMask);
				}
			}
		} finally {
			txnManager.lockManager().unlockRead(stamp);
		}
		return readTransaction(env, (stack, txn) -> positionResolvedValue(getValue(snapshot, txn, id), positionMask));
	}

	private LmdbValue positionResolvedValue(LmdbValue value, int positionMask) {
		if (value != null && value.getValueStoreRevision().getPositionMask() != positionMask) {
			value.setInternalID(value.getInternalID(), positionedRevision(value.getValueStoreRevision(), positionMask));
		}
		return value;
	}

	private LmdbValue getValue(ReadSnapshot snapshot, long txn, long id) throws IOException {
		snapshot.ensureValid();
		if (ValueIds.isInlined(id)) {
			Literal unpacked = format.unpackLiteral(id, this);
			return new LmdbLiteral(snapshot.completedRevision(), unpacked.getLabel(), unpacked.getDatatype(), id);
		}
		if (ValueIds.getIdType(id) == ValueIds.T_TRIPLE) {
			return id2tripleTerm(snapshot, txn, id, null);
		}
		byte[] data = getData(txn, id);
		return data == null ? null : data2value(snapshot, txn, id, data);
	}

	boolean resolveValue(ReadSnapshot snapshot, long id, LmdbValue value) {
		long stamp;
		try {
			stamp = txnManager.lockManager().readLock();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new SailException("Interrupted while resolving a ValueStore snapshot value", e);
		}
		try {
			synchronized (snapshot.txnRef()) {
				snapshot.ensureValid();
				if (snapshot.valueStore() != this) {
					throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
				}
				if (ValueIds.isInlined(id)) {
					Literal unpacked = format.unpackLiteral(id, this);
					LmdbLiteral literal = (LmdbLiteral) value;
					literal.setLabel(unpacked.getLabel());
					literal.setDatatype(unpacked.getDatatype());
					literal.setBaseDirection(unpacked.getBaseDirection());
					return true;
				}
				if (ValueIds.getIdType(id) == ValueIds.T_TRIPLE) {
					LmdbTripleTerm tripleTerm = id2tripleTerm(snapshot, snapshot.txnRef().get(), id, null);
					if (tripleTerm != null) {
						value.setFromInitializedValue(tripleTerm);
						return true;
					}
					return false;
				}
				byte[] data = getData(snapshot.txnRef().get(), id);
				if (data == null) {
					return false;
				}
				return data2value(snapshot, snapshot.txnRef().get(), id, data, value) != null;
			}
		} catch (IOException e) {
			throw new SailException(e.getMessage(), e);
		} finally {
			txnManager.lockManager().unlockRead(stamp);
		}
	}

	RecordIterator getTripleTerms(ReadSnapshot snapshot, long subj, long pred, long obj,
			Consumer<RecordIterator> onClose) throws IOException {
		RecordIterator iterator = getTripleTerms(snapshot, subj, pred, obj);
		return onClose == null ? iterator : new RecordIterator() {
			private boolean closed;

			@Override
			public long[] next() {
				return iterator.next();
			}

			@Override
			public void close() {
				if (!closed) {
					closed = true;
					try {
						iterator.close();
					} finally {
						onClose.accept(this);
					}
				}
			}
		};
	}

	RecordIterator getTripleTerms(ReadSnapshot snapshot, long subj, long pred, long obj) throws IOException {
		if (snapshot.valueStore() != this) {
			throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
		}
		snapshot.requireTermSnapshot();
		TripleIndex index = TripleIndex.getBestIndex(tripleTermIndexes, subj, pred, obj, -1);
		boolean doRangeSearch = index.getPatternScore(subj, pred, obj, -1) > 0;
		return new LmdbRecordIterator(index, doRangeSearch, subj, pred, obj, -1, true, snapshot.txnRef(), snapshot);
	}

	/** Records IDs that may be reclaimed after the supplied TripleStore reader watermark has passed. */

	/** Returns candidates whose retirement watermark has passed; the caller must check TripleStore liveness. */

	/** Removes a polled batch after the caller has applied the normal liveness and ValueStore GC checks. */

	boolean hasRetiredIds() {
		return retiredIdStore.hasPending();
	}

	Map<String, LmdbStore.LmdbDatabaseStats> getLmdbStats() throws IOException {
		return readTransaction(env, (stack, txn) -> {
			Map<String, LmdbStore.LmdbDatabaseStats> stats = new LinkedHashMap<>();
			MDBStat stat = MDBStat.malloc(stack);
			addLmdbStats(stats, "main", txn, dbi, stat);
			addLmdbStats(stats, "unused_ids", txn, unusedDbi, stat);
			addLmdbStats(stats, "free_ids", txn, freeDbi, stat);
			addLmdbStats(stats, "ref_counts", txn, refCountsDbi, stat);
			for (TripleIndex index : tripleTermIndexes) {
				addLmdbStats(stats, index.getName(true), txn, index.getDB(true), stat);
			}
			return stats;
		});
	}

	private static void addLmdbStats(Map<String, LmdbStore.LmdbDatabaseStats> stats, String name, long txn, int dbi,
			MDBStat stat) throws IOException {
		E(mdb_stat(txn, dbi, stat));
		stats.put(name, LmdbStore.LmdbDatabaseStats.from(stat));
	}

	<T> T readTransaction(long env, Transaction<T> transaction) throws IOException {
		if (isWriteTransactionOwner()) {
			return withValueReadTransaction(null, transaction);
		}
		ReadContext context = readContext.get();
		long borrowed = context.borrowedTxn;
		if (borrowed != 0) {
			MemoryStack stack = context.stack;
			if (stack == null) {
				return LmdbUtil.readTransaction(env, borrowed, transaction);
			}
			try (MemoryStack frame = stack.push()) {
				return transaction.exec(stack, borrowed);
			}
		}
		return withValueReadTransaction(null, transaction);
	}

	<T> T writeTransaction(Transaction<T> transaction) throws IOException {
		checkReplayFailure();
		if (writeTxn != 0) {
			if (!isWriteTransactionOwner()) {
				return withWriterLookupContext((stack, txn) -> writeTransaction(transaction));
			}
			try (MemoryStack stack = MemoryStack.stackPush()) {
				T result = transaction.exec(stack, writeTxn);
				nativeMutation = true;
				return result;
			} catch (LmdbUtil.MapFullException mapFull) {
				TxnReplayPolicy.Decision decision = replayDecision;
				if (autoGrow && decision != null && decision.frozenReplay) {
					throw frozenCapacity(mapFull);
				}
				if (autoGrow && decision != null && !decision.track) {
					growForTransactionRetry(0L, mapFull, decision);
				}
				throw mapFull;
			}
		} else {
			beginValueLookupMutation();
			ValueOverlayRegistry.Prepared[] publication = new ValueOverlayRegistry.Prepared[1];
			long[] nativeTransactionId = new long[1];
			long[] priorNativeTransactionId = new long[1];
			boolean committed = false;
			long expectedNativeTransactionId = startupInitializationInProgress
					? startupExpectedLastTransactionId
					: lastTrustedNativeTransactionId;
			try {
				T result = LmdbUtil.writeTransaction(env, (stack, txn) -> {
					validateNativeWriterTransaction(txn, expectedNativeTransactionId);
					beginCompressedValueMutation(txn);
					T out = transaction.exec(stack, txn);
					persistNextId(stack, txn);
					updateRefCounts(stack, txn);
					publication[0] = prepareCompressedValueMutation(txn);
					nativeTransactionId[0] = mdb_txn_id(txn);
					priorNativeTransactionId[0] = lastTransactionId();
					return out;
				});
				// The utility returns only after successful native commit. Record that boundary before optional
				// publication or
				// cleanup, so callers retain committed fresh-value bookkeeping when those later steps fail.
				lastNativeCommitSucceeded = true;
				refCountsTxCache.clear();
				committed = true;
				retiredIdStore.transactionCommitted();
				nativeCommitGeneration++;
				mutationGeneration++;
				refreshCommittedHighWater();
				long observedNativeTransactionId = trustedPostCommitTransactionId(nativeTransactionId[0],
						priorNativeTransactionId[0]);
				if (refCountIntegrityEstablished || bulkNativeOwnership) {
					lastTrustedNativeTransactionId = observedNativeTransactionId;
				}
				// Never publish from inside the native transaction callback.
				completeCompressedValueMutation(publication[0]);
				return result;
			} finally {
				if (!committed) {
					retiredIdStore.transactionRolledBack();
					// The native writer was aborted; discard deltas and invalidate all value revisions so an aborted ID
					// cannot
					// be served from a cache on the next transaction.
					refCountsTxCache.clear();
					clearCaches();
					setNewRevision();
				}
				if (publication[0] != null)
					publication[0].close();
				discardCompressedValueMutation();
				try {
					resetReadersAfterWrite();
				} finally {
					endValueLookupMutation();
				}
			}
		}
	}

	private void resetReadersAfterWrite() throws IOException {
		var lockManager = txnManager.lockManager();
		boolean readLocked = readContext.get().hasReadLock;
		if (readLocked) {
			lockManager.unlockRead(StampedLongAdderLockManager.READ_LOCK_STAMP);
		}
		long stamp = 0;
		try {
			stamp = lockManager.writeLock();
			txnManager.reset();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException(e);
		} finally {
			if (stamp != 0) {
				lockManager.unlockWrite(stamp);
			}
			if (readLocked) {
				boolean interrupted = Thread.interrupted();
				for (;;) {
					try {
						lockManager.readLock();
						break;
					} catch (InterruptedException e) {
						interrupted = true;
					}
				}
				if (interrupted) {
					Thread.currentThread().interrupt();
				}
			}
		}
	}

	private void persistNextId(MemoryStack stack, long txn) throws IOException {
		if (!coreDatatypeLiteralReferences || deferNextIdPersistence) {
			return;
		}
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(stack.bytes(new byte[] { NEXT_ID_KEY }));
		ByteBuffer encoded = stack.malloc(Long.BYTES + 1);
		Varint.writeUnsigned(encoded, nextId);
		MDBVal value = MDBVal.calloc(stack);
		value.mv_data(encoded.flip());
		E(mdb_put(txn, dbi, key, value, 0));
	}

	int compareRegion(ByteBuffer array1, int startIdx1, ByteBuffer array2, int startIdx2, int length) {
		int result = 0;
		for (int i = 0; result == 0 && i < length; i++) {
			result = (array1.get(startIdx1 + i) & 0xff) - (array2.get(startIdx2 + i) & 0xff);
		}
		return result;
	}

	// ---------------------------------------------------------------------------------------------------------
	// Language-tag key policy
	// ---------------------------------------------------------------------------------------------------------

	/**
	 * How language literals are keyed in the data-to-id direction of the value dictionary. {@code Literal.equals}
	 * compares language tags case-insensitively (RDF 1.1 Concepts 3.3 lower-cases them in the value space), so
	 * {@code "abc"@en} and {@code "abc"@EN} are one RDF term and must resolve to one id independent of whether the
	 * (equals-based) value-id cache is warm.
	 */
	enum LanguageTagKeyMode {
		/**
		 * Case variants resolve to one RDF term. Format 2 uses semantic owner lookup while retaining raw physical
		 * reverse keys for the old writer; format 6 uses canonical physical keys. Payload encoding is selected
		 * independently by {@link LmdbStoreFormat}: format 2 preserves the supplied spelling, while format 6 uses the
		 * {@code lowercase-v1} payload policy.
		 */
		CANONICAL,
		/**
		 * Legacy policy: the encoding is looked up byte-exactly. Only used for stores written before the canonical key
		 * existed that hold distinct ids for case variants of one term and therefore cannot simply be re-keyed (see
		 * {@link #migrateLanguageTagKeysIfNeeded()}), until {@link LmdbLanguageTagVariantMerge} has merged the variants
		 * when the LMDB store opens.
		 */
		BYTE_EXACT
	}

	LanguageTagKeyMode languageTagKeyMode() {
		return languageTagKeyMode;
	}

	private LanguageTagKeyMode initialLanguageTagKeyMode() {
		String policy = properties.getLanguageTagKey();
		if (StoreProperties.LANGUAGE_TAG_KEY_CANONICAL.equals(policy)) {
			return LanguageTagKeyMode.CANONICAL;
		}
		if (StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT.equals(policy)) {
			logger.info("LMDB value store {} still keys language literals byte-exactly (case variants of one language "
					+ "tag, \"abc\"@en vs \"abc\"@EN, may be separate values); the LMDB store merges the variants and "
					+ "switches to canonical keys when it is opened", dir);
			return LanguageTagKeyMode.BYTE_EXACT;
		}
		// no recorded policy: a store written before the policy existed, or a new (empty) store. Byte-exact until
		// migrateLanguageTagKeysIfNeeded has inspected the data - the policy is derived from the data rather than from
		// whether store.properties could be loaded, so existing entries can never become unreachable
		return LanguageTagKeyMode.BYTE_EXACT;
	}

	/**
	 * Returns the physical data-to-id key. A legacy writer must be able to reclaim every reverse association, so format
	 * 2 always keeps its raw encoding; its canonical RDF matching is separate from physical key identity.
	 */
	private byte[] lookupKey(byte[] data) {
		return !format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
				? canonicalLanguageKey(data)
				: data;
	}

	private byte[][] lookupKeys(byte[][] data, int count) {
		if (format.isLegacy() || languageTagKeyMode != LanguageTagKeyMode.CANONICAL) {
			return data;
		}
		byte[][] keys = data;
		for (int i = 0; i < count; i++) {
			byte[] key = canonicalLanguageKey(data[i]);
			if (key != data[i]) {
				if (keys == data) {
					keys = Arrays.copyOf(data, data.length);
				}
				keys[i] = key;
			}
		}
		return keys;
	}

	/**
	 * The language-tag range ({@link #languageTagRange(ByteBuffer)}) of a lookup key, or -1 when stored payloads must
	 * match the key byte-exactly.
	 */
	private long lookupLanguageRange(byte[] key) {
		return !format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
				? languageTagRange(ByteBuffer.wrap(key))
				: -1L;
	}

	/**
	 * Returns the encoding with the ASCII letters of its language tag lower-cased, or {@code data} itself (same array)
	 * when it is not a language literal or the tag is already lower case. The lower-cased form has the same length, so
	 * the short-key / hash-path decision is identical for key and payload.
	 */
	static byte[] canonicalLanguageKey(byte[] data) {
		return ValueStoreRecordCodec.canonicalLanguageKey(data);
	}

	private static boolean hasUpperCaseLanguageTag(ByteBuffer data) {
		long range = languageTagRange(data);
		if (range < 0) {
			return false;
		}
		int position = data.position();
		for (int i = (int) (range >>> 32); i < (int) range; i++) {
			if (isAsciiUpperCase(data.get(position + i))) {
				return true;
			}
		}
		return false;
	}

	private static boolean isAsciiUpperCase(byte b) {
		return b >= 'A' && b <= 'Z';
	}

	/**
	 * Locates the language tag inside an encoded literal ({@code [LITERAL_VALUE][varint datatype id][direction |
	 * language length, or 0xC0 | direction followed by a varint length][language][label]}).
	 *
	 * @return {@code start << 32 | end} of the tag relative to the buffer position, or -1 when the encoding is not a
	 *         literal with a language tag
	 */
	private static long languageTagRange(ByteBuffer data) {
		return ValueStoreRecordCodec.languageTagRange(data);
	}

	/**
	 * Whether a stored payload denotes the value looked up by {@code key}: byte-equal outside the language tag and,
	 * inside it, equal up to ASCII case ({@code key} carries the lower-cased tag). With {@code languageRange < 0} this
	 * is plain byte equality.
	 */
	private static boolean payloadMatchesKey(ByteBuffer payload, byte[] key, long languageRange) {
		if (payload.remaining() != key.length) {
			return false;
		}
		int position = payload.position();
		int langStart = languageRange < 0 ? 0 : (int) (languageRange >>> 32);
		int langEnd = languageRange < 0 ? 0 : (int) languageRange;
		for (int i = 0; i < key.length; i++) {
			byte stored = payload.get(position + i);
			if (stored != key[i]) {
				if (i < langStart || i >= langEnd || !isAsciiUpperCase(stored)
						|| (byte) (stored + ('a' - 'A')) != key[i]) {
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * Establishes the canonical RDF lookup policy and its format-specific physical representation. A Sail-owned legacy
	 * store waits for the triple-aware variant merge; a bare dictionary leaves ambiguous owners unchanged. Valid legacy
	 * canonical-only or dual-key owners are normalized to raw keys, including already-marked stores. Format 6 retains
	 * its canonical physical migration and explicit byte-exact dictionaries retain their policy.
	 */
	private void migrateLanguageTagKeysIfNeeded() throws IOException {
		if (format.isLegacy() && deferPersistedUnusedRecovery) {
			// A raw spelling may belong to a distinct live old-writer variant. Only the Sail's existing
			// statement rewrite/retirement protocol may choose a survivor before restoring that raw key.
			return;
		}
		String policy = properties.getLanguageTagKey();
		if (policy != null && (!format.isLegacy() || !StoreProperties.LANGUAGE_TAG_KEY_CANONICAL.equals(policy))) {
			return;
		}
		LanguageTagRekey rekey;
		startTransaction(true);
		try {
			rekey = writeTransaction(this::rekeyLanguageTagKeys);
			commit();
		} catch (IOException | RuntimeException e) {
			rollback();
			throw e;
		}
		if (rekey.collisions() > 0) {
			logger.info("LMDB value store {} holds {} language literal(s) whose language tag differs only in case "
					+ "from another stored literal ({} literals scanned). They received distinct ids before this "
					+ "version; the LMDB store merges them into one value when it is opened.", dir,
					rekey.collisions(), rekey.literals());
			if (policy == null) {
				properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT);
			}
			return;
		}
		if (rekey.rekeyed() > 0) {
			logger.info("LMDB value store {} now uses canonical language-literal identity; {} of {} literal owner "
					+ "mappings were normalized", dir, rekey.rekeyed(), rekey.literals());
		}
		properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_CANONICAL);
		languageTagKeyMode = LanguageTagKeyMode.CANONICAL;
	}

	private record LegacyLanguageTagEntry(long id, byte[] data, byte[] key) {
	}

	/**
	 * Outcome of {@link #rekeyLanguageTagKeys}: the number of language literals that collide with another stored
	 * literal under canonical identity (nothing is changed then), the number normalized, and the literals scanned.
	 */
	private record LanguageTagRekey(int collisions, int rekeyed, long literals) {
	}

	/**
	 * Establishes format-specific physical ownership unless canonical identity would merge distinct live owners. Format
	 * 6 uses canonical keys; format 2 restores the raw spelling and removes extra canonical associations.
	 */
	private LanguageTagRekey rekeyLanguageTagKeys(MemoryStack stack, long txn) throws IOException {
		if (format.isLegacy()) {
			return normalizeLegacyLanguageOwnerKeys(stack, txn);
		}
		List<LegacyLanguageTagEntry> entries = new ArrayList<>();
		Set<ByteBuffer> canonicalKeys = new HashSet<>();
		int collisions = 0;
		long literals = 0;
		PointerBuffer pp = stack.mallocPointer(1);
		E(mdb_cursor_open(txn, dbi, pp));
		long cursor = pp.get(0);
		try {
			MDBVal keyVal = MDBVal.calloc(stack);
			MDBVal dataVal = MDBVal.calloc(stack);
			keyVal.mv_data(stack.bytes(new byte[] { ID_KEY }));
			int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
			while (rc == MDB_SUCCESS && keyVal.mv_data().get(0) == ID_KEY) {
				ByteBuffer payload = dataVal.mv_data();
				if (payload.remaining() > 0 && payload.get(0) == LITERAL_VALUE) {
					literals++;
					if (hasUpperCaseLanguageTag(payload)) {
						byte[] data = new byte[payload.remaining()];
						payload.get(data);
						byte[] key = canonicalLanguageKey(data);
						long id = data2id(keyVal.mv_data());
						if (!ownsReverseKey(stack, txn, id, data) && !ownsReverseKey(stack, txn, id, key)) {
							// Retired payloads remain available to pinned readers but own no live reverse association.
							rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
							continue;
						}
						// canonical lookup of the key: an entry stored with the lower-case spelling, or one already
						// re-keyed, is found under it
						long canonicalId = findId(key, key, languageTagRange(ByteBuffer.wrap(key)), false);
						// An existing canonical association is complete only when the legacy owner spelling is
						// also retained. Repair a prior canonical-only generation without creating another owner.
						if (canonicalId != id || format.isLegacy() && !ownsReverseKey(stack, txn, id, data)) {
							if (canonicalId != id && (canonicalId != LmdbValue.UNKNOWN_ID
									|| !canonicalKeys.add(ByteBuffer.wrap(key)))) {
								// another id already denotes the same term
								collisions++;
							}
							entries.add(new LegacyLanguageTagEntry(id, data, key));
						}
					}
				}
				rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
			}
		} finally {
			mdb_cursor_close(cursor);
		}

		if (collisions > 0) {
			return new LanguageTagRekey(collisions, 0, literals);
		}

		if (!entries.isEmpty()) {
			resizeMap(txn, entries.size() * 4L * (MAX_KEY_SIZE + 2L + 2L * Long.BYTES + 2L));
			long writeTxn = currentWriteTxn(txn);
			for (LegacyLanguageTagEntry entry : entries) {
				stack.push();
				try {
					ByteBuffer idBb = id2data(idBuffer(stack), entry.id()).flip();
					if (entry.key().length <= MAX_KEY_SIZE) {
						MDBVal oldKeyVal = MDBVal.calloc(stack);
						oldKeyVal.mv_data(stack.bytes(entry.data()));
						if (!format.isLegacy()) {
							mdb_del(writeTxn, dbi, oldKeyVal, null);
						}
						MDBVal newKeyVal = MDBVal.calloc(stack);
						newKeyVal.mv_data(stack.bytes(entry.key()));
						MDBVal idVal = MDBVal.calloc(stack);
						idVal.mv_data(idBb);
						E(mdb_put(writeTxn, dbi, newKeyVal, idVal, 0));
					} else {
						if (!format.isLegacy()) {
							removeHashAssociation(stack, writeTxn, hash(entry.data()), idBb);
						}
						addHashAssociation(stack, writeTxn, hash(entry.key()), idBb);
					}
					retainLegacyLanguageOwnerKey(stack, writeTxn, entry.data(), entry.key(), entry.id());
				} finally {
					stack.pop();
				}
			}
		}
		return new LanguageTagRekey(0, entries.size(), literals);
	}

	/**
	 * Restores raw physical ownership from actual live owner bytes, then drops only that owner's extra canonical
	 * association. The complete planning pass precedes every write: a bare dictionary cannot resolve live variants
	 * without their statements, and must not steal a raw key before the Sail's triple-aware merge.
	 */
	private LanguageTagRekey normalizeLegacyLanguageOwnerKeys(MemoryStack stack, long txn) throws IOException {
		List<LegacyLanguageTagEntry> entries = new ArrayList<>();
		Set<ByteBuffer> canonicalKeys = new HashSet<>();
		int collisions = 0;
		long literals = 0;
		PointerBuffer pointer = stack.mallocPointer(1);
		E(mdb_cursor_open(txn, dbi, pointer));
		long cursor = pointer.get(0);
		try {
			MDBVal ownerKey = MDBVal.calloc(stack).mv_data(stack.bytes(new byte[] { ID_KEY }));
			MDBVal ownerValue = MDBVal.calloc(stack);
			int rc = mdb_cursor_get(cursor, ownerKey, ownerValue, MDB_SET_RANGE);
			while (rc == MDB_SUCCESS && isIdKey(ownerKey.mv_data())) {
				ByteBuffer payload = ownerValue.mv_data();
				if (payload.hasRemaining() && payload.get(payload.position()) == LITERAL_VALUE) {
					literals++;
					if (hasUpperCaseLanguageTag(payload)) {
						byte[] data = copyValue(ownerValue);
						byte[] key = canonicalLanguageKey(data);
						long id = data2id(ownerKey.mv_data().duplicate());
						boolean rawOwner = ownsReverseKey(stack, txn, id, data);
						boolean canonicalOwner = ownsReverseKey(stack, txn, id, key);
						if (rawOwner || canonicalOwner) {
							long canonicalId = findId(key, key, languageTagRange(ByteBuffer.wrap(key)), false);
							long rawId = findId(data, data, -1L, false);
							boolean distinctOwner = canonicalId != LmdbValue.UNKNOWN_ID && canonicalId != id;
							boolean duplicate = !canonicalKeys.add(ByteBuffer.wrap(key));
							if (distinctOwner || duplicate || rawId != LmdbValue.UNKNOWN_ID && rawId != id) {
								collisions++;
							}
							boolean distinctKey = data.length <= MAX_KEY_SIZE || hash(data) != hash(key);
							if (!rawOwner || canonicalOwner && distinctKey) {
								entries.add(new LegacyLanguageTagEntry(id, data, key));
							}
						}
					}
				}
				rc = mdb_cursor_get(cursor, ownerKey, ownerValue, MDB_NEXT);
			}
			if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
				E(rc);
			}
		} finally {
			mdb_cursor_close(cursor);
		}
		if (collisions > 0) {
			return new LanguageTagRekey(collisions, 0, literals);
		}
		if (!entries.isEmpty()) {
			resizeMap(txn, entries.size() * 4L * (MAX_KEY_SIZE + 2L + 2L * Long.BYTES + 2L));
			long activeTxn = currentWriteTxn(txn);
			for (LegacyLanguageTagEntry entry : entries) {
				stack.push();
				try {
					retainLegacyLanguageOwnerKey(stack, activeTxn, entry.data(), entry.key(), entry.id());
					if (entry.data().length <= MAX_KEY_SIZE || hash(entry.data()) != hash(entry.key())) {
						removeOwnedReverseKey(stack, activeTxn, entry.id(), entry.key());
					}
				} finally {
					stack.pop();
				}
			}
		}
		return new LanguageTagRekey(0, entries.size(), literals);
	}

	/**
	 * Plans the merge of the ids that denote one RDF term in a {@link LanguageTagKeyMode#BYTE_EXACT} store (see
	 * {@link LmdbLanguageTagVariantMerge}): every group of case variants of one language literal, and every triple term
	 * that becomes equal to another one once its components are replaced by their survivors. It only reads, and the
	 * plan depends on nothing but the stored values, so a merge that was interrupted before
	 * {@link #applyLanguageTagVariantMerge} committed plans the same merge again.
	 */
	LanguageTagVariantMergePlan planLanguageTagVariantMerge() throws IOException {
		LanguageTagVariantMergePlan plan = new LanguageTagVariantMergePlan();
		// a write transaction that is rolled back: the nested lookups (findId, findTripleTermId) then read the same
		// snapshot as the scans
		startTransaction(false);
		try {
			writeTransaction((stack, txn) -> {
				planLanguageLiteralGroups(plan, stack, txn);
				if (!plan.isEmpty()) {
					planTripleTermMerges(plan, stack, txn);
				}
				return null;
			});
		} finally {
			rollback();
		}
		return plan;
	}

	private void planLanguageLiteralGroups(LanguageTagVariantMergePlan plan, MemoryStack stack, long txn)
			throws IOException {
		Map<ByteBuffer, LongArrayList> variantsByKey = new LinkedHashMap<>();
		PointerBuffer pp = stack.mallocPointer(1);
		E(mdb_cursor_open(txn, dbi, pp));
		long cursor = pp.get(0);
		try {
			MDBVal keyVal = MDBVal.calloc(stack);
			MDBVal dataVal = MDBVal.calloc(stack);
			keyVal.mv_data(stack.bytes(new byte[] { ID_KEY }));
			int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
			while (rc == MDB_SUCCESS && keyVal.mv_data().get(0) == ID_KEY) {
				ByteBuffer payload = dataVal.mv_data();
				if (payload.remaining() > 0 && payload.get(0) == LITERAL_VALUE && hasUpperCaseLanguageTag(payload)) {
					byte[] data = new byte[payload.remaining()];
					payload.get(data);
					byte[] key = canonicalLanguageKey(data);
					long id = data2id(keyVal.mv_data());
					if (!ownsReverseKey(stack, txn, id, data) && !ownsReverseKey(stack, txn, id, key)) {
						rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
						continue;
					}
					plan.countUpperCaseLanguageLiteral();
					LongArrayList variants = variantsByKey.get(ByteBuffer.wrap(key));
					if (variants == null) {
						variants = new LongArrayList(2);
						// the variant spelled in lower case is stored under exactly the canonical key
						long lowerCaseId = findId(key, key, -1L, false);
						if (lowerCaseId != LmdbValue.UNKNOWN_ID && lowerCaseId != id) {
							variants.add(lowerCaseId);
						}
						variantsByKey.put(ByteBuffer.wrap(key), variants);
					}
					if (!variants.contains(id)) {
						variants.add(id);
					}
				}
				rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
			}
		} finally {
			mdb_cursor_close(cursor);
		}
		for (LongArrayList variants : variantsByKey.values()) {
			if (variants.size() > 1) {
				plan.addLiteralGroup(variants);
			}
		}
	}

	private record TripleTermComponents(long subject, long predicate, long object) {
	}

	/**
	 * Groups the triple terms whose components, resolved through the merges planned so far, are equal - including every
	 * triple term already stored with exactly those components - and lets the smallest id survive. Triple terms stored
	 * twice with identical components (left behind when a merge was interrupted after rewriting a survivor) are grouped
	 * as well. Repeats until nothing changes, so a triple term nested in a merged triple term is merged too.
	 */
	private void planTripleTermMerges(LanguageTagVariantMergePlan plan, MemoryStack stack, long txn)
			throws IOException {
		boolean changed = true;
		while (changed) {
			Map<TripleTermComponents, LongArrayList> membersByComponents = new LinkedHashMap<>();
			Long2ObjectLinkedOpenHashMap<long[]> storedById = new Long2ObjectLinkedOpenHashMap<>();
			stack.push();
			try {
				PointerBuffer pp = stack.mallocPointer(1);
				E(mdb_cursor_open(txn, tripleTermSpocIndex.getDB(true), pp));
				long cursor = pp.get(0);
				try {
					MDBVal keyVal = MDBVal.calloc(stack);
					MDBVal dataVal = MDBVal.calloc(stack);
					long[] quad = new long[4];
					long[] previous = null;
					int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_FIRST);
					while (rc == MDB_SUCCESS) {
						tripleTermSpocIndex.keyToQuad(keyVal.mv_data(), quad);
						long id = quad[TripleIndex.CONTEXT_IDX];
						TripleTermComponents resolved = new TripleTermComponents(
								plan.resolve(quad[TripleIndex.SUBJ_IDX]), plan.resolve(quad[TripleIndex.PRED_IDX]),
								plan.resolve(quad[TripleIndex.OBJ_IDX]));
						if (resolved.subject() != quad[TripleIndex.SUBJ_IDX]
								|| resolved.predicate() != quad[TripleIndex.PRED_IDX]
								|| resolved.object() != quad[TripleIndex.OBJ_IDX]) {
							storedById.put(id, new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
									quad[TripleIndex.OBJ_IDX] });
							addTripleTermMember(membersByComponents, resolved, id);
						} else if (previous != null && previous[0] == quad[0] && previous[1] == quad[1]
								&& previous[2] == quad[2]) {
							// the index is sorted by components, so triple terms stored twice are adjacent
							addTripleTermMember(membersByComponents, resolved, previous[3]);
							addTripleTermMember(membersByComponents, resolved, id);
						}
						previous = quad.clone();
						rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
					}
				} finally {
					mdb_cursor_close(cursor);
				}
			} finally {
				stack.pop();
			}

			Long2LongOpenHashMap survivorByLoser = new Long2LongOpenHashMap();
			Long2ObjectLinkedOpenHashMap<long[]> losers = new Long2ObjectLinkedOpenHashMap<>();
			Long2ObjectLinkedOpenHashMap<long[]> rewrites = new Long2ObjectLinkedOpenHashMap<>();
			for (Map.Entry<TripleTermComponents, LongArrayList> group : membersByComponents.entrySet()) {
				TripleTermComponents components = group.getKey();
				LongArrayList members = group.getValue();
				// triple terms stored with exactly the resolved components mention no losing id, so they were not
				// collected above; they denote the same term and join the group
				LongArrayList existing = tripleTermIds(stack, txn, components);
				for (int i = 0; i < existing.size(); i++) {
					if (!members.contains(existing.getLong(i))) {
						members.add(existing.getLong(i));
					}
				}
				long survivor = Long.MAX_VALUE;
				for (int i = 0; i < members.size(); i++) {
					survivor = Math.min(survivor, members.getLong(i));
				}
				long[] resolved = { components.subject(), components.predicate(), components.object() };
				for (int i = 0; i < members.size(); i++) {
					long member = members.getLong(i);
					// members that were not collected as affected are stored with the resolved components
					long[] stored = storedById.containsKey(member) ? storedById.get(member) : resolved;
					if (member != survivor) {
						survivorByLoser.put(member, survivor);
						losers.put(member, stored);
					} else if (storedById.containsKey(member)) {
						rewrites.put(member, new long[] { stored[0], stored[1], stored[2], resolved[0], resolved[1],
								resolved[2] });
					}
				}
			}
			changed = plan.replaceTripleTermMerges(survivorByLoser, losers, rewrites);
		}
	}

	private static void addTripleTermMember(Map<TripleTermComponents, LongArrayList> membersByComponents,
			TripleTermComponents components, long id) {
		LongArrayList members = membersByComponents.computeIfAbsent(components, ignored -> new LongArrayList(2));
		if (!members.contains(id)) {
			members.add(id);
		}
	}

	/** The ids of every triple term stored with exactly the given components. */
	private LongArrayList tripleTermIds(MemoryStack stack, long txn, TripleTermComponents components)
			throws IOException {
		LongArrayList ids = new LongArrayList(1);
		stack.push();
		try {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, tripleTermSpocIndex.getDB(true), pp));
			long cursor = pp.get(0);
			try {
				MDBVal keyVal = MDBVal.calloc(stack);
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				tripleTermSpocIndex.getMinKey(keyBuf, components.subject(), components.predicate(),
						components.object(), -1);
				keyBuf.flip();
				keyVal.mv_data(keyBuf);
				GroupMatcher matcher = tripleTermSpocIndex.createMatcher(components.subject(),
						components.predicate(), components.object(), -1);
				long[] quad = new long[4];
				int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_SET_RANGE);
				while (rc == MDB_SUCCESS && matcher.matches(keyVal.mv_data())) {
					tripleTermSpocIndex.keyToQuad(keyVal.mv_data(), quad);
					ids.add(quad[TripleIndex.CONTEXT_IDX]);
					rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
				}
			} finally {
				mdb_cursor_close(cursor);
			}
		} finally {
			stack.pop();
		}
		return ids;
	}

	/**
	 * Test seam: when it accepts the number of a completed step of {@link #applyLanguageTagVariantMerge} (1 surviving
	 * triple terms rewritten, 2 losing triple terms retired, 3 losing literals retired), the work so far is committed -
	 * as a map resize at that point would - and the merge fails as if the process had died.
	 */
	static volatile IntPredicate crashAfterLanguageTagMergeStepForTesting;

	/**
	 * Carries out a {@link LanguageTagVariantMergePlan} after every statement of the triple store has been rewritten to
	 * the surviving ids, then establishes canonical RDF lookup with the format-specific physical keys and switches this
	 * store to {@link LanguageTagKeyMode#CANONICAL}. Runs in one write transaction; if the value map grows mid-way, the
	 * work done so far is committed early, and every such prefix is a state from which
	 * {@link #planLanguageTagVariantMerge} plans the rest of the merge: surviving triple terms are rewritten first
	 * (they then have the resolved components and are no longer affected), each losing id is retired as a whole
	 * (deleted, marked unused, hash cleared), losing triple terms before losing literals (so no triple term refers to a
	 * deleted literal), and physical key normalization comes last and skips owners already in their final format.
	 *
	 * @throws IOException if a language literal still collides with another one after the merge (the transaction is
	 *                     rolled back and the store stays byte-exact)
	 */
	void applyLanguageTagVariantMerge(LanguageTagVariantMergePlan plan) throws IOException {
		LanguageTagRekey rekey;
		startTransaction(true);
		try {
			rekey = writeTransaction((stack, txn) -> {
				if (!plan.isEmpty()) {
					resizeMap(txn, languageTagVariantMergeBytes(plan));
					rewriteSurvivingTripleTerms(plan, stack, currentWriteTxn(txn));
					languageTagMergeStepDone(1);
					retireLosingTripleTerms(plan, stack, currentWriteTxn(txn));
					languageTagMergeStepDone(2);
					retireLosingLiterals(plan, stack, currentWriteTxn(txn));
					languageTagMergeStepDone(3);
				}
				LanguageTagRekey result = rekeyLanguageTagKeys(stack, currentWriteTxn(txn));
				if (result.collisions() > 0) {
					throw new IOException("LMDB value store " + dir + " still holds " + result.collisions()
							+ " language literal(s) that collide with another stored literal after merging the case "
							+ "variants of language tags");
				}
				return result;
			});
			if (!plan.isEmpty()) {
				// values handed out before the merge may carry a losing id
				invalidateRevisionOnCommit = true;
			}
			commit();
		} catch (IOException | RuntimeException e) {
			rollback();
			throw e;
		}
		if (rekey.rekeyed() > 0) {
			logger.info("LMDB value store {} now uses canonical language-literal identity; {} of {} literal owner "
					+ "mappings were normalized", dir, rekey.rekeyed(), rekey.literals());
		}
		properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_CANONICAL);
		languageTagKeyMode = LanguageTagKeyMode.CANONICAL;
	}

	private void languageTagMergeStepDone(int step) throws IOException {
		IntPredicate crash = crashAfterLanguageTagMergeStepForTesting;
		if (crash != null && crash.test(step)) {
			endTransaction(true, true);
			throw new IOException("simulated crash after step " + step + " of the language-tag variant merge");
		}
	}

	/** Upper bound of the map space the merge and the subsequent re-keying need. */
	private long languageTagVariantMergeBytes(LanguageTagVariantMergePlan plan) {
		long tripleTermKeys = (2L * plan.tripleTermRewrites().size() + plan.loserTripleTerms().size())
				* tripleTermIndexes.size();
		long entries = tripleTermKeys + 4L * plan.loserCount() + 4L * plan.upperCaseLanguageLiterals();
		return 2L * entries * (TripleIndex.MAX_KEY_LENGTH + MAX_KEY_SIZE + 2L * Long.BYTES + 4L);
	}

	private void rewriteSurvivingTripleTerms(LanguageTagVariantMergePlan plan, MemoryStack stack, long writeTxn)
			throws IOException {
		for (Long2ObjectMap.Entry<long[]> rewrite : plan.tripleTermRewrites().long2ObjectEntrySet()) {
			long id = rewrite.getLongKey();
			long[] components = rewrite.getValue();
			writeTripleTermKeys(stack, writeTxn, components[0], components[1], components[2], id, false);
			writeTripleTermKeys(stack, writeTxn, components[3], components[4], components[5], id, true);
			for (int i = 0; i < 3; i++) {
				if (components[i] != components[i + 3]) {
					incrementRefCount(stack, writeTxn, components[i + 3]);
					decrementRefCount(stack, writeTxn, components[i]);
				}
			}
			clearStoredHash(id);
		}
	}

	private void retireLosingTripleTerms(LanguageTagVariantMergePlan plan, MemoryStack stack, long writeTxn)
			throws IOException {
		for (Long2ObjectMap.Entry<long[]> loser : plan.loserTripleTerms().long2ObjectEntrySet()) {
			long id = loser.getLongKey();
			long[] components = loser.getValue();
			writeTripleTermKeys(stack, writeTxn, components[0], components[1], components[2], id, false);
			for (int i = 0; i < 3; i++) {
				decrementRefCount(stack, writeTxn, components[i]);
			}
			retireMergedId(stack, writeTxn, id);
		}
	}

	/** Puts ({@code put}) or deletes the keys of one triple term in every triple-term index. */
	private void writeTripleTermKeys(MemoryStack stack, long writeTxn, long subject, long predicate, long object,
			long id, boolean put) throws IOException {
		stack.push();
		try {
			MDBVal keyVal = MDBVal.calloc(stack);
			MDBVal dataVal = MDBVal.calloc(stack);
			ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
			for (TripleIndex index : tripleTermIndexes) {
				keyBuf.clear();
				index.toKey(keyBuf, subject, predicate, object, id);
				keyBuf.flip();
				keyVal.mv_data(keyBuf);
				if (put) {
					E(mdb_put(writeTxn, index.getDB(true), keyVal, dataVal, 0));
				} else {
					E(mdb_del(writeTxn, index.getDB(true), keyVal, null));
				}
			}
		} finally {
			stack.pop();
		}
	}

	/**
	 * Deletes each losing language literal - its byte-exact data-to-id entry (short key or hash association), its
	 * reference to the datatype and its id-to-data entry - and retires its id.
	 */
	private void retireLosingLiterals(LanguageTagVariantMergePlan plan, MemoryStack stack, long writeTxn)
			throws IOException {
		LongArrayList losers = plan.loserLiterals();
		for (int i = 0; i < losers.size(); i++) {
			long id = losers.getLong(i);
			stack.push();
			try {
				ByteBuffer idBb = id2data(idBuffer(stack), id).flip();
				MDBVal idVal = MDBVal.calloc(stack);
				idVal.mv_data(idBb);
				MDBVal dataVal = MDBVal.calloc(stack);
				if (mdb_get(writeTxn, dbi, idVal, dataVal) != MDB_SUCCESS) {
					continue;
				}
				byte[] data = new byte[dataVal.mv_data().remaining()];
				dataVal.mv_data().get(data);
				removeOwnedReverseKey(stack, writeTxn, id, data);
				byte[] canonical = canonicalLanguageKey(data);
				if (canonical != data && (data.length <= MAX_KEY_SIZE || hash(data) != hash(canonical))) {
					removeOwnedReverseKey(stack, writeTxn, id, canonical);
				}
				// the datatype of a language literal (rdf:langString / rdf:dirLangString) is seeded and never collected
				decrementRefCount(stack, writeTxn, Varint.readUnsigned(data, 1));
				E(mdb_del(writeTxn, dbi, idVal, null));
				retireMergedId(stack, writeTxn, id);
			} finally {
				stack.pop();
			}
		}
	}

	/**
	 * Drops the reference count of a losing id (nothing refers to it any more), clears its stored hash and marks it
	 * unused under the current revision, so the normal two-phase garbage collection puts it on the free list (at the
	 * latest when the store opens next).
	 */
	private void retireMergedId(MemoryStack stack, long writeTxn, long id) throws IOException {
		stack.push();
		try {
			ByteBuffer revIdBb = stack.malloc(1 + Long.BYTES + 2 + Long.BYTES);
			Varint.writeUnsigned(revIdBb, revision.getRevisionId());
			MDBVal revIdVal = MDBVal.calloc(stack);
			revIdVal.mv_data(id2data(revIdBb, id).flip());
			E(mdb_put(writeTxn, unusedDbi, revIdVal, MDBVal.calloc(stack), 0));
		} finally {
			stack.pop();
		}
		refCountsTxCache.put(id, 0L);
		clearStoredHash(id);
	}

	/** Ensures the actual legacy owner's raw spelling; routine raw writes already have data == key. */
	private void retainLegacyLanguageOwnerKey(MemoryStack stack, long txn, byte[] data, byte[] key, long id)
			throws IOException {
		if (!format.isLegacy() || data == key) {
			return;
		}
		stack.push();
		try {
			if (data.length <= MAX_KEY_SIZE) {
				MDBVal raw = MDBVal.calloc(stack).mv_data(stack.bytes(data));
				MDBVal mapped = MDBVal.calloc(stack);
				int rc = mdb_get(txn, dbi, raw, mapped);
				if (rc == MDB_SUCCESS && data2id(mapped.mv_data()) != id) {
					throw new IOException("Original language spelling maps to a different ValueStore owner");
				}
				if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
					E(rc);
				}
				MDBVal owner = MDBVal.calloc(stack).mv_data(id2data(idBuffer(stack), id).flip());
				E(mdb_put(txn, dbi, raw, owner, 0));
			} else if (hash(data) != hash(key)) {
				addHashAssociation(stack, txn, hash(data), id2data(idBuffer(stack), id).flip());
			}
		} finally {
			stack.pop();
		}
	}

	/** Tests one exact physical reverse association, independent of current semantic lookup policy. */
	private void removeOwnedReverseKey(MemoryStack stack, long txn, long id, byte[] key) throws IOException {
		stack.push();
		try {
			if (key.length > MAX_KEY_SIZE) {
				removeHashAssociation(stack, txn, hash(key), id2data(idBuffer(stack), id).flip());
				return;
			}
			MDBVal nativeKey = MDBVal.calloc(stack).mv_data(stack.bytes(key));
			MDBVal mapped = MDBVal.calloc(stack);
			int rc = mdb_get(txn, dbi, nativeKey, mapped);
			if (rc == MDB_SUCCESS && data2id(mapped.mv_data()) == id) {
				E(mdb_del(txn, dbi, nativeKey, null));
			} else if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
				E(rc);
			}
		} finally {
			stack.pop();
		}
	}

	private void addLegacyLanguageOwnerKeyReservation(PreparedValueFootprint footprint, byte[] data) {
		if (format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL) {
			addLegacyLanguageOwnerKeyReservation(footprint, ByteBuffer.wrap(data));
		}
	}

	private void addLegacyLanguageOwnerKeyReservation(PreparedValueFootprint footprint, ByteBuffer data) {
		if (format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
				&& hasUpperCaseLanguageTag(data)) {
			footprint.addMainEntry(data.remaining() <= MAX_KEY_SIZE ? data.remaining() : MAX_HASH_ID_KEY_BYTES,
					MAX_ID_KEY_BYTES);
		}
	}

	/**
	 * Removes the association of {@code dataHash} with the id encoded in {@code idBb}: either the first-entry
	 * {@code HASH_KEY} record (promoting the next {@code HASHID_KEY} collision record, if any, as
	 * {@link #deleteValueToIdMappings} does) or the id's own {@code HASHID_KEY} collision record.
	 */
	private void removeHashAssociation(MemoryStack stack, long writeTxn, long dataHash, ByteBuffer idBb)
			throws IOException {
		int maxHashKeyLength = 2 + 2 * Long.BYTES + 2;
		ByteBuffer hashBb = stack.malloc(maxHashKeyLength);
		hashBb.put(HASH_KEY);
		Varint.writeUnsigned(hashBb, dataHash);
		int hashLength = hashBb.position();
		hashBb.flip();
		MDBVal hashVal = MDBVal.calloc(stack);
		hashVal.mv_data(hashBb);
		MDBVal dataVal = MDBVal.calloc(stack);

		byte[] idBytes = new byte[idBb.remaining()];
		idBb.duplicate().get(idBytes);
		if (mdb_get(writeTxn, dbi, hashVal, dataVal) == MDB_SUCCESS && bufferEquals(dataVal.mv_data(), idBytes)) {
			E(mdb_del(writeTxn, dbi, hashVal, null));
			// promote the first collision record for this hash, if any, to the first-entry record
			ByteBuffer hashIdBb = stack.malloc(maxHashKeyLength);
			hashIdBb.put(HASHID_KEY);
			Varint.writeUnsigned(hashIdBb, dataHash);
			hashIdBb.flip();
			MDBVal hashIdVal = MDBVal.calloc(stack);
			hashIdVal.mv_data(hashIdBb);
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(writeTxn, dbi, pp));
			long cursor = pp.get(0);
			try {
				if (mdb_cursor_get(cursor, hashIdVal, dataVal, MDB_SET_RANGE) == MDB_SUCCESS
						&& compareRegion(hashIdVal.mv_data(), 0, hashIdBb, 0, hashLength) == 0) {
					ByteBuffer nextIdBb = hashIdVal.mv_data();
					nextIdBb.position(hashLength);
					MDBVal nextIdVal = MDBVal.calloc(stack);
					nextIdVal.mv_data(nextIdBb);
					hashVal.mv_data(hashBb);
					E(mdb_put(writeTxn, dbi, hashVal, nextIdVal, 0));
					E(mdb_cursor_del(cursor, 0));
				}
			} finally {
				mdb_cursor_close(cursor);
			}
		} else {
			ByteBuffer hashIdBb = stack.malloc(maxHashKeyLength + idBytes.length);
			hashIdBb.put(HASHID_KEY);
			Varint.writeUnsigned(hashIdBb, dataHash);
			hashIdBb.put(idBytes);
			hashIdBb.flip();
			MDBVal hashIdVal = MDBVal.calloc(stack);
			hashIdVal.mv_data(hashIdBb);
			mdb_del(writeTxn, dbi, hashIdVal, null);
		}
	}

	/**
	 * Associates {@code dataHash} with the id encoded in {@code idBb}: as the first-entry {@code HASH_KEY} record when
	 * the hash is new, else as a {@code HASHID_KEY} collision record (the layout {@link #findId(byte[], boolean)}
	 * reads).
	 */
	private void addHashAssociation(MemoryStack stack, long writeTxn, long dataHash, ByteBuffer idBb)
			throws IOException {
		int maxHashKeyLength = 2 + 2 * Long.BYTES + 2;
		ByteBuffer hashBb = stack.malloc(maxHashKeyLength);
		hashBb.put(HASH_KEY);
		Varint.writeUnsigned(hashBb, dataHash);
		hashBb.flip();
		MDBVal hashVal = MDBVal.calloc(stack);
		hashVal.mv_data(hashBb);
		MDBVal dataVal = MDBVal.calloc(stack);
		MDBVal idVal = MDBVal.calloc(stack);
		idVal.mv_data(idBb.duplicate());
		if (mdb_get(writeTxn, dbi, hashVal, dataVal) != MDB_SUCCESS) {
			E(mdb_put(writeTxn, dbi, hashVal, idVal, 0));
			return;
		}
		if (data2id(dataVal.mv_data()) == data2id(idBb.duplicate())) {
			return;
		}
		ByteBuffer hashIdBb = stack.malloc(maxHashKeyLength + idBb.remaining());
		hashIdBb.put(HASHID_KEY);
		Varint.writeUnsigned(hashIdBb, dataHash);
		hashIdBb.put(idBb.duplicate());
		hashIdBb.flip();
		MDBVal hashIdVal = MDBVal.calloc(stack);
		hashIdVal.mv_data(hashIdBb);
		dataVal.mv_data(stack.bytes());
		E(mdb_put(writeTxn, dbi, hashIdVal, dataVal, 0));
	}

	/**
	 * Gets the ID for the specified value.
	 *
	 * @param value A value.
	 * @return The ID for the specified value, or {@link LmdbValue#UNKNOWN_ID} if no such ID could be found.
	 * @throws IOException If an I/O error occurred.
	 */
	public long getId(Value value) throws IOException {
//		var t = refCountMap.compute(value, (k, v) -> {
//			if (v == null) {
//				return new AtomicLong(1);
//			} else {
//				v.incrementAndGet();
//				return v;
//			}
//		});
//		System.out.println("getId called for value: " + value + ", current ref count: " + t.get());
		return getId(value, false);
	}

	/**
	 * Identity of the current dictionary lookup view: both the read transaction and dictionary mutation generation.
	 * Calls during ANY active dictionary mutation decline caching, not only calls from its write owner. getId also
	 * consults shared positive caches; those can change independently of an individual reader's native snapshot. A
	 * completed mutation changes the generation even after rollback. Tokens retain no LMDB transaction or page. A cache
	 * must observe the same non-null identity before and after loading a result, including UNKNOWN.
	 */
	@InternalUseOnly
	public Object valueLookupScope() throws IOException {
		Object generation = valueLookupGeneration;
		if (generation == null) {
			return null;
		}
		return readTransaction(env, (stack, txn) -> valueLookupScope(generation, txn));
	}

	@InternalUseOnly
	public Object valueLookupScope(ReadSnapshot snapshot) throws IOException {
		if (snapshot.valueStore() != this) {
			throw new IllegalArgumentException("Read snapshot belongs to a different ValueStore");
		}
		synchronized (snapshot.txnRef()) {
			snapshot.ensureValid();
			if (!snapshot.dictionaryDetached()) {
				return snapshot;
			}
		}
		return valueLookupScope();
	}

	/** Reuse an already open native snapshot when validating lookup-local absence and namespace prefix proofs. */
	private Object valueLookupScope(Object generation, long txn) {
		if (generation == null || valueLookupGeneration != generation) {
			return null;
		}
		long snapshotId = mdb_txn_id(txn);
		DictionaryLookupScope token = dictionaryLookupScope;
		if (token == null || token.generation() != generation || token.snapshotId() != snapshotId) {
			synchronized (this) {
				token = dictionaryLookupScope;
				if (token == null || token.generation() != generation || token.snapshotId() != snapshotId) {
					token = new DictionaryLookupScope(generation, snapshotId);
					dictionaryLookupScope = token;
				}
			}
		}
		return valueLookupGeneration == generation ? token : null;
	}

	/** Current-view delta accounting; use retained stats for base/history/compaction reservations. */
	@InternalUseOnly
	public ValueOverlayRegistry.ViewStats compressedValueOverlayViewStats() {
		ValueOverlayRegistry registry = compressedValues;
		return registry == null
				? new ValueOverlayRegistry.ViewStats(-1L, -1L, 0, 0L, 0L, 0, 0L, 0L, 0L, null)
				: registry.viewStats();
	}

	/** Shared across configured stores, including physical memory pinned by retired snapshots. */
	@InternalUseOnly
	public org.eclipse.rdf4j.sail.lmdb.valueoverlay.OverlayMemoryBudget.Stats compressedValueOverlayRetainedMemoryStats() {
		ValueOverlayRegistry registry = compressedValues;
		return registry == null
				? new OverlayMemoryBudget.Stats(0L, 0L, 0L, 0L, 0L, 0L, 0L)
				: registry.retainedMemoryStats();
	}

	/**
	 * Startup warming and bounded maintenance diagnostics. The last reason also describes an intentionally disabled or
	 * invalid automatic warm-up; ordinary reads do not update these counters.
	 */
	@InternalUseOnly
	public ValueOverlayRegistry.MaintenanceStats compressedValueOverlayMaintenanceStats() {
		ValueOverlayRegistry registry = compressedValues;
		ValueOverlayRegistry.MaintenanceStats stats = registry == null
				? new ValueOverlayRegistry.MaintenanceStats(false, false, 0L, 0L, null)
				: registry.maintenanceStats();
		return new ValueOverlayRegistry.MaintenanceStats(stats.scheduled() || isValueOverlayWarmupInProgress(),
				stats.active() || valueOverlayWarmupActive, stats.refusals() + valueOverlayWarmupRefusals,
				stats.discarded() + valueOverlayWarmupDiscards,
				valueOverlayWarmupFailure == null ? stats.lastFailure() : valueOverlayWarmupFailure);
	}

	/** Explicit caller-scheduled maintenance; do not invoke from a dictionary write transaction. */
	@InternalUseOnly
	public int compactCompressedValueOverlay() {
		ValueOverlayRegistry registry = compressedValues;
		if (!valueOverlayEnabled || valueOverlayMaintenanceDeferred || registry == null) {
			return 0;
		}
		if (isWriteTransactionOwner()) {
			throw new IllegalStateException("Overlay compaction must run outside the dictionary writer");
		}
		return registry.compact();
	}

	private void beginCompressedValueMutation(long txn) {
		discardCompressedValueMutation();
		ValueOverlayRegistry registry = compressedValues;
		if (valueOverlayEnabled && !valueOverlayCaptureDeferred && registry != null && registry.isPopulated()) {
			compressedValueMutation = registry.begin(mdb_txn_id(txn));
		}
	}

	private void recordCompressedValueChange(long id) {
		if (compressedValueMutation != null)
			compressedValueMutation.touch(id);
	}

	private void discardCompressedValueMutation() {
		if (compressedValueMutation != null) {
			compressedValueMutation.close();
			compressedValueMutation = null;
		}
	}

	/** Seal FINAL write-transaction state, never transient bytes from an MDB_RESERVE buffer. */
	private ValueOverlayRegistry.Prepared prepareCompressedValueMutation(long txn) {
		ValueOverlayRegistry.Mutation mutation = compressedValueMutation;
		if (!valueOverlayEnabled || mutation == null)
			return null;
		try {
			if (mutation.transactionId() != mdb_txn_id(txn)) {
				return mutation.refused("native write transaction changed before capture");
			}
			return mutation.prepare(id -> {
				try (MemoryStack scratch = stackPush()) {
					MDBVal key = MDBVal.calloc(scratch);
					LmdbUtil.setMDBValData(key, id2data(idBuffer(scratch), id).flip());
					MDBVal value = MDBVal.calloc(scratch);
					int rc = mdb_get(txn, dbi, key, value);
					if (rc == MDB_NOTFOUND)
						return new ValueOverlayRegistry.Record(null, false);
					E(rc);
					long length = LmdbUtil.mdbValSize(value);
					if (length > mutation.maxRecordBytes())
						return new ValueOverlayRegistry.Record(null, false);
					byte[] record = new byte[Math.toIntExact(length)];
					LmdbUtil.copyMemoryToByteArray(LmdbUtil.mdbValDataAddress(value), record, record.length);
					Long live = mutation.requiresReverseMapping()
							? findIdInTransaction(record, false, CoreDatatype.NONE, scratch, txn)
							: null;
					return new ValueOverlayRegistry.Record(record, live != null && live.longValue() == id);
				}
			});
		} catch (IOException | RuntimeException failedOverlay) {
			// Optional acceleration must not turn a committed dictionary change into a half-published cache.
			logger.warn("Cannot prepare compressed ValueStore delta; commit will retire overlay", failedOverlay);
			return mutation.refused("delta preparation failed: " + failedOverlay.getClass().getSimpleName());
		}
	}

	private void completeCompressedValueMutation(ValueOverlayRegistry.Prepared publication) {
		if (publication == null)
			return;
		try (MemoryStack stack = stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(env, info));
			// LMDB may discard an empty write transaction. Check native metadata instead of inventing txn+1.
			compressedValues.complete(publication, info.me_last_txnid());
		} catch (IOException | RuntimeException failedOverlay) {
			compressedValues.invalidate();
			logger.warn("Cannot publish compressed ValueStore delta; using LMDB", failedOverlay);
		} finally {
			publication.close();
		}
	}

	private void commitCompressedValueTransaction(boolean[] nativeCommitSucceededSignal) throws IOException {
		long txn = writeTxn;
		long nativeTransactionId = mdb_txn_id(txn);
		long priorNativeTransactionId = lastTransactionId();
		int rc = mdb_txn_commit(txn);
		// Native commit consumes the transaction even on failure. Never leave a freed handle for rollback.
		writeTxn = 0;
		writeTxnOwner = null;
		if (rc != MDB_SUCCESS) {
			E(rc);
			return;
		}
		// Record success at the native boundary, before any optional publication or cleanup can fail. In particular,
		// a Sail-level caller must retain fresh-value bookkeeping when LMDB has committed but overlay publication
		// fails.
		lastNativeCommitSucceeded = true;
		if (nativeCommitSucceededSignal != null) {
			nativeCommitSucceededSignal[0] = true;
		}
		refCountsTxCache.clear();
		long observedNativeTransactionId = trustedPostCommitTransactionId(nativeTransactionId,
				priorNativeTransactionId);
		if (startupInitializationInProgress) {
			startupExpectedLastTransactionId = observedNativeTransactionId;
		}
		if (refCountIntegrityEstablished || bulkNativeOwnership) {
			lastTrustedNativeTransactionId = observedNativeTransactionId;
		}
	}

	private long trustedPostCommitTransactionId(long nativeTransactionId, long priorNativeTransactionId)
			throws IOException {
		long observedNativeTransactionId = lastTransactionId();
		if (observedNativeTransactionId != nativeTransactionId
				&& observedNativeTransactionId != priorNativeTransactionId) {
			invalidateRefCountIntegrity("an intervening native LMDB writer after commit");
			throw new IOException(
					"ValueStore detected an intervening native LMDB writer after commit: expected transaction "
							+ nativeTransactionId + " or no-op predecessor " + priorNativeTransactionId + " but found "
							+ observedNativeTransactionId);
		}
		return observedNativeTransactionId;
	}

	private void beginValueLookupMutation() {
		lastNativeCommitSucceeded = false;
		valueLookupGeneration = null;
	}

	private void validateNativeWriterTransaction(long txn, long expectedLastTransactionId) throws IOException {
		if ((!refCountIntegrityEstablished && !startupInitializationInProgress && !bulkNativeOwnership)
				|| expectedLastTransactionId < 0L) {
			return;
		}
		long expected;
		try {
			expected = Math.addExact(expectedLastTransactionId, 1L);
		} catch (ArithmeticException overflow) {
			throw new IOException("ValueStore native transaction ID overflow while validating writer ownership",
					overflow);
		}
		long actual = mdb_txn_id(txn);
		if (actual != expected) {
			invalidateRefCountIntegrity("an intervening native LMDB writer");
			throw new IOException("ValueStore detected an intervening native LMDB writer: expected transaction "
					+ expected + " but found " + actual);
		}
	}

	/**
	 * Reports whether the most recent dictionary commit reached LMDB's native commit boundary. The result remains true
	 * when a later optional overlay publication or maintenance step fails, so callers can retain bookkeeping for data
	 * that is already durable.
	 */
	boolean lastNativeCommitSucceeded() {
		return lastNativeCommitSucceeded;
	}

	private void endValueLookupMutation() {
		synchronized (writerAdmission) {
			if (writeTxn == 0 && writerPublication == null && writerStartsInFlight == 0 && env != 0 && !shuttingDown) {
				// A delayed reader reset from an older commit cannot certify another writer's uncompleted publication.
				valueLookupGeneration = new Object();
			}
		}
	}

	/**
	 * Gets the ID for the specified value.
	 *
	 * @param value A value.
	 * @return The ID for the specified value, or {@link LmdbValue#UNKNOWN_ID} if no such ID could be found.
	 * @throws IOException If an I/O error occurred.
	 */
	public long getId(Value value, boolean create) throws IOException {
		return getId(value, create, ValuePosition.NONE);
	}

	public long getId(Value value, int positionMask) throws IOException {
		return getId(value, false, positionMask);
	}

	public long getId(Value value, boolean create, int positionMask) throws IOException {
		ValuePosition.validateMask(positionMask);
		ReadSnapshot planning = planningValueSnapshot();
		if (!create && planning != null) {
			return getStatementId(planning, value, positionMask);
		}
		if (create) {
			checkReplayFailure();
			if (writeTxn != 0 && !isWriteTransactionOwner()) {
				return withWriterLookupContext((stack, txn) -> getId(value, true, positionMask));
			}
		}
		LmdbValue.InternalIdentity identity = value instanceof LmdbValue nativeValue
				? nativeValue.getInternalIdentity()
				: null;
		boolean own = identity != null && identity.revision().getValueStore() == this;
		if (own && ((LmdbValue) value).getSemanticVersion() != LmdbValue.UNKNOWN_ID) {
			WriterPublication publication = writerPublication;
			if ((publication == null || publication.owner == Thread.currentThread() && isWriteTransactionOwner())
					&& revision.equals(completedRevision(identity.revision()))
					&& identity.id() != LmdbValue.UNKNOWN_ID) {
				return identity.id();
			}
		}
		if (!create && !isWriteTransactionOwner()) {
			SnapshotValueLookup captured = captureSnapshotLookup(null, value);
			RdfTermKey key = capturedTermKey(captured);
			Object generation = valueLookupGeneration;
			ReverseIdCache.State<RdfTermKey> state = valueIDCache.state();
			if (key != null && generation != null && readContext.get().borrowedTxn == 0L) {
				ReverseIdCache.Entry<RdfTermKey> cached = valueIDCache.get(state, key, positionMask);
				ValueStoreRevision selected = revision;
				if (cached != null && sameRevision(cached.revision(), selected)) {
					boolean hit = cached.id() != LmdbValue.UNKNOWN_ID;
					if (!hit) {
						Object scope = valueLookupScope();
						hit = scope != null && cached.negativeScope() == scope;
					}
					if (hit && valueLookupGeneration == generation && valueIDCache.isCurrent(state)
							&& revision == selected) {
						if (own && cached.id() != LmdbValue.UNKNOWN_ID) {
							((LmdbValue) value).setInternalID(cached.id(), cached.revision());
						}
						return cached.id();
					}
				}
			}
			ValueLookupContext lookup = new ValueLookupContext(generation);
			ResolvedValueId resolved = readTransaction(env, (stack, txn) -> {
				lookup.captureScope(txn);
				Object scope = lookup.scope;
				ValueStoreRevision selected = completedRevision(currentReadRevision(LmdbValue.UNKNOWN_ID));
				ReverseIdCache.Entry<RdfTermKey> cached = key == null ? null
						: valueIDCache.get(state, key, positionMask);
				long id = LmdbValue.UNKNOWN_ID;
				boolean hit = false;
				if (cached != null && sameRevision(cached.revision(), selected)) {
					if (cached.id() == LmdbValue.UNKNOWN_ID && scope != null && cached.negativeScope() == scope) {
						hit = true;
					} else if (cached.id() != LmdbValue.UNKNOWN_ID && containsValueId(txn, cached.id())) {
						id = cached.id();
						hit = true;
					}
				}
				if (!hit) {
					id = getCapturedId(txn, captured, positionMask, lookup);
				}
				if (key != null && id == LmdbValue.UNKNOWN_ID) {
					lookup.values = lookup.values == null ? new ArrayList<>() : lookup.values;
					lookup.values.add(new ValueMiss(key, positionMask, state));
				} else if (key != null && scope != null && valueLookupGeneration == generation
						&& valueIDCache.isCurrent(state) && sameRevision(selected, revision)) {
					valueIDCache.put(state, key, id, selected, null, positionMask);
				}
				return new ResolvedValueId(id, selected);
			});
			lookup.complete();
			if (own && resolved.id() != LmdbValue.UNKNOWN_ID) {
				((LmdbValue) value).setInternalID(resolved.id(), resolved.revision());
			}
			return resolved.id();
		}
		return getId(value, create, positionMask, null);
	}

	private long getCapturedId(long txn, SnapshotValueLookup captured, int positionMask, ValueLookupContext lookup)
			throws IOException {
		if (captured instanceof SnapshotKnownId known) {
			return known.id();
		}
		RdfTermKey key = capturedTermKey(captured);
		ReverseIdCache.State<RdfTermKey> state = valueIDCache.state();
		ValueStoreRevision selected = completedRevision(currentReadRevision(LmdbValue.UNKNOWN_ID));
		ReverseIdCache.Entry<RdfTermKey> cached = key == null ? null : valueIDCache.get(state, key, positionMask);
		if (cached != null && sameRevision(cached.revision(), selected)) {
			if (cached.id() == LmdbValue.UNKNOWN_ID && lookup.scope != null && cached.negativeScope() == lookup.scope) {
				return LmdbValue.UNKNOWN_ID;
			}
			if (cached.id() != LmdbValue.UNKNOWN_ID && containsValueId(txn, cached.id())) {
				return cached.id();
			}
		}
		long id = switch (captured) {
		case SnapshotKnownId known -> known.id();
		case SnapshotEncodedValue encoded -> findCapturedId(txn, encoded.data());
		case SnapshotIRI iri -> {
			String namespace = new String(iri.namespaceData(), 1, iri.namespaceData().length - 1,
					StandardCharsets.UTF_8);
			ReverseIdCache.State<NamespaceKey> namespaces = namespaceIDCache.state();
			ReverseIdCache.Entry<NamespaceKey> found = namespaceIDCache.get(namespaces, namespace, ValuePosition.NONE);
			long namespaceId = LmdbValue.UNKNOWN_ID;
			boolean hit = false;
			if (found != null && sameRevision(found.revision(), selected)) {
				if (found.id() == LmdbValue.UNKNOWN_ID && lookup.scope != null
						&& found.negativeScope() == lookup.scope) {
					hit = true;
				} else if (found.id() != LmdbValue.UNKNOWN_ID && containsValueId(txn, found.id())) {
					namespaceId = found.id();
					hit = true;
				}
			}
			if (!hit) {
				namespaceId = findCapturedId(txn, iri.namespaceData());
				if (namespaceId == LmdbValue.UNKNOWN_ID) {
					lookup.missingNamespace(namespace, namespaces);
				} else if (valueLookupGeneration == lookup.generation && lookup.generation != null
						&& namespaceIDCache.isCurrent(namespaces) && sameRevision(selected, revision)) {
					cacheNamespaceResult(namespace, namespaceId, selected, null, namespaces);
				}
			}
			long result = LmdbValue.UNKNOWN_ID;
			if (namespaceId != LmdbValue.UNKNOWN_ID) {
				int prefix = 1 + Varint.calcLengthUnsigned(namespaceId);
				byte[] data = new byte[prefix + iri.localNameData().length];
				data[0] = URI_VALUE;
				Varint.writeUnsigned(data, 1, namespaceId);
				System.arraycopy(iri.localNameData(), 0, data, prefix, iri.localNameData().length);
				result = findCapturedId(txn, data);
			}
			if (result == LmdbValue.UNKNOWN_ID) {
				byte[] lexical = new byte[iri.namespaceData().length - 1 + iri.localNameData().length];
				System.arraycopy(iri.namespaceData(), 1, lexical, 0, iri.namespaceData().length - 1);
				System.arraycopy(iri.localNameData(), 0, lexical, iri.namespaceData().length - 1,
						iri.localNameData().length);
				try (MemoryStack stack = stackPush()) {
					result = findAlternativeIriId(lexical, -1, LmdbValue.UNKNOWN_ID, stack, txn);
				}
			}
			yield result;
		}
		case SnapshotLiteral literal -> {
			long datatypeId = literal.datatype() == null ? 0
					: getCapturedId(txn, literal.datatype(), ValuePosition.NONE, lookup);
			if (datatypeId == LmdbValue.UNKNOWN_ID) {
				yield LmdbValue.UNKNOWN_ID;
			}
			byte[] data = ValueStoreRecordCodec.literalData(new String(literal.labelData(), StandardCharsets.UTF_8),
					literal.languageData() == null ? Optional.empty()
							: Optional.of(new String(literal.languageData(), StandardCharsets.UTF_8)),
					literal.baseDirection(), datatypeId, canonicalLanguageTags);
			long found = findCapturedId(txn, data);
			yield found == LmdbValue.UNKNOWN_ID ? findLegacyLiteralInTransaction(txn, literal) : found;
		}
		case SnapshotTriple triple -> {
			long subject = getCapturedId(txn, triple.subject(), ValuePosition.SUBJECT, lookup);
			long predicate = getCapturedId(txn, triple.predicate(), ValuePosition.PREDICATE, lookup);
			long object = getCapturedId(txn, triple.object(), ValuePosition.OBJECT, lookup);
			yield subject == LmdbValue.UNKNOWN_ID || predicate == LmdbValue.UNKNOWN_ID || object == LmdbValue.UNKNOWN_ID
					? LmdbValue.UNKNOWN_ID
					: findTripleTermId(null, txn, subject, predicate, object);
		}
		};
		if (key != null && id == LmdbValue.UNKNOWN_ID) {
			lookup.values = lookup.values == null ? new ArrayList<>() : lookup.values;
			lookup.values.add(new ValueMiss(key, positionMask, state));
		} else if (key != null && lookup.generation != null && valueLookupGeneration == lookup.generation
				&& valueIDCache.isCurrent(state) && sameRevision(selected, revision)) {
			valueIDCache.put(state, key, id, selected, null, positionMask);
		}
		return id;
	}

	private long findCapturedId(long txn, byte[] data) throws IOException {
		try (MemoryStack stack = stackPush()) {
			Long id = findIdInTransaction(data, false, CoreDatatype.NONE, stack, txn);
			return id == null ? LmdbValue.UNKNOWN_ID : id;
		}
	}

	private record ResolvedValueId(long id, ValueStoreRevision revision) {
	}

	/** Derives the optional spelling memo from the same owned fields used by the physical lookup. */
	private static RdfTermKey capturedTermKey(SnapshotValueLookup lookup) {
		return switch (lookup) {
		case SnapshotKnownId ignored -> null;
		case SnapshotEncodedValue encoded -> encoded.data()[0] == BNODE_VALUE
				? new RdfTermKey(Value.Type.BNode, new String(encoded.data(), 1, encoded.data().length - 1,
						StandardCharsets.UTF_8), null, null, null, null, null, null)
				: null;
		case SnapshotIRI iri -> new RdfTermKey(Value.Type.IRI,
				new String(iri.namespaceData(), 1, iri.namespaceData().length - 1, StandardCharsets.UTF_8)
						+ new String(iri.localNameData(), StandardCharsets.UTF_8),
				null, null, null, null, null, null);
		case SnapshotLiteral literal -> {
			RdfTermKey datatype = literal.datatype() == null ? null : capturedTermKey(literal.datatype());
			yield datatype == null ? null
					: new RdfTermKey(Value.Type.Literal,
							new String(literal.labelData(), StandardCharsets.UTF_8),
							literal.languageData() == null ? null
									: new String(literal.languageData(), StandardCharsets.UTF_8),
							datatype.lexical(), literal.baseDirection(), null, null, null);
		}
		case SnapshotTriple triple -> {
			RdfTermKey subject = capturedTermKey(triple.subject());
			RdfTermKey predicate = capturedTermKey(triple.predicate());
			RdfTermKey object = capturedTermKey(triple.object());
			yield subject == null || predicate == null || object == null ? null
					: new RdfTermKey(Value.Type.TripleTerm, null, null, null, null, subject, predicate, object);
		}
		};
	}

	private long getId(Value value, boolean create, int positionMask, ValueLookupContext lookup) throws IOException {
		// Capture the pair once; the owning writer may checkpoint and publish a different epoch.
		LmdbValue.InternalIdentity identity = value instanceof LmdbValue nativeValue
				? nativeValue.getInternalIdentity()
				: null;
		boolean isOwnValue = identity != null && identity.revision().getValueStore() == this;
		boolean writerLookup = create || isWriteTransactionOwner();
		Object identityGeneration = valueLookupGeneration;
		if (isOwnValue && (writerLookup || identityGeneration != null)) {
			LmdbValue lmdbValue = (LmdbValue) value;
			if (lmdbValue.getSemanticVersion() != LmdbValue.UNKNOWN_ID
					&& revision.equals(completedRevision(identity.revision()))) {
				long id = identity.id();
				// Writer admission can assign this mutable shell while an ordinary lookup reads its ID.
				if (id != LmdbValue.UNKNOWN_ID && (writerLookup || valueLookupGeneration == identityGeneration)) {
					return id;
				}
			}
		}

		long transactionId = getTransactionValueId(value);
		if (transactionId != LmdbValue.UNKNOWN_ID) {
			if (isOwnValue) {
				((LmdbValue) value).setInternalID(transactionId, revision);
			}
			return transactionId;
		}

		long stamp = create || isWriteTransactionOwner() ? 0L : revisionLock.readLock();
		try {
			ReverseIdCache.State<RdfTermKey> cacheState = valueIDCache.state();
			ReverseIdCache.Entry<?> cachedID = cachedValueId(value, create, positionMask, lookup, cacheState);
			if (cachedID != null) {
				long id = cachedID.id();
				if (id != LmdbValue.UNKNOWN_ID) {
					cacheTransactionValueId(value, id);
				}
				if (isOwnValue && id != LmdbValue.UNKNOWN_ID) {
					// Store id in value for fast access in any consecutive calls
					((LmdbValue) value).setInternalID(id, revision);
				}
				return id;
			}

			boolean legacyLanguage = format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
					&& LegacySemanticScope.containsLanguage(value);
			if (!legacyLanguage && value instanceof Literal literal) {
				long inlineId = format.tryInline(literal);
				if (inlineId != LmdbValue.UNKNOWN_ID) {
					cacheStoredId(value, inlineId, isOwnValue);
					return inlineId;
				}
			}

			Object generation = valueLookupGeneration;
			boolean ownsLookup = !create && lookup == null;
			if (ownsLookup) {
				lookup = new ValueLookupContext(generation);
			}
			long id = legacyLanguage ? findLegacySemanticId(value, lookup) : LmdbValue.UNKNOWN_ID;
			if (id == LmdbValue.UNKNOWN_ID && legacyLanguage && value instanceof Literal literal) {
				id = format.tryInline(literal);
			}
			if (id == LmdbValue.UNKNOWN_ID) {
				if (value.isTripleTerm()) {
					TripleTerm tripleTerm = (TripleTerm) value;
					long subjectId = getId(tripleTerm.getSubject(), create, ValuePosition.SUBJECT, lookup);
					long predicateId = getId(tripleTerm.getPredicate(), create, ValuePosition.PREDICATE, lookup);
					long objectId = getId(tripleTerm.getObject(), create, ValuePosition.OBJECT, lookup);

					if (subjectId == LmdbValue.UNKNOWN_ID || predicateId == LmdbValue.UNKNOWN_ID
							|| objectId == LmdbValue.UNKNOWN_ID) {
						id = LmdbValue.UNKNOWN_ID;
					} else {
						id = findTripleTermId(subjectId, predicateId, objectId, create, lookup);
					}
				} else {
					// not inlined or ID not cached, search in index
					byte[] data = value2data(value, create, lookup);
					if (data != null) {
						CoreDatatype coreDatatype = value instanceof Literal literal
								? literal.getCoreDatatype()
								: CoreDatatype.NONE;
						id = findId(data, create, coreDatatype, lookup);
					} else if (value instanceof IRI iri) {
						id = findAlternativeIriId(iri, lookup);
					}
				}
			}

			if (id != LmdbValue.UNKNOWN_ID) {
				if (legacyValueIndex != null && isWriteTransactionOwner()
						&& LegacySemanticScope.containsLanguage(value)) {
					try {
						legacyValueIndex.add(LegacySemanticScope.detached(value), id);
					} catch (RuntimeException | Error failure) {
						closeLegacyValueIndex(failure);
						throw failure;
					}
				}
				cacheStoredId(value, id, isOwnValue, positionMask, generation, cacheState);
			} else if (lookup != null) {
				lookup.missingValue(value, positionMask, cacheState);
			}
			if (ownsLookup) {
				lookup.complete();
			}
			return id;
		} finally {
			if (stamp != 0L) {
				revisionLock.unlockRead(stamp);
			}
		}
	}

	private boolean revisionIsCurrent(LmdbValue value) {
		LmdbValue.InternalIdentity identity = value.getInternalIdentity();
		return value.getSemanticVersion() != LmdbValue.UNKNOWN_ID && identity.revision() != null
				&& identity.revision().getValueStore() == this
				&& revision.equals(completedRevision(identity.revision()));
	}

	private ReverseIdCache.Entry<?> cachedValueId(Value value, boolean create, int positionMask,
			ValueLookupContext lookup,
			ReverseIdCache.State<RdfTermKey> cacheState) throws IOException {
		Object generation = valueLookupGeneration;
		if (generation == null) {
			return null;
		}
		ReverseIdCache.Entry<RdfTermKey> entry = valueIDCache.get(cacheState, value, positionMask);
		if (entry != null && sameRevision(entry.revision(), revision)) {
			if (entry.id() != LmdbValue.UNKNOWN_ID) {
				if (valueIDCache.isCurrent(cacheState) && valueLookupGeneration == generation) {
					return entry;
				}
			} else if (!create) {
				Object scope = lookup == null ? valueLookupScope() : lookup.scope();
				if (scope != null && entry.negativeScope() == scope && valueIDCache.isCurrent(cacheState)
						&& valueLookupGeneration == generation) {
					return entry;
				}
			}
		}
		if (value instanceof IRI iri) {
			VocabularyId vocabulary = commonVocabulary.get(iri.stringValue());
			if (vocabulary != null && vocabulary.epoch() == cacheState.epoch()
					&& sameRevision(vocabulary.entry().revision(), revision) && valueIDCache.isCurrent(cacheState)
					&& valueLookupGeneration == generation) {
				return vocabulary.entry();
			}
		}
		return null;
	}

	int valueIDCacheCapacity(int positionMask) {
		return valueIDCache.capacity(positionMask);
	}

	/** The first physical reader supplies the before token for all nested lookups and early absence proofs. */
	private final class ValueLookupContext {
		private final Object generation;
		private final ValueStoreRevision lookupRevision = revision;
		private Object scope;
		private boolean invalid;
		private ArrayList<ValueMiss> values;
		private ArrayList<NamespaceMiss> namespaces;

		private ValueLookupContext(Object generation) {
			this.generation = generation;
			invalid = generation == null;
		}

		void captureScope(long txn) {
			if (!invalid) {
				acceptScope(valueLookupScope(generation, txn));
			}
		}

		Object scope() throws IOException {
			if (invalid || valueLookupGeneration != generation) {
				invalidate();
				return null;
			}
			if (scope == null) {
				// A cached absence may be consulted before any physical lookup. It still needs a native view check.
				acceptScope(valueLookupScope());
			}
			return scope;
		}

		private void acceptScope(Object observed) {
			if (observed == null || valueLookupGeneration != generation || scope != null && scope != observed) {
				invalidate();
			} else {
				scope = observed;
			}
		}

		private void invalidate() {
			invalid = true;
			scope = null;
		}

		void missingValue(Value value, int positionMask, ReverseIdCache.State<RdfTermKey> state) {
			if (scope != null) {
				if (values == null) {
					values = new ArrayList<>();
				}
				values.add(new ValueMiss(RdfTermKey.of(value), positionMask, state));
			}
		}

		void missingNamespace(String namespace, ReverseIdCache.State<NamespaceKey> state) {
			if (scope != null) {
				if (namespaces == null) {
					namespaces = new ArrayList<>();
				}
				namespaces.add(new NamespaceMiss(namespace, state));
			}
		}

		void complete() throws IOException {
			if (scope == null || valueLookupGeneration != generation || values == null && namespaces == null
					|| valueLookupScope() != scope
					|| !sameRevision(lookupRevision, revision)) {
				return;
			}
			if (values != null) {
				for (ValueMiss miss : values) {
					valueIDCache.put(miss.state(), miss.key(), LmdbValue.UNKNOWN_ID, lookupRevision, scope,
							miss.positionMask());
				}
			}
			if (namespaces != null) {
				for (NamespaceMiss miss : namespaces) {
					cacheNamespaceResult(miss.namespace(), LmdbValue.UNKNOWN_ID, lookupRevision, scope, miss.state());
				}
			}
		}
	}

	private record ValueMiss(RdfTermKey key, int positionMask, ReverseIdCache.State<RdfTermKey> state) {
	}

	private record NamespaceMiss(String namespace, ReverseIdCache.State<NamespaceKey> state) {
	}

	/** Find a live RDF-equal owner without changing the byte-preserving legacy dictionary. */
	private long findLegacySemanticId(Value value, ValueLookupContext lookup) throws IOException {
		if (isWriteTransactionOwner()) {
			return findLegacyWriterSemanticId(value);
		}
		if (value instanceof TripleTerm term) {
			long subject = getId(term.getSubject(), false, ValuePosition.SUBJECT, lookup);
			long predicate = getId(term.getPredicate(), false, ValuePosition.PREDICATE, lookup);
			if (subject == LmdbValue.UNKNOWN_ID || predicate == LmdbValue.UNKNOWN_ID) {
				return LmdbValue.UNKNOWN_ID;
			}
			long object = LegacySemanticScope.containsLanguage(term.getObject()) ? LmdbValue.UNKNOWN_ID
					: getId(term.getObject(), false, ValuePosition.OBJECT, lookup);
			if (object == LmdbValue.UNKNOWN_ID && !LegacySemanticScope.containsLanguage(term.getObject())) {
				return LmdbValue.UNKNOWN_ID;
			}
			return readTransaction(env, (stack, txn) -> {
				if (lookup != null) {
					lookup.captureScope(txn);
				}
				TripleIndex index = TripleIndex.getBestIndex(tripleTermIndexes, subject, predicate, object, -1);
				long visited = 0;
				try (RecordIterator records = new LmdbRecordIterator(index,
						index.getPatternScore(subject, predicate, object, -1) > 0,
						subject, predicate, object, -1, true, txnManager.createTxn(txn))) {
					long[] quad;
					while ((quad = records.next()) != null) {
						visited++;
						if (value.equals(getValue(quad[3]))) {
							return quad[3];
						}
					}
				} finally {
					observeLegacySemanticScan(visited);
				}
				return LmdbValue.UNKNOWN_ID;
			});
		}
		return readTransaction(env, (stack, txn) -> {
			if (lookup != null) {
				lookup.captureScope(txn);
			}
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, dbi, pointer));
			long cursor = pointer.get(0);
			long visited = 0;
			try {
				MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(new byte[] { ID_KEY }));
				MDBVal data = MDBVal.calloc(stack);
				for (int result = mdb_cursor_get(cursor, key, data, MDB_SET_RANGE); result == MDB_SUCCESS
						&& isIdKey(key.mv_data()); result = mdb_cursor_get(cursor, key, data, MDB_NEXT)) {
					visited++;
					long id = data2id(key.mv_data().duplicate());
					if (ValueIds.getIdType(id) != ValueIds.T_LITERAL
							&& ValueIds.getIdType(id) != ValueIds.T_CORE_LITERAL) {
						continue;
					}
					byte[] bytes = copyValue(data);
					// Retired payloads remain readable by snapshots but must never become new lookup owners.
					if (isLiveReverseOwner(stack, txn, id, bytes) && value.equals(data2value(id, bytes, null))) {
						return id;
					}
				}
				return LmdbValue.UNKNOWN_ID;
			} finally {
				mdb_cursor_close(cursor);
				observeLegacySemanticScan(visited);
			}
		});
	}

	/** Each dictionary source is seeded once per logical writer, including native resize continuations. */
	private long findLegacyWriterSemanticId(Value value) throws IOException {
		try {
			if (legacyValueIndex == null) {
				legacyValueIndex = legacyCollections == null ? new LegacySemanticIndex<>()
						: new LegacySemanticIndex<>(legacyCollections);
			}
			if (value instanceof TripleTerm && !legacyTermOwnersSeeded) {
				seedLegacyTermOwners();
				legacyTermOwnersSeeded = true;
			} else if (value instanceof Literal && !legacyLiteralOwnersSeeded) {
				seedLegacyLiteralOwners();
				legacyLiteralOwnersSeeded = true;
			}
			Value key = LegacySemanticScope.detached(value);
			Iterator<Long> owners = legacyValueIndex.aliases(key);
			while (owners.hasNext()) {
				long id = owners.next();
				if (isLiveLegacySemanticOwner(id, key)) {
					return id;
				} else {
					legacyValueIndex.remove(id);
				}
			}
			return LmdbValue.UNKNOWN_ID;
		} catch (IOException | RuntimeException | Error failure) {
			closeLegacyValueIndex(failure);
			throw failure;
		}
	}

	private void seedLegacyLiteralOwners() throws IOException {
		readTransaction(env, (stack, txn) -> {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, dbi, pointer));
			long cursor = pointer.get(0);
			long visited = 0;
			try {
				MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(new byte[] { ID_KEY }));
				MDBVal data = MDBVal.calloc(stack);
				for (int result = mdb_cursor_get(cursor, key, data, MDB_SET_RANGE); result == MDB_SUCCESS
						&& isIdKey(key.mv_data()); result = mdb_cursor_get(cursor, key, data, MDB_NEXT)) {
					visited++;
					long id = data2id(key.mv_data().duplicate());
					if (ValueIds.getIdType(id) == ValueIds.T_LITERAL) {
						byte[] bytes = copyValue(data);
						if (isLiveReverseOwner(stack, txn, id, bytes)) {
							Value decoded = data2value(id, bytes, null);
							if (LegacySemanticScope.containsLanguage(decoded)) {
								legacyValueIndex.add(LegacySemanticScope.detached(decoded), id);
							}
						}
					}
				}
				return null;
			} finally {
				mdb_cursor_close(cursor);
				observeLegacySemanticScan(visited);
			}
		});
	}

	private void seedLegacyTermOwners() throws IOException {
		readTransaction(env, (stack, txn) -> {
			long visited = 0;
			try (RecordIterator records = new LmdbRecordIterator(tripleTermSpocIndex, false,
					-1, -1, -1, -1, true, txnManager.createTxn(txn))) {
				long[] quad;
				while ((quad = records.next()) != null) {
					visited++;
					Value decoded = getValue(quad[3]);
					if (LegacySemanticScope.containsLanguage(decoded)) {
						legacyValueIndex.add(LegacySemanticScope.detached(decoded), quad[3]);
					}
				}
			} finally {
				observeLegacySemanticScan(visited);
			}
			return null;
		});
	}

	private boolean isLiveLegacySemanticOwner(long id, Value expected) throws IOException {
		if (legacySemanticLookupObserver != null) {
			legacySemanticLookupObserver.accept(id);
		}
		return readTransaction(env, (stack, txn) -> {
			if (expected instanceof TripleTerm) {
				return hasTripleTermMapping(txn, id) && expected.equals(id2tripleTerm(id, null));
			}
			MDBVal key = MDBVal.calloc(stack).mv_data(id2data(idBuffer(stack), id).flip());
			MDBVal data = MDBVal.calloc(stack);
			int rc = mdb_get(txn, dbi, key, data);
			if (rc == MDB_NOTFOUND) {
				return false;
			}
			E(rc);
			byte[] bytes = copyValue(data);
			return isLiveReverseOwner(stack, txn, id, bytes) && expected.equals(data2value(id, bytes, null));
		});
	}

	private void closeLegacyValueIndex(Throwable primary) {
		LegacySemanticIndex<Value, Long> index = legacyValueIndex;
		legacyValueIndex = null;
		legacyLiteralOwnersSeeded = false;
		legacyTermOwnersSeeded = false;
		if (index != null) {
			try {
				index.close();
			} catch (RuntimeException | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

	PreparedValueBatch prepareFreshValues(FreshValueSession session, Value[] values) throws IOException {
		PreparedValueBatch prepared = new PreparedValueBatch(values);
		long stamp = revisionLock.readLock();
		try {
			for (int i = 0; i < values.length; i++) {
				prepared.inputIds[i] = prepareFreshValue(session, prepared, values[i]);
				prepared.hasOwnInputValues |= isOwnValue(values[i]);
			}
		} finally {
			revisionLock.unlockRead(stamp);
		}
		return prepared;
	}

	FreshValueAssignment assignFreshValues(FreshValueSession session, Value[] values) throws IOException {
		return assignFreshValues(session, values, null);
	}

	FreshValueAssignment assignFreshValues(FreshValueSession session, Value[] values, int[] predicateValueIndexes)
			throws IOException {
		if (session.valueIds.isEmpty() && values.length > 0) {
			session.valueIds = new ObjectLongHashMap<>(values.length);
		}
		int namespaceStart = session.provisionalNamespaces.size();
		int valueStart = session.provisionalValues.size();
		PreparedValueBatch publication = new PreparedValueBatch(values);
		long stamp = isWriteTransactionOwner() ? 0L : revisionLock.readLock();
		try {
			if (predicateValueIndexes != null && enablePredicateIdWindow(session)) {
				for (int predicateValueIndex : predicateValueIndexes) {
					assignFreshPredicate(session, (IRI) values[predicateValueIndex]);
				}
			}
			for (int i = 0; i < values.length; i++) {
				publication.inputIds[i] = assignFreshValue(session, values[i]);
				publication.hasOwnInputValues |= isOwnValue(values[i]);
			}
		} finally {
			if (stamp != 0L) {
				revisionLock.unlockRead(stamp);
			}
		}
		return new FreshValueAssignment(publication, namespaceStart, session.provisionalNamespaces.size(), valueStart,
				session.provisionalValues.size());
	}

	private boolean enablePredicateIdWindow(FreshValueSession session) {
		if (session.predicateIdWindowEnabled) {
			return true;
		}
		if (session.nextIdValueByType[ValueIds.T_URI] != 1) {
			return false;
		}
		session.nextIdValueByType[ValueIds.T_URI] = RESERVED_PREDICATE_ID_COUNT + 1;
		session.predicateIdWindowEnabled = true;
		return true;
	}

	private long assignFreshPredicate(FreshValueSession session, IRI predicate) throws IOException {
		long existingId = session.valueIds.getIfAbsent(predicate, LmdbValue.UNKNOWN_ID);
		if (existingId != LmdbValue.UNKNOWN_ID) {
			return existingId;
		}
		long namespaceId = assignFreshNamespace(session, predicate.getNamespace());
		long id = nextFreshPredicateId(session);
		session.valueIds.put(predicate, id);
		session.provisionalValues.add(predicate);
		addAssignedFreshReference(session, namespaceId);
		return id;
	}

	FreshValueEncoder freshValueEncoder(FreshValueSession session, FreshValueAssignment assignment) {
		return new FreshValueEncoder(session, assignment);
	}

	private long assignFreshValue(FreshValueSession session, Value value) throws IOException {
		long existingId = session.valueIds.getIfAbsent(value, LmdbValue.UNKNOWN_ID);
		if (existingId != LmdbValue.UNKNOWN_ID) {
			return existingId;
		}

		long inlineId = getInlineId(value);
		if (inlineId != LmdbValue.UNKNOWN_ID) {
			session.valueIds.put(value, inlineId);
			session.provisionalValues.add(value);
			return inlineId;
		}

		long referencedId = 0;
		long id;
		if (value instanceof TripleTerm triple) {
			long subjectId = assignFreshValue(session, triple.getSubject());
			long predicateId = assignFreshValue(session, triple.getPredicate());
			long objectId = assignFreshValue(session, triple.getObject());
			id = nextFreshId(session, TRIPLE_VALUE);
			session.valueIds.put(value, id);
			session.provisionalValues.add(value);
			addAssignedFreshReference(session, subjectId);
			addAssignedFreshReference(session, predicateId);
			addAssignedFreshReference(session, objectId);
			return id;
		}

		switch (value.getType()) {
		case Value.Type.IRI:
			referencedId = assignFreshNamespace(session, ((IRI) value).getNamespace());
			id = nextFreshId(session, URI_VALUE);
			break;
		case Value.Type.BNode:
			id = nextFreshId(session, BNODE_VALUE);
			break;
		case Value.Type.Literal:
			Literal literal = (Literal) value;
			IRI datatype = literal.getDatatype();
			referencedId = datatype == null ? 0 : assignFreshValue(session, datatype);
			id = nextFreshId(session, LITERAL_VALUE, literal.getCoreDatatype());
			break;
		default:
			throw new IllegalArgumentException("Unsupported fresh value type " + value.getType());
		}
		session.valueIds.put(value, id);
		session.provisionalValues.add(value);
		if (referencedId != 0) {
			addAssignedFreshReference(session, referencedId);
		}
		return id;
	}

	private long assignFreshNamespace(FreshValueSession session, String namespace) throws IOException {
		long existingId = session.namespaceIds.getIfAbsent(namespace, LmdbValue.UNKNOWN_ID);
		if (existingId != LmdbValue.UNKNOWN_ID) {
			return existingId;
		}
		long id = nextFreshId(session, NAMESPACE_VALUE);
		session.namespaceIds.put(namespace, id);
		session.provisionalNamespaces.add(namespace);
		return id;
	}

	private void addAssignedFreshReference(FreshValueSession session, long id) {
		session.referenceCounts.addToValue(id, 1);
		session.provisionalReferenceDeltas.addToValue(id, 1);
	}

	private void prepareAssignedFreshNamespace(FreshValueSession session, PreparedValueBatch prepared,
			String namespace) {
		byte[] data = ValueStoreRecordCodec.namespaceData(namespace);
		long id = session.namespaceIds.getIfAbsent(namespace, LmdbValue.UNKNOWN_ID);
		addPreparedValueRecord(session, prepared, null, namespace, id, data);
	}

	private void prepareAssignedFreshValue(FreshValueSession session, PreparedValueBatch prepared, Value value) {
		long id = session.valueIds.getIfAbsent(value, LmdbValue.UNKNOWN_ID);
		if (ValueIds.isInlined(id)) {
			return;
		}
		if (value instanceof TripleTerm triple) {
			prepared.tripleRecords.add(new PreparedTripleRecord(triple, id,
					session.valueIds.getIfAbsent(triple.getSubject(), LmdbValue.UNKNOWN_ID),
					session.valueIds.getIfAbsent(triple.getPredicate(), LmdbValue.UNKNOWN_ID),
					session.valueIds.getIfAbsent(triple.getObject(), LmdbValue.UNKNOWN_ID)));
			return;
		}

		byte[] data;
		switch (value.getType()) {
		case Value.Type.IRI:
			IRI iri = (IRI) value;
			data = uri2data(iri, session.namespaceIds.getIfAbsent(iri.getNamespace(), LmdbValue.UNKNOWN_ID));
			break;
		case Value.Type.BNode:
			data = bnode2data((BNode) value, true);
			break;
		case Value.Type.Literal:
			Literal literal = (Literal) value;
			IRI datatype = literal.getDatatype();
			long datatypeId = datatype == null ? 0
					: session.valueIds.getIfAbsent(datatype, LmdbValue.UNKNOWN_ID);
			data = literal2data(literal, datatypeId);
			break;
		default:
			throw new IllegalArgumentException("Unsupported fresh value type " + value.getType());
		}
		addPreparedValueRecord(session, prepared, value, null, id, data);
	}

	private void addAssignedReferenceCounts(FreshValueSession session, PreparedValueBatch prepared) {
		var referenceIds = session.provisionalReferenceDeltas.keysView().longIterator();
		while (referenceIds.hasNext()) {
			long id = referenceIds.next();
			prepared.referenceCountUpdates.put(id, session.referenceCounts.get(id));
		}
	}

	private long prepareFreshValue(FreshValueSession session, PreparedValueBatch prepared, Value value)
			throws IOException {
		long existingId = session.valueIds.getIfAbsent(value, LmdbValue.UNKNOWN_ID);
		if (existingId != LmdbValue.UNKNOWN_ID) {
			return existingId;
		}

		long inlineId = getInlineId(value);
		if (inlineId != LmdbValue.UNKNOWN_ID) {
			session.valueIds.put(value, inlineId);
			session.provisionalValues.add(value);
			return inlineId;
		}

		if (value instanceof TripleTerm triple) {
			long subjectId = prepareFreshValue(session, prepared, triple.getSubject());
			long predicateId = prepareFreshValue(session, prepared, triple.getPredicate());
			long objectId = prepareFreshValue(session, prepared, triple.getObject());
			long id = nextFreshId(session, TRIPLE_VALUE);
			session.valueIds.put(value, id);
			session.provisionalValues.add(value);
			prepared.tripleRecords.add(new PreparedTripleRecord(triple, id, subjectId, predicateId, objectId));
			addFreshReference(session, prepared, subjectId);
			addFreshReference(session, prepared, predicateId);
			addFreshReference(session, prepared, objectId);
			return id;
		}

		byte[] data;
		long referencedId = 0;
		CoreDatatype coreDatatype = CoreDatatype.NONE;
		switch (value.getType()) {
		case Value.Type.IRI:
			IRI iri = (IRI) value;
			long namespaceId = prepareFreshNamespace(session, prepared, iri.getNamespace());
			data = uri2data(iri, namespaceId);
			referencedId = namespaceId;
			break;
		case Value.Type.BNode:
			data = bnode2data((BNode) value, true);
			break;
		case Value.Type.Literal:
			Literal literal = (Literal) value;
			coreDatatype = literal.getCoreDatatype();
			IRI datatype = literal.getDatatype();
			long datatypeId = datatype == null ? 0 : prepareFreshValue(session, prepared, datatype);
			data = literal2data(literal, datatypeId);
			referencedId = datatypeId;
			break;
		default:
			throw new IllegalArgumentException("Unsupported fresh value type " + value.getType());
		}

		long id = nextFreshId(session, data[0], coreDatatype);
		session.valueIds.put(value, id);
		session.provisionalValues.add(value);
		addPreparedValueRecord(session, prepared, value, null, id, data);
		if (referencedId != 0) {
			addFreshReference(session, prepared, referencedId);
		}
		return id;
	}

	private void addFreshReference(FreshValueSession session, PreparedValueBatch prepared, long id) {
		long count = session.referenceCounts.addToValue(id, 1);
		session.provisionalReferenceDeltas.addToValue(id, 1);
		prepared.referenceCountUpdates.put(id, count);
	}

	private long prepareFreshNamespace(FreshValueSession session, PreparedValueBatch prepared, String namespace)
			throws IOException {
		long existingId = session.namespaceIds.getIfAbsent(namespace, LmdbValue.UNKNOWN_ID);
		if (existingId != LmdbValue.UNKNOWN_ID) {
			return existingId;
		}
		byte[] data = ValueStoreRecordCodec.namespaceData(namespace);
		long id = nextFreshId(session, NAMESPACE_VALUE);
		session.namespaceIds.put(namespace, id);
		session.provisionalNamespaces.add(namespace);
		addPreparedValueRecord(session, prepared, null, namespace, id, data);
		return id;
	}

	private void addPreparedValueRecord(FreshValueSession session, PreparedValueBatch prepared, Value value,
			String namespace, long id, byte[] data) {
		long dataHash = data.length > MAX_KEY_SIZE ? hash(lookupKey(data)) : 0;
		boolean firstForHash = false;
		if (data.length > MAX_KEY_SIZE) {
			Long firstId = session.firstLargeValueIds.putIfAbsent(dataHash, id);
			firstForHash = firstId == null;
			if (firstForHash) {
				session.provisionalFirstLargeHashes.add(dataHash);
			}
		}
		PreparedValueRecord record = new PreparedValueRecord(value, namespace, id, data, dataHash, firstForHash);
		prepared.records.add(record);
		if (namespace != null) {
			prepared.namespaceRecords.add(record);
		} else if (value instanceof IRI iri && isCommonVocabulary(iri)) {
			prepared.commonVocabularyRecords.add(record);
		}
	}

	private byte[] uri2data(IRI iri, long namespaceId) {
		return ValueStoreRecordCodec.iriData(iri, namespaceId);
	}

	private byte[] literal2data(Literal literal, long datatypeId) {
		return ValueStoreRecordCodec.literalData(literal, datatypeId, canonicalLanguageTags);
	}

	void persistPreparedValues(PreparedValueBatch prepared) throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer cursorHandle = stack.mallocPointer(1);
			E(mdb_cursor_open(writeTxn, dbi, cursorHandle));
			long cursor = cursorHandle.get(0);
			MDBVal keyVal = MDBVal.malloc(stack);
			MDBVal dataVal = MDBVal.malloc(stack);
			MDBVal idVal = MDBVal.malloc(stack);
			MDBVal emptyVal = MDBVal.calloc(stack);
			ByteBuffer idBytes = idBuffer(stack);
			ByteBuffer hashBytes = stack.malloc(2 + 2 * Long.BYTES + 2);
			try {
				for (PreparedValueRecord record : prepared.records) {
					if (record.data.length > MAX_KEY_SIZE) {
						continue;
					}
					stack.push();
					try {
						idBytes.clear();
						idVal.mv_data(id2data(idBytes, record.id).flip());
						dataVal.mv_data(stack.bytes(record.data));
						keyVal.mv_data(stack.bytes(lookupKey(record.data)));
						E(mdb_cursor_put(cursor, keyVal, idVal, 0));
					} finally {
						stack.pop();
					}
				}
				for (PreparedValueRecord record : prepared.records) {
					stack.push();
					try {
						idBytes.clear();
						idVal.mv_data(id2data(idBytes, record.id).flip());
						if (record.data.length <= MAX_KEY_SIZE) {
							dataVal.mv_data(stack.bytes(record.data));
							E(mdb_cursor_put(cursor, idVal, dataVal, 0));
						} else {
							dataVal.mv_size(record.data.length);
							E(mdb_cursor_put(cursor, idVal, dataVal, MDB_RESERVE));
							dataVal.mv_data().put(record.data);
						}
					} finally {
						stack.pop();
					}
				}
				for (PreparedValueRecord record : prepared.records) {
					if (record.data.length <= MAX_KEY_SIZE) {
						continue;
					}
					idBytes.clear();
					idVal.mv_data(id2data(idBytes, record.id).flip());
					hashBytes.clear();
					hashBytes.put(record.firstForHash ? HASH_KEY : HASHID_KEY);
					Varint.writeUnsigned(hashBytes, record.hash);
					if (!record.firstForHash) {
						hashBytes.put(idVal.mv_data().duplicate());
					}
					keyVal.mv_data(hashBytes.flip());
					E(mdb_cursor_put(cursor, keyVal, record.firstForHash ? idVal : emptyVal, 0));
				}
			} finally {
				mdb_cursor_close(cursor);
			}
			if (prepared.referenceCountUpdates.notEmpty()) {
				E(mdb_cursor_open(writeTxn, refCountsDbi, cursorHandle));
				long refCountCursor = cursorHandle.get(0);
				try {
					var referenceIds = prepared.referenceCountUpdates.keysView().longIterator();
					while (referenceIds.hasNext()) {
						long referencedId = referenceIds.next();
						idBytes.clear();
						idVal.mv_data(id2data(idBytes, referencedId).flip());
						hashBytes.clear();
						Varint.writeUnsigned(hashBytes, prepared.referenceCountUpdates.get(referencedId));
						dataVal.mv_data(hashBytes.flip());
						E(mdb_cursor_put(refCountCursor, idVal, dataVal, 0));
					}
				} finally {
					mdb_cursor_close(refCountCursor);
				}
			}
			ByteBuffer tripleKey = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
			for (PreparedTripleRecord triple : prepared.tripleRecords) {
				for (TripleIndex index : tripleTermIndexes) {
					tripleKey.clear();
					index.toKey(tripleKey, triple.subject, triple.predicate, triple.object, triple.id);
					keyVal.mv_data(tripleKey.flip());
					E(mdb_put(writeTxn, index.getDB(true), keyVal, emptyVal, 0));
				}
			}
		}
	}

	void publishPreparedValues(PreparedValueBatch prepared) {
		int namespaceCapacity = namespaceIDCache.isUnbounded() ? prepared.namespaceRecords.size()
				: namespaceIDCache.capacity();
		int valueCapacity = valueIDCache.isUnbounded() ? prepared.records.size() : valueIDCache.capacity();
		int namespaceStart = Math.max(0, prepared.namespaceRecords.size() - namespaceCapacity);
		int publishedValues = 0;
		for (int i = namespaceStart; i < prepared.namespaceRecords.size(); i++) {
			PreparedValueRecord record = prepared.namespaceRecords.get(i);
			cacheNamespaceId(record.namespace, record.id, valueLookupGeneration, namespaceIDCache.state());
		}
		for (int i = prepared.records.size() - 1; i >= 0 && publishedValues < valueCapacity; i--) {
			PreparedValueRecord record = prepared.records.get(i);
			if (record.value != null) {
				cacheStoredId(record.value, record.id, isOwnValue(record.value));
				publishedValues++;
			}
		}
		for (PreparedValueRecord record : prepared.commonVocabularyRecords) {
			cacheStoredId(record.value, record.id, isOwnValue(record.value));
		}
		if (valueHashCacheEnabled) {
			for (PreparedValueRecord record : prepared.records) {
				if (record.value != null && !ValueIds.isInlined(record.id)) {
					storeHashIfAbsent(record.id, record.value);
				}
			}
		}
		if (prepared.hasOwnInputValues) {
			for (int i = 0; i < prepared.inputValues.length; i++) {
				Value value = prepared.inputValues[i];
				if (isOwnValue(value)) {
					((LmdbValue) value).setInternalID(prepared.inputIds[i], revision);
				}
			}
		}
	}

	private long getKnownOrInlineId(Value value, boolean isOwnValue) throws IOException {
		return knownMutationId(value);
	}

	private long getInlineId(Value value) {
		return value instanceof Literal literal ? format.tryInline(literal) : LmdbValue.UNKNOWN_ID;
	}

	private void cacheStoredId(Value value, long id, boolean isOwnValue) {
		cacheStoredId(value, id, isOwnValue, ValuePosition.NONE, valueLookupGeneration, valueIDCache.state());
	}

	private void cacheStoredId(Value value, long id, boolean isOwnValue, int positionMask, Object generation,
			ReverseIdCache.State<RdfTermKey> state) {
		cacheTransactionValueId(value, id);
		if (isOwnValue) {
			LmdbValue lmdbValue = (LmdbValue) value;
			lmdbValue.setInternalID(id, revision);
		}
		if (!ValueIds.isInlined(id)) {
			storeHashIfAbsent(id, value);
			if (generation != null && valueLookupGeneration == generation && valueIDCache.isCurrent(state)) {
				RdfTermKey key = RdfTermKey.of(value);
				if (key.lexicalLength() <= MAX_SHARED_VALUE_CACHE_LEXICAL_CHARS) {
					ValueStoreRevision cachedRevision = revision;
					ReverseIdCache.Entry<RdfTermKey> entry = valueIDCache.put(state, key, id, cachedRevision, null,
							positionMask);
					if (entry != null && value instanceof IRI iri && isCommonVocabulary(iri)) {
						commonVocabulary.put(key.lexical(), new VocabularyId(entry, state.epoch()));
					}
				}
			}
		}
	}

	private void cacheNamespaceId(String namespace, long id, Object generation,
			ReverseIdCache.State<NamespaceKey> state) {
		if (generation != null && valueLookupGeneration == generation && namespaceIDCache.isCurrent(state)) {
			cacheNamespaceResult(namespace, id, revision, null, state);
		}
	}

	/** Ordinary namespace admission must preserve a same-view prefix proof published by the physical fallback. */
	private void cacheNamespaceResult(String namespace, long id, ValueStoreRevision lookupRevision, Object scope,
			ReverseIdCache.State<NamespaceKey> state) {
		ReverseIdCache.Entry<NamespaceKey> cached = namespaceIDCache.get(state, namespace, ValuePosition.NONE);
		if (cached != null && cached.id() == id && sameRevision(cached.revision(), lookupRevision)
				&& (id != LmdbValue.UNKNOWN_ID || cached.negativeScope() == scope)) {
			return;
		}
		namespaceIDCache.put(state, NamespaceKey.of(namespace), id, lookupRevision, scope, ValuePosition.NONE);
	}

	private void invalidateRefCountIntegrity(String reason) {
		refCountIntegrityEstablished = false;
		refCountRecoveryRequired = true;
		logger.debug("ValueStore ref-count integrity invalidated by {}", reason);
	}

	private void requireRefCountIntegrity(String operation) throws IOException {
		if (!refCountIntegrityEstablished || refCountRecoveryInProgress) {
			throw new IOException("Cannot " + operation
					+ " while ValueStore ref-count integrity is untrusted; reopen to reconcile live owners");
		}
	}

	static long estimateGcWriteBytes(int idCount) {
		return 2L * idCount * (1L + Long.BYTES + 2L + Long.BYTES);
	}

	public void gcIds(Collection<Long> ids, Collection<Long> nextIds) throws IOException {
		if (!enableGC()) {
			return;
		}
		if (!refCountRepairEnabled) {
			// Keep candidates durable while historical counts are untrusted. A later opted-in opener reconstructs
			// counts and checks authoritative statement liveness before draining this queue.
			recordRetiredIds(ids, 0L);
			return;
		}
		requireRefCountIntegrity("garbage collect ValueStore IDs");
		ids = new ArrayList<>(ids);
		valueIdLivenessChecker.filterUsedIds(ids);

		if (!ids.isEmpty()) {
			Collection<Long> candidates = ids;
			// wrap into read txn as resizeMap expects an active surrounding read txn
			readTransaction(env, (stack1, txn1) -> {
				// Reserve the complete dictionary, ref-count, triple-index, and unused-ID mutation before any component
				// count is changed. The footprint uses the actual records in this read view, not a per-edge byte
				// heuristic.
				resizeMap(writeTxn, reserveGarbageCollectionCapacity(stack1, txn1, candidates));

				final Collection<Long> finalIds = candidates;
				final Collection<Long> finalNextIds = nextIds;
				writeTransaction((stack, writeTxn) -> {
					MDBVal revIdVal = MDBVal.calloc(stack);
					MDBVal dataVal = MDBVal.calloc(stack);

					ByteBuffer revIdBb = stack.malloc(1 + Long.BYTES + 2 + Long.BYTES);
					Varint.writeUnsigned(revIdBb, revision.getRevisionId());
					int revLength = revIdBb.position();
					Set<Long> retiredIds = deleteValueToIdMappings(stack, writeTxn, finalIds, finalNextIds);
					for (long id : retiredIds) {
						revIdBb.position(revLength).limit(revIdBb.capacity());
						revIdVal.mv_data(id2data(revIdBb, id).flip());
						E(mdb_put(writeTxn, unusedDbi, revIdVal, dataVal, 0));
					}

					invalidateRevisionOnCommit = true;
					if (lazyRevisions.nextValueEvictionTime < 0) {
						lazyRevisions.nextValueEvictionTime = System.currentTimeMillis() + this.valueEvictionInterval;
					}
					return null;
				});
				return null;
			});
		}
	}

	/**
	 * Records durable retirement intents for IDs whose statements were removed at the given TripleStore data revision
	 * while pinned SNAPSHOT readers predating the removal were open. The dictionary entries stay fully intact; the IDs
	 * are handed to {@link #gcIds} only after the reader horizon has passed the revision. Requires the active write
	 * transaction; the records commit atomically with the dictionary changes.
	 */
	void recordRetiredIds(Collection<Long> ids, long tripleDataRevision) throws IOException {
		recordRetiredIds(ids, tripleDataRevision, false);
	}

	/** Publication owns all removed IDs before any retirement record is written. */
	void recordPublicationRetiredIds(Collection<Long> ids, long tripleDataRevision) throws IOException {
		recordRetiredIds(ids, tripleDataRevision, true);
	}

	private void recordRetiredIds(Collection<Long> ids, long tripleDataRevision, boolean publication)
			throws IOException {
		if (!enableGC() || ids.isEmpty()) {
			return;
		}
		if (refCountRepairEnabled) {
			requireRefCountIntegrity("record retired ValueStore IDs");
		}
		List<Long> capturedIds = List.copyOf(ids);
		// Finish native preflight before resizing. The continuation owns copied IDs and resolves the current
		// writer afterward; no retirement cursor or partially applied retirement records cross this boundary.
		long reservation = readTransaction(env,
				(stack, txn) -> reserveRetiredIdRecordCapacity(stack, txn, capturedIds.size(), capturedIds.size()));
		if (publication) {
			safeRetirementReservationResize.set(Boolean.TRUE);
		}
		try {
			readTransaction(env, (stack, txn) -> {
				resizeMap(writeTxn, reservation);
				return null;
			});
		} finally {
			if (publication) {
				safeRetirementReservationResize.remove();
			}
		}
		// Maintenance callers retain whole-batch rollback/retry: GC/removal never receives the publication
		// reservation certificate, even if it records another retirement frontier after its native mutations.
		writeTransaction((stack, currentWriteTxn) -> {
			retiredIdStore.recordRetirements(stack, currentWriteTxn, capturedIds, tripleDataRevision);
			return null;
		});
	}

	/**
	 * Collects retirement records whose revision is no newer than the given watermark (records from older boot epochs
	 * always qualify). Returns null when nothing is pending. Candidates must be re-checked for TripleStore liveness
	 * before being reclaimed.
	 */
	RetiredValueIdStore.DrainBatch pollRetiredIds(long maxRevisionInclusive, int maxIds) throws IOException {
		if (!refCountRepairEnabled || !retiredIdStore.hasPending()) {
			return null;
		}
		return readTransaction(env,
				(stack, txn) -> retiredIdStore.pollDrainable(stack, txn, maxRevisionInclusive, maxIds));
	}

	/**
	 * Deletes the records of a polled batch (matched and stale ordered-index entries plus by-ID records). Requires the
	 * active write transaction.
	 */
	void removeRetiredIds(RetiredValueIdStore.DrainBatch batch) throws IOException {
		if (batch == null || batch.isEmpty()) {
			return;
		}
		requireRefCountIntegrity("remove retired ValueStore IDs");
		readTransaction(env, (stack1, txn1) -> {
			resizeMap(writeTxn,
					reserveRetiredIdRecordCapacity(stack1, txn1, batch.ids.size(),
							batch.matchedSeqKeys.size() + batch.staleSeqKeys.size()));
			writeTransaction((stack, writeTxn) -> {
				retiredIdStore.removeDrained(stack, writeTxn, batch);
				return null;
			});
			return null;
		});
	}

	/** True when durable retirement records exist (possibly only superseded ones). */

	private boolean hasPositiveRefCount(MemoryStack stack, long txn, long id) throws IOException {
		stack.push();
		try {
			long cached = refCountsTxCache.get(id);
			if (cached != UNKNOWN_REF_COUNT) {
				return cached > 0L;
			}
			MDBVal idVal = MDBVal.calloc(stack);
			MDBVal countVal = MDBVal.calloc(stack);
			idVal.mv_data(id2data(idBuffer(stack), id).flip());
			int rc = mdb_get(txn, refCountsDbi, idVal, countVal);
			if (rc == MDB_NOTFOUND) {
				return false;
			}
			E(rc);
			try {
				return Varint.readUnsigned(countVal.mv_data()) > 0L;
			} catch (RuntimeException malformed) {
				throw new IOException("Malformed ValueStore ref-count record for ID " + id, malformed);
			}
		} finally {
			stack.pop();
		}
	}

	protected Set<Long> deleteValueToIdMappings(MemoryStack stack, long writeTxn, Collection<Long> ids,
			Collection<Long> newGcIds)
			throws IOException {
		Set<Long> retiredIds = new HashSet<>();
		int maxHashKeyLength = 2 + 2 * Long.BYTES + 2;
		ByteBuffer hashBb = stack.malloc(maxHashKeyLength);
		MDBVal idVal = MDBVal.calloc(stack);
		ByteBuffer idBb = idBuffer(stack);
		MDBVal hashVal = MDBVal.calloc(stack);
		MDBVal dataVal = MDBVal.calloc(stack);
		MDBVal ignoreVal = MDBVal.calloc(stack);

		MDBVal keyVal = MDBVal.malloc(stack);
		ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
		PointerBuffer pp = stack.mallocPointer(1);

		long termsCursor = 0;
		long valuesCursor = 0;
		try {
			for (Long id : ids) {
				long idValue = id;
				if (seededDatatypeIds.contains(id)) {
					continue;
				}
				idVal.mv_data(id2data(idBb.clear(), id).flip());
				if (hasPositiveRefCount(stack, writeTxn, id)) {
					continue;
				}
				if (legacyValueIndex != null) {
					try {
						legacyValueIndex.remove(id);
					} catch (RuntimeException | Error failure) {
						closeLegacyValueIndex(failure);
						throw failure;
					}
				}

				// special handling of triple terms
				if (ValueIds.getIdType(id) == ValueIds.T_TRIPLE) {
					// A triple term can still be referenced by another live triple term. Do not remove any of its
					// indexes or decrement its components until the canonical count reaches zero.
					if (hasPositiveRefCount(stack, writeTxn, id)) {
						continue;
					}
					if (termsCursor == 0) {
						E(mdb_cursor_open(writeTxn, tripleTermCspoIndex.getDB(true), pp));
						termsCursor = pp.get(0);
					}

					keyBuf.clear();
					tripleTermCspoIndex.getMinKey(keyBuf, -1, -1, -1, id);
					keyBuf.flip();
					keyVal.mv_data(keyBuf);

					int rc = mdb_cursor_get(termsCursor, keyVal, dataVal, MDB_SET_RANGE);
					if (rc == MDB_SUCCESS
							&& tripleTermCspoIndex.createMatcher(-1, -1, -1, id).matches(keyVal.mv_data())) {
						long[] quad = new long[4];
						tripleTermCspoIndex.keyToQuad(keyVal.mv_data(), quad);
						try {
							stack.push();
							if (!hasActiveTripleTermMapping(stack, writeTxn, quad)) {
								continue;
							}
						} finally {
							stack.pop();
						}
						for (int i = 0; i < 3; i++) {
							if (decrementRefCount(stack, writeTxn, quad[i])) {
								newGcIds.add(quad[i]);
							}
						}

						for (TripleIndex index : tripleTermIndexes) {
							// keep index for resolving id -> triple term
							if (index == tripleTermCspoIndex) {
								continue;
							}
							keyBuf.clear();
							index.toKey(keyBuf, quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
									quad[TripleIndex.OBJ_IDX], quad[TripleIndex.CONTEXT_IDX]);
							keyBuf.flip();
							// update buffer positions in MDBVal
							keyVal.mv_data(keyBuf);

							E(mdb_del(writeTxn, index.getDB(true), keyVal, null));
						}
						retiredIds.add(id);
					}
					continue;
				}

				idVal.mv_data(id2data(idBb.clear(), id).flip());
				// An ID must not have a positive reference count and must have an associated value.
				if (!hasPositiveRefCount(stack, writeTxn, id)) {
					int rc = mdb_get(writeTxn, dbi, idVal, dataVal);
					if (rc == MDB_NOTFOUND) {
						continue;
					}
					E(rc);
					recordCompressedValueChange(id);
					ByteBuffer dataBuffer = dataVal.mv_data();
					try {
						stack.push();
						if (!hasActiveValueMapping(stack, writeTxn, id, dataBuffer)) {
							continue;
						}
					} finally {
						stack.pop();
					}

					// update ref count if literal or URI namespace is removed
					if (dataBuffer.get(0) == LITERAL_VALUE || dataBuffer.get(0) == URI_VALUE) {
						long refId = Varint.readUnsigned(dataBuffer, 1);
						if (decrementRefCount(stack, writeTxn, refId)) {
							newGcIds.add(refId);
						}
					}

					int dataLength = dataBuffer.remaining();
					if (format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
							&& hasUpperCaseLanguageTag(dataBuffer)) {
						byte[] raw = new byte[dataLength];
						dataBuffer.duplicate().get(raw);
						byte[] canonical = canonicalLanguageKey(raw);
						// A valid earlier generation can still own its canonical association. Remove only this
						// owner's raw/canonical keys, from copied bytes, without deleting another live variant.
						removeOwnedReverseKey(stack, writeTxn, idValue, raw);
						if (dataLength <= MAX_KEY_SIZE || hash(raw) != hash(canonical)) {
							removeOwnedReverseKey(stack, writeTxn, idValue, canonical);
						}
					} else if (dataLength > MAX_KEY_SIZE) {
						byte[] data = new byte[dataLength];
						dataBuffer.get(data);
						// the hash association is keyed by the canonical form of the stored encoding
						long dataHash = hash(lookupKey(data));

						hashBb.clear();
						hashBb.put(HASH_KEY);
						Varint.writeUnsigned(hashBb, dataHash);
						int hashLength = hashBb.position();
						hashBb.flip();

						hashVal.mv_data(hashBb);

						// delete HASH -> ID association
						if (mdb_get(writeTxn, dbi, hashVal, ignoreVal) == MDB_SUCCESS
								&& data2id(ignoreVal.mv_data()) == id) {
							E(mdb_del(writeTxn, dbi, hashVal, null));
							// was first entry, find a possible next entry and make it the first
							hashBb.put(0, HASHID_KEY);
							hashBb.rewind();
							hashVal.mv_data(hashBb);

							if (valuesCursor == 0) {
								// initialize cursor
								E(mdb_cursor_open(writeTxn, dbi, pp));
								valuesCursor = pp.get(0);
							}

							if (mdb_cursor_get(valuesCursor, hashVal, dataVal, MDB_SET_RANGE) == MDB_SUCCESS) {
								if (compareRegion(hashVal.mv_data(), 0, hashBb, 0, hashLength) == 0) {
									ByteBuffer idBuffer2 = hashVal.mv_data();
									idBuffer2.position(hashLength);
									idVal.mv_data(idBuffer2);

									hashBb.put(0, HASH_KEY);
									hashVal.mv_data(hashBb);

									// HASH -> ID
									E(mdb_put(writeTxn, dbi, hashVal, idVal, 0));
									// delete existing mapping
									E(mdb_cursor_del(valuesCursor, 0));
								}
							}
						} else {
							// was not the first entry, delete HASH+ID association
							hashBb.put(0, HASHID_KEY);
							hashBb.limit(hashLength + idVal.mv_data().remaining());
							hashBb.position(hashLength);
							hashBb.put(idVal.mv_data());
							hashBb.flip();

							hashVal.mv_data(hashBb);
							// delete HASH+ID -> [] association
							mdb_del(writeTxn, dbi, hashVal, null);
						}
					} else if (languageTagKeyMode == LanguageTagKeyMode.CANONICAL
							&& hasUpperCaseLanguageTag(dataBuffer)) {
						// the value -> ID association is keyed by the canonical (lower-cased language tag) encoding
						byte[] data = new byte[dataLength];
						dataBuffer.duplicate().get(data);
						if (format.isLegacy()) {
							removeOwnedReverseKey(stack, writeTxn, idValue, canonicalLanguageKey(data));
						} else {
							stack.push();
							try {
								dataVal.mv_data(stack.bytes(canonicalLanguageKey(data)));
								mdb_del(writeTxn, dbi, dataVal, null);
							} finally {
								stack.pop();
							}
						}
					} else {
						// delete value -> ID association
						dataVal.mv_data(dataBuffer);
						mdb_del(writeTxn, dbi, dataVal, null);
					}

					// does not delete ID -> value association
					retiredIds.add(id);
				}
			}
		} finally {
			if (termsCursor != 0) {
				mdb_cursor_close(termsCursor);
			}
			if (valuesCursor != 0) {
				mdb_cursor_close(valuesCursor);
			}
		}
		return retiredIds;
	}

	private boolean hasDictionaryRecord(MemoryStack stack, long txn, long id) throws IOException {
		if (id <= 0L || ValueIds.isInlined(id)) {
			return false;
		}
		stack.push();
		try {
			MDBVal key = MDBVal.calloc(stack);
			MDBVal data = MDBVal.calloc(stack);
			if (ValueIds.getIdType(id) == ValueIds.T_TRIPLE) {
				long cursor = 0L;
				try {
					PointerBuffer handle = stack.mallocPointer(1);
					E(mdb_cursor_open(txn, tripleTermCspoIndex.getDB(true), handle));
					cursor = handle.get(0);
					ByteBuffer bytes = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
					tripleTermCspoIndex.getMinKey(bytes, -1, -1, -1, id);
					key.mv_data(bytes.flip());
					int rc = mdb_cursor_get(cursor, key, data, MDB_SET_RANGE);
					if (rc == MDB_NOTFOUND) {
						return false;
					}
					E(rc);
					return tripleTermCspoIndex.createMatcher(-1, -1, -1, id).matches(key.mv_data());
				} finally {
					if (cursor != 0L) {
						mdb_cursor_close(cursor);
					}
				}
			}
			key.mv_data(stack.bytes(ValueStoreRecordCodec.idKey(id)));
			int rc = mdb_get(txn, dbi, key, data);
			if (rc == MDB_NOTFOUND) {
				return false;
			}
			E(rc);
			verifyOwnerRecordType(id, copyValue(data));
			return true;
		} finally {
			stack.pop();
		}
	}

	protected void freeUnusedIdsAndValues(MemoryStack stack, long txn, Set<Long> revisionIds) throws IOException {
		freeUnusedIdsAndValues(stack, txn, revisionIds, valueIdLivenessChecker);
	}

	private void freeUnusedIdsAndValues(MemoryStack stack, long txn, Set<Long> revisionIds,
			ValueIdLivenessChecker livenessChecker) throws IOException {
		if (!refCountRepairEnabled) {
			return;
		}
		boolean retiringCohorts = revisionIds != null;
		MDBVal idVal = MDBVal.calloc(stack);
		MDBVal revIdVal = MDBVal.calloc(stack);
		MDBVal dataVal = MDBVal.calloc(stack);
		MDBVal emptyVal = MDBVal.calloc(stack);
		MDBVal keyVal = null;
		ByteBuffer keyBuf = null;

		ByteBuffer revIdBb = stack.malloc(1 + Long.BYTES + 2 + Long.BYTES);

		boolean freeIds = false;
		Set<Long> livenessCandidate = new HashSet<>(1);
		long unusedIdsCursor = 0;
		long termsCursor = 0;
		try {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, unusedDbi, pp));
			unusedIdsCursor = pp.get(0);

			if (revisionIds == null) {
				// marker to delete all IDs
				revisionIds = Collections.singleton(0L);
			}
			for (Long revisionId : revisionIds) {
				// iterate all unused IDs for revision
				revIdBb.clear();
				Varint.writeUnsigned(revIdBb, revisionId);
				revIdVal.mv_data(revIdBb.flip());
				if (mdb_cursor_get(unusedIdsCursor, revIdVal, dataVal, MDB_SET_RANGE) == MDB_SUCCESS) {
					do {
						ByteBuffer keyBb = revIdVal.mv_data();
						long revisionOfId = Varint.readUnsigned(keyBb);
						if (revisionId == 0L || revisionOfId == revisionId) {
							idVal.mv_data(keyBb);
							long id = Varint.readUnsigned(keyBb, keyBb.position() + 1);
							livenessCandidate.clear();
							livenessCandidate.add(id);
							livenessChecker.filterUsedIds(livenessCandidate);
							if (livenessCandidate.isEmpty() || hasPositiveRefCount(stack, txn, id)
									|| !hasDictionaryRecord(stack, txn, id)) {
								// A stale retirement marker must not destroy a dependency that reconstruction found
								// live. Remove
								// only the obsolete hint. Missing records provide no proof that the ordinal is free:
								// an old writer may already have reused it under a different reference type.
								E(mdb_cursor_del(unusedIdsCursor, 0));
								continue;
							}

							if (ValueIds.getIdType(id) == ValueIds.T_TRIPLE && termsCursor == 0) {
								E(mdb_cursor_open(txn, tripleTermCspoIndex.getDB(true), pp));
								termsCursor = pp.get(0);
								keyVal = MDBVal.calloc(stack);
								keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
							}
							boolean activeForwardOwner;
							stack.push();
							try {
								activeForwardOwner = isActiveStoredId(stack, txn, termsCursor, id);
							} finally {
								stack.pop();
							}
							if (activeForwardOwner) {
								// Liveness/count proof above can discard an obsolete hint. Without that proof an active
								// forward owner cannot authorize reverse-only deletion or recycling its ordinal.
								throw new IOException(
										"Cannot reclaim ValueStore pending retirement for active value " + id);
							}

							if (!freeIds && txn == writeTxn) {
								ensurePendingValueAssociation();
								nativeMutation = true;
							}
							// add id to free list
							E(mdb_put(txn, freeDbi, idVal, emptyVal, 0));

							if (ValueIds.getIdType(id) == ValueIds.T_TRIPLE) {
								if (termsCursor == 0) {
									E(mdb_cursor_open(txn, tripleTermCspoIndex.getDB(true), pp));
									termsCursor = pp.get(0);
									keyVal = MDBVal.calloc(stack);
									keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
								}

								keyBuf.clear();
								tripleTermCspoIndex.getMinKey(keyBuf, -1, -1, -1, id);
								keyBuf.flip();
								keyVal.mv_data(keyBuf);

								int rc = mdb_cursor_get(termsCursor, keyVal, dataVal, MDB_SET_RANGE);
								if (rc == MDB_SUCCESS &&
										tripleTermCspoIndex.createMatcher(-1, -1, -1, id).matches(keyVal.mv_data())) {
									// delete id -> triple term association
									E(mdb_cursor_del(termsCursor, 0));
								}
							} else {
								// delete id -> value association
								E(mdb_del(txn, dbi, idVal, null));
								recordCompressedValueChange(id);
							}

							clearStoredHash(id);
							// delete id and value from unused list
							E(mdb_cursor_del(unusedIdsCursor, 0));

							freeIds = true;
						} else {
							break;
						}
					} while (mdb_cursor_get(unusedIdsCursor, revIdVal, dataVal, MDB_NEXT) == MDB_SUCCESS);
				}
			}
		} finally {
			if (unusedIdsCursor != 0) {
				mdb_cursor_close(unusedIdsCursor);
			}
			if (termsCursor != 0) {
				mdb_cursor_close(termsCursor);
			}
		}
		this.freeIdsAvailable |= freeIds;
		if (retiringCohorts && txn == writeTxn) {
			// Only the native writer that completed reclamation may retire the cohort at commit. A capacity
			// checkpoint before this method must leave candidates eligible for its replacement writer.
			reclaimedRevisionIds.addAll(revisionIds);
		}
	}

	public void startTransaction(boolean resize) throws IOException {
		checkReplayFailure();
		synchronized (writerAdmission) {
			boolean restarting = writerStartsInFlight != 0 && writerStartOwner == Thread.currentThread();
			if (env == 0 || shuttingDown && !restarting) {
				throw new IOException("ValueStore is closed");
			}
			if (writeTxn != 0 || writerPublication != null || writerStartsInFlight != 0 && !restarting) {
				throw new IOException("ValueStore already has an active write transaction");
			}
			writerStartsInFlight++;
			writerStartOwner = Thread.currentThread();
			nativeMutation = false;
			// Claim publication admission before fencing lookup: an older consumer must not reopen this writer's proof.
			beginValueLookupMutation();
			clearTransactionValueCaches();
		}
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);

			// Native begin can block on an external writer. The in-flight scope keeps the environment alive without
			// holding an admission monitor or native barrier through begin, reclamation, or map-growth restart.
			E(mdb_txn_begin(env, NULL, 0, pp));
			synchronized (writerAdmission) {
				writeTxn = pp.get(0);
				writeTxnOwner = Thread.currentThread();
				writerPublication = new WriterPublication(Thread.currentThread());
				writerFirstAppendedId = nextId;
				writerReusedIds.clear();
			}
			validateNativeWriterTransaction(writeTxn, startupInitializationInProgress
					? startupExpectedLastTransactionId
					: lastTrustedNativeTransactionId);
			beginCompressedValueMutation(writeTxn);

			// delete unused IDs if required on a regular basis
			// this is also run after opening the database
			if (lazyRevisions.nextValueEvictionTime >= 0
					&& System.currentTimeMillis() >= lazyRevisions.nextValueEvictionTime) {
				Set<Long> candidates;
				synchronized (unusedRevisionIds) {
					candidates = new HashSet<>(unusedRevisionIds);
					lazyRevisions.nextValueEvictionTime = -1;
				}
				// Eligible epochs cannot be resurrected. Copy the cohort under its tracker lock, then
				// release it before publication/map growth; admission orders associationGate before tracker.
				if (!candidates.isEmpty()) {
					MDBStat stat = MDBStat.malloc(stack);
					mdb_stat(writeTxn, unusedDbi, stat);
					if (resize) {
						resizeMap(writeTxn, stat.ms_entries() * (2L + Long.BYTES));
					}
					freeUnusedIdsAndValues(stack, writeTxn, candidates);
				}
			}
		} catch (LmdbUtil.MapFullException mapFull) {
			TxnReplayPolicy.Decision decision = replayDecision;
			if (autoGrow && decision != null && decision.frozenReplay) {
				throw frozenCapacity(mapFull);
			}
			if (autoGrow && decision != null && !decision.track) {
				growForTransactionRetry(0L, mapFull, decision);
			}
			throw mapFull;
		} finally {
			synchronized (writerAdmission) {
				if (--writerStartsInFlight == 0) {
					writerStartOwner = null;
					if (writeTxn == 0 && writerPublication == null && env != 0 && !shuttingDown) {
						// Native begin failed before creating publication authority; no cleanup remains to fence.
						endValueLookupMutation();
					}
				}
				writerAdmission.notifyAll();
			}
		}
	}

	/**
	 * Closes the snapshot and the DB iterator if any was opened in the current transaction
	 */
	void endTransaction(boolean commit, boolean autoGrow) throws IOException {
		if (commit && autoGrow && isFrozenReplay()) {
			throw new IOException("ValueStore checkpoints are disabled during frozen statement replay");
		}
		if (commit) {
			checkReplayFailure();
		}
		WriterPublication publication = writerPublication;
		if (publication == null) {
			return;
		}
		boolean publicationComplete = false;
		Throwable terminalFailure = null;
		try {
			publicationComplete = endWriterTransaction(publication, commit, autoGrow);
		} catch (Throwable failure) {
			terminalFailure = failure;
			if (publication.consumer == Thread.currentThread()) {
				if (writeTxn != 0) {
					// Preparation failed before native consumption. The owning writer can still roll back or
					// retry growth; shutdown must not wait for a consumer that has already unwound.
					associationGate.lock();
					try {
						publication.consumer = null;
					} finally {
						associationGate.unlock();
					}
				} else {
					try {
						// A consumed native pointer cannot retain IDs assigned by a failed writer, even when
						// commit or subsequent metadata cleanup throws before the normal invalidation path.
						setNewRevision();
						clearCaches();
						publicationComplete = true;
					} catch (Throwable cleanupFailure) {
						failure = appendFailure(failure, cleanupFailure);
						publication.failedCleanup = true;
					}
				}
			}
			rethrowFailure(failure);
		} finally {
			synchronized (writerAdmission) {
				if (publicationComplete && writerPublication == publication) {
					writerPublication = null;
					if (!shuttingDown) {
						// Only settled publication opens the global ready-value proof again, atomically with
						// admitting the next writer after aborted IDs and caches have been invalidated.
						endValueLookupMutation();
					}
				}
				writerAdmission.notifyAll();
			}
			if (!(commit && autoGrow)) {
				closeLegacyValueIndex(terminalFailure);
			}
		}
	}

	private boolean endWriterTransaction(WriterPublication publication, boolean commit, boolean autoGrow)
			throws IOException {
		associationGate.lock();
		try {
			if (writerPublication != publication || writeTxn == 0 || publication.consumer != null) {
				if (commit) {
					throw new IOException("ValueStore write transaction was already consumed");
				}
				return false;
			}
			// Claim before commit preparation touches native state. Close can retire an idle writer, but must
			// drain the winning consumer's complete publication, including native high-water refresh.
			publication.consumer = Thread.currentThread();
		} finally {
			associationGate.unlock();
		}
		if (writeTxn != 0) {
			if (commit) {
				// Checkpoints publish dictionary mappings too: their component counts must be in the same commit.
				try (MemoryStack stack = stackPush()) {
					persistNextId(stack, writeTxn);
					updateRefCounts(stack, writeTxn);
				}
				refCountsTxCache.clear();
				if (invalidateRevisionOnCommit) {
					long stamp = revisionLock.writeLock();
					try {
						int rc = commitAndReleaseWriteTransaction(publication);
						if (rc != MDB_SUCCESS) {
							cleanupAfterFailedCommit(rc);
						}
						retiredIdStore.transactionCommitted();
						flushPendingHashUpdates();
						lazyRevisions.retireCurrentEpoch();
						setNewRevision();
						clearCaches();
					} finally {
						revisionLock.unlockWrite(stamp);
					}
				} else {
					int rc = commitAndReleaseWriteTransaction(publication);
					if (rc != MDB_SUCCESS) {
						cleanupAfterFailedCommit(rc);
					}
					retiredIdStore.transactionCommitted();
					flushPendingHashUpdates();
				}
			} else {
				refCountsTxCache.clear();
				Throwable rollbackFailure = null;
				associationGate.lock();
				try {
					long transaction = nativeWriteTransaction(publication);
					abortWriteTransaction(transaction);
				} catch (Throwable failure) {
					rollbackFailure = failure;
				} finally {
					try {
						settleValueAssociation(false);
					} finally {
						releaseNativeWriteTransactionOwnership(publication);
						associationGate.unlock();
					}
					releaseWriteTransactionState();
					droppedTermIndexDbis.clear();
				}
				try {
					rollbackRetiredIds();
				} catch (Throwable failure) {
					rollbackFailure = appendFailure(rollbackFailure, failure);
				}
				try {
					clearPendingHashUpdates();
				} catch (Throwable failure) {
					rollbackFailure = appendFailure(rollbackFailure, failure);
				}
				// IDs assigned during the aborted transaction may have been cached on input values and in valueIDCache.
				// Reusing either cache would let a later transaction publish triples that point at dictionary IDs which
				// were never committed.
				try {
					setNewRevision();
				} catch (Throwable failure) {
					rollbackFailure = appendFailure(rollbackFailure, failure);
				}
				try {
					clearCaches();
				} catch (Throwable failure) {
					rollbackFailure = appendFailure(rollbackFailure, failure);
				}
				rethrowFailure(rollbackFailure);
			}
			releaseWriteTransactionState();
		}
		return true;
	}

	private long nativeWriteTransaction(WriterPublication publication) throws IOException {
		assert associationGate.isHeldByCurrentThread();
		if (writerPublication != publication || publication.consumer != Thread.currentThread() || writeTxn == 0) {
			throw new IOException("ValueStore write transaction was already consumed");
		}
		return writeTxn;
	}

	private void releaseNativeWriteTransactionOwnership(WriterPublication publication) {
		assert associationGate.isHeldByCurrentThread();
		synchronized (writerAdmission) {
			if (writerPublication == publication) {
				writeTxn = 0;
				writeTxnOwner = null;
			}
		}
	}

	void abortWriteTransaction(long transaction) {
		mdb_txn_abort(transaction);
	}

	void rollbackRetiredIds() {
		retiredIdStore.transactionRolledBack();
	}

	private static Throwable appendFailure(Throwable primary, Throwable additional) {
		if (primary == null) {
			return additional;
		}
		if (primary != additional) {
			primary.addSuppressed(additional);
		}
		return primary;
	}

	private static void rethrowFailure(Throwable failure) throws IOException {
		if (failure instanceof IOException ioException) {
			throw ioException;
		}
		if (failure instanceof RuntimeException runtimeException) {
			throw runtimeException;
		}
		if (failure instanceof Error error) {
			throw error;
		}
		if (failure != null) {
			throw new IOException(failure);
		}
	}

	private void releaseWriteTransactionState() {
		synchronized (writerAdmission) {
			writeTxn = 0;
			writeTxnOwner = null;
			invalidateRevisionOnCommit = false;
			nativeMutation = false;
			reclaimedRevisionIds.clear();
			writerReusedIds.clear();
		}
		clearTransactionValueCaches();
		lazyRevisions.schedulePendingEviction();
	}

	private int commitAndReleaseWriteTransaction(WriterPublication publication) throws IOException {
		ValueOverlayRegistry.Prepared overlay = prepareCompressedValueMutation(writeTxn);
		boolean mutated = nativeMutation;
		long nativeId = mdb_txn_id(writeTxn);
		long priorNativeId = lastTransactionId();
		try {
			int result;
			associationGate.lock();
			try {
				long transaction = nativeWriteTransaction(publication);
				try {
					result = commitWriteTransaction(transaction);
					settleValueAssociation(result == MDB_SUCCESS);
				} catch (RuntimeException | Error failure) {
					settleValueAssociation(false);
					throw failure;
				} finally {
					// LMDB consumed this pointer before another gated close/rollback can inspect it.
					releaseNativeWriteTransactionOwnership(publication);
				}
			} finally {
				associationGate.unlock();
			}
			if (result == MDB_SUCCESS) {
				lastNativeCommitSucceeded = true;
				long observed = trustedPostCommitTransactionId(nativeId, priorNativeId);
				if (startupInitializationInProgress) {
					startupExpectedLastTransactionId = observed;
				}
				if (refCountIntegrityEstablished || bulkNativeOwnership) {
					lastTrustedNativeTransactionId = observed;
				}
				completeCompressedValueMutation(overlay);
				synchronized (unusedRevisionIds) {
					unusedRevisionIds.removeAll(reclaimedRevisionIds);
				}
				nativeCommitGeneration++;
				if (mutated) {
					mutationGeneration++;
				}
				refreshCommittedHighWater();
			}
			return result;
		} finally {
			if (overlay != null) {
				overlay.close();
			}
			discardCompressedValueMutation();
			// LMDB consumes the transaction on every commit result. Do not let later close/rollback paths abort this
			// pointer.
			releaseWriteTransactionState();
			droppedTermIndexDbis.clear();
		}
	}

	private void cleanupAfterFailedCommit(int result) throws IOException {
		IOException nativeFailure;
		try {
			E(result);
			nativeFailure = new IOException("LMDB commit returned unexpected result " + result);
		} catch (IOException failure) {
			nativeFailure = failure;
		}
		refCountsTxCache.clear();
		try {
			rollbackRetiredIds();
		} catch (RuntimeException cleanupFailure) {
			nativeFailure.addSuppressed(cleanupFailure);
		}
		try {
			clearPendingHashUpdates();
		} catch (RuntimeException cleanupFailure) {
			nativeFailure.addSuppressed(cleanupFailure);
		}
		try {
			setNewRevision();
		} catch (RuntimeException cleanupFailure) {
			nativeFailure.addSuppressed(cleanupFailure);
		}
		try {
			clearCaches();
		} catch (RuntimeException cleanupFailure) {
			nativeFailure.addSuppressed(cleanupFailure);
		}
		throw nativeFailure;
	}

	int commitWriteTransaction(long transaction) {
		return mdb_txn_commit(transaction);
	}

	void closeEnvironment(long environment) {
		mdb_env_close(environment);
	}

	public void commit() throws IOException {
		long generationBefore = nativeCommitGeneration;
		TxnReplayPolicy.Decision decision = replayDecision;
		try {
			endTransaction(true, false);
		} catch (LmdbUtil.MapFullException mapFull) {
			if (autoGrow && decision != null && decision.frozenReplay) {
				throw frozenCapacity(mapFull, decision);
			}
			if (autoGrow && decision != null && !decision.track) {
				growForTransactionRetry(0L, mapFull, decision);
			}
			throw mapFull;
		} catch (IOException | RuntimeException | Error failure) {
			if (nativeCommitGeneration != generationBefore) {
				try {
					resetReadTransactionsAfterCommit();
				} catch (IOException | RuntimeException cleanupFailure) {
					failure.addSuppressed(cleanupFailure);
				}
			}
			throw failure;
		}
		resetReadTransactionsAfterCommit();
	}

	private void resetReadTransactionsAfterCommit() throws IOException {
		var lockManager = txnManager.lockManager();
		long stamp = 0;
		try {
			endTransaction(true, false);
			stamp = lockManager.writeLock();
			txnManager.reset();
		} catch (InterruptedException e) {
			throw new IOException(e);
		} finally {
			if (stamp != 0) {
				lockManager.unlockWrite(stamp);
			}
			endValueLookupMutation();
		}
	}

	/**
	 * Append exact, strictly increasing records to a newly created main value database.
	 */
	@InternalUseOnly
	public void appendBulkRecords(BulkRecordSource source, int maxTransactionRecords, long maxTransactionBytes)
			throws IOException {
		appendBulkRecords(source, dbi, maxTransactionRecords, maxTransactionBytes);
	}

	/**
	 * Append exact, strictly increasing reference-count records to a newly created value store.
	 */
	@InternalUseOnly
	public void appendBulkReferenceCounts(BulkRecordSource source, int maxTransactionRecords,
			long maxTransactionBytes) throws IOException {
		appendBulkRecords(source, refCountsDbi, maxTransactionRecords, maxTransactionBytes);
	}

	private void appendBulkRecords(BulkRecordSource source, int targetDbi, int maxTransactionRecords,
			long maxTransactionBytes) throws IOException {
		invalidateRefCountIntegrity(targetDbi == dbi ? "raw main dictionary bulk append"
				: "raw ref_counts bulk append");
		if (maxTransactionRecords <= 0 || maxTransactionBytes <= 0L) {
			throw new IllegalArgumentException("Bulk transaction bounds must be positive");
		}
		boolean appendingMainRecords = targetDbi == dbi && coreDatatypeLiteralReferences;
		if (appendingMainRecords) {
			deferNextIdPersistence = true;
		}
		try {
			byte[] previousKey = null;
			BulkRecord pending = source.next();
			while (pending != null) {
				ArrayList<BulkRecord> batch = new ArrayList<>(Math.min(maxTransactionRecords, 4096));
				long batchBytes = 0L;
				while (pending != null && batch.size() < maxTransactionRecords) {
					long recordBytes = Math.addExact((long) pending.key().length, pending.value().length);
					if (!batch.isEmpty() && batchBytes + recordBytes > maxTransactionBytes) {
						break;
					}
					if (previousKey != null && Arrays.compareUnsigned(previousKey, pending.key()) >= 0) {
						throw new IOException("ValueStore bulk records are not strictly increasing");
					}
					if (targetDbi == dbi && pending.key().length > 1 && pending.key()[0] == ID_KEY) {
						bulkDataRecordCount = add(bulkDataRecordCount, 1L);
						bulkMaximumDataBytes = Math.max(bulkMaximumDataBytes, pending.value().length);
						if (pending.value().length > 0) {
							if (pending.value()[0] == NAMESPACE_VALUE) {
								bulkMaximumNamespaceBytes = Math.max(bulkMaximumNamespaceBytes, pending.value().length);
							} else if (pending.value()[0] == URI_VALUE) {
								bulkMaximumIriBytes = Math.max(bulkMaximumIriBytes, pending.value().length);
							}
						}
						nextId = Math.max(nextId,
								Math.addExact(ValueIds.referenceOrdinal(data2id(ByteBuffer.wrap(pending.key()))), 1L));
					}
					previousKey = pending.key().clone();
					batch.add(pending);
					batchBytes = Math.addExact(batchBytes, recordBytes);
					pending = source.next();
				}
				appendBulkBatch(targetDbi, batch, batchBytes);
			}
		} finally {
			if (appendingMainRecords) {
				deferNextIdPersistence = false;
			}
		}
		if (appendingMainRecords) {
			// The deferred bulk stream keeps NEXT_ID_KEY out of each batch; reserve its final counter record before the
			// standalone commit that persists the recovered high-water mark.
			reserveWriteCapacity(leafEntryBytes(1L, MAX_UNSIGNED_ID_BYTES));
			writeTransaction((stack, txn) -> null);
		}
	}

	private void appendBulkBatch(int targetDbi, List<BulkRecord> batch, long batchBytes) throws IOException {
		long reservation = Math.max(64 * 1024L, Math.multiplyExact(batchBytes, 2L));
		for (int attempt = 0; attempt < 8; attempt++) {
			reserveWriteCapacity(reservation);
			startTransaction(false);
			if (targetDbi == dbi && compressedValueMutation != null) {
				compressedValueMutation.invalidate("raw dictionary bulk append");
			}
			boolean mapFull = false;
			try (MemoryStack stack = stackPush()) {
				PointerBuffer cursorHandle = stack.mallocPointer(1);
				E(mdb_cursor_open(writeTxn, targetDbi, cursorHandle));
				long cursor = cursorHandle.get(0);
				try {
					MDBVal key = MDBVal.malloc(stack);
					MDBVal value = MDBVal.malloc(stack);
					int appendFlags = MDB_APPEND;
					int last = mdb_cursor_get(cursor, key, value, MDB_LAST);
					if (last == MDB_SUCCESS) {
						// The main database also holds named-database catalog entries. Their keys can sort above
						// dictionary records, so a sorted input alone does not satisfy MDB_APPEND's tail precondition.
						if (Arrays.compareUnsigned(copyValue(key), batch.get(0).key()) >= 0) {
							appendFlags = MDB_NOOVERWRITE;
						}
					} else if (last != MDB_NOTFOUND) {
						E(last);
					}
					for (BulkRecord record : batch) {
						stack.push();
						try {
							byte[] valueBytes = record.value();
							key.mv_data(stack.bytes(record.key()));
							int result;
							if (valueBytes.length <= MAX_KEY_SIZE) {
								value.mv_data(stack.bytes(valueBytes));
								result = mdb_cursor_put(cursor, key, value, appendFlags);
							} else {
								// Large values (e.g. big literals) do not fit on the fixed-size LWJGL MemoryStack.
								// Reserve space inside LMDB and copy the payload directly into the reserved buffer,
								// mirroring the incremental write path in persistPreparedValues.
								value.mv_size(valueBytes.length);
								result = mdb_cursor_put(cursor, key, value, appendFlags | MDB_RESERVE);
								if (result == MDB_SUCCESS) {
									value.mv_data().put(valueBytes);
								}
							}
							if (result == org.lwjgl.util.lmdb.LMDB.MDB_MAP_FULL) {
								mapFull = true;
								break;
							}
							E(result);
						} finally {
							stack.pop();
						}
					}
				} finally {
					mdb_cursor_close(cursor);
				}
				if (!mapFull) {
					commit();
					return;
				}
			} catch (Throwable failure) {
				rollback();
				throw failure;
			}
			rollback();
			reservation = Math.multiplyExact(reservation, 2L);
		}
		throw new IOException("ValueStore map remained full after repeated bulk transaction growth");
	}

	/**
	 * Populate every configured RDF-star term index from exact assigned IDs.
	 */
	@InternalUseOnly
	public long appendBulkTripleTermIndex(String specification, BulkLongQuadSource source, int maxTransactionRecords)
			throws IOException {
		return appendBulkTripleTermIndex(specification, source, maxTransactionRecords, Long.MAX_VALUE);
	}

	@InternalUseOnly
	public long appendBulkTripleTermIndex(String specification, BulkLongQuadSource source, int maxTransactionRecords,
			long maxTransactionBytes) throws IOException {
		invalidateRefCountIntegrity("raw RDF-star term-index bulk append");
		int batchRecords = bulkIndexBatchRecords(maxTransactionRecords, maxTransactionBytes);
		TripleIndex index = tripleTermIndexes.stream()
				.filter(candidate -> candidate.toString().equals(specification))
				.findFirst()
				.orElseThrow(() -> new IOException("RDF-star term index is not configured: " + specification));
		if (!TripleIndex.usesUnsignedTupleOrder(specification)) {
			throw new IOException("RDF-star term index requires encoded-key sorting: " + specification);
		}
		if (!bulkAppendedTripleTermIndexes.add(specification)) {
			throw new IOException("RDF-star term index was already appended by this bulk load: " + specification);
		}

		long[] batch = new long[Math.multiplyExact(batchRecords, 4)];
		long[] tuple = new long[4];
		long[] previousTuple = new long[4];
		boolean hasPreviousTuple = false;
		boolean exhausted = false;
		long uniqueTerms = 0L;
		byte[] lastCommittedKey = null;
		while (!exhausted) {
			int count = 0;
			while (count < batchRecords) {
				if (!source.next(tuple)) {
					exhausted = true;
					break;
				}
				if (hasPreviousTuple) {
					int comparison = compareUnsignedBulkTuple(previousTuple, tuple);
					if (comparison > 0) {
						throw new IOException("RDF-star term index input is not sorted for " + specification);
					}
					if (comparison == 0) {
						continue;
					}
				}
				System.arraycopy(tuple, 0, previousTuple, 0, 4);
				hasPreviousTuple = true;
				System.arraycopy(tuple, 0, batch, count * 4, 4);
				count++;
			}
			if (count == 0) {
				continue;
			}
			lastCommittedKey = appendBulkTripleTermIndexBatch(index, specification, batch, count, lastCommittedKey);
			uniqueTerms += count;
		}
		return uniqueTerms;
	}

	private static int bulkIndexBatchRecords(int maxTransactionRecords, long maxTransactionBytes) {
		if (maxTransactionRecords <= 0 || maxTransactionBytes <= 0L) {
			throw new IllegalArgumentException("Bulk transaction record and byte limits must be positive");
		}
		long recordsByBytes = Math.max(1L, maxTransactionBytes / 128L);
		return Math.toIntExact(Math.min(maxTransactionRecords, recordsByBytes));
	}

	private byte[] appendBulkTripleTermIndexBatch(TripleIndex index, String specification, long[] batch, int count,
			byte[] lastCommittedKey) throws IOException {
		long reservation = Math.multiplyExact((long) count, 128L);
		for (int attempt = 0; attempt < 8; attempt++) {
			reserveWriteCapacity(reservation);
			startTransaction(false);
			boolean mapFull = false;
			byte[] finalKey = null;
			try (MemoryStack stack = stackPush()) {
				PointerBuffer cursorHandle = stack.mallocPointer(1);
				E(mdb_cursor_open(writeTxn, index.getDB(true), cursorHandle));
				long cursor = cursorHandle.get(0);
				try {
					MDBVal key = MDBVal.malloc(stack);
					MDBVal empty = MDBVal.calloc(stack);
					ByteBuffer keyBuffer = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
					byte[] previousKey = lastCommittedKey == null ? new byte[TripleIndex.MAX_KEY_LENGTH]
							: Arrays.copyOf(lastCommittedKey, TripleIndex.MAX_KEY_LENGTH);
					int previousKeyLength = lastCommittedKey == null ? 0 : lastCommittedKey.length;
					int subjectPosition = specification.indexOf('s');
					int predicatePosition = specification.indexOf('p');
					int objectPosition = specification.indexOf('o');
					int contextPosition = specification.indexOf('c');
					for (int row = 0; row < count; row++) {
						int offset = row * 4;
						keyBuffer.clear();
						index.toKey(keyBuffer, batch[offset + subjectPosition], batch[offset + predicatePosition],
								batch[offset + objectPosition], batch[offset + contextPosition]);
						keyBuffer.flip();
						if (previousKeyLength > 0
								&& compareUnsignedBulkKey(previousKey, previousKeyLength, keyBuffer) >= 0) {
							throw new IOException("Unsigned tuple order does not match encoded RDF-star term key order "
									+ "for " + specification);
						}
						key.mv_data(keyBuffer);
						int result = mdb_cursor_put(cursor, key, empty, MDB_APPEND);
						if (result == org.lwjgl.util.lmdb.LMDB.MDB_MAP_FULL) {
							mapFull = true;
							break;
						}
						E(result);
						previousKeyLength = keyBuffer.remaining();
						for (int i = 0; i < previousKeyLength; i++) {
							previousKey[i] = keyBuffer.get(keyBuffer.position() + i);
						}
					}
					if (!mapFull) {
						finalKey = Arrays.copyOf(previousKey, previousKeyLength);
					}
				} finally {
					mdb_cursor_close(cursor);
				}
				if (!mapFull) {
					commit();
					return finalKey;
				}
			} catch (Throwable failure) {
				rollback();
				throw failure;
			}
			rollback();
			reservation = Math.multiplyExact(reservation, 2L);
		}
		throw new IOException("RDF-star term index map remained full after repeated bulk transaction growth");
	}

	private static int compareUnsignedBulkTuple(long[] left, long[] right) {
		for (int component = 0; component < 4; component++) {
			int comparison = Long.compareUnsigned(left[component], right[component]);
			if (comparison != 0) {
				return comparison;
			}
		}
		return 0;
	}

	private static int compareUnsignedBulkKey(byte[] left, int leftLength, ByteBuffer right) {
		int length = Math.min(leftLength, right.remaining());
		for (int i = 0; i < length; i++) {
			int comparison = Integer.compare(Byte.toUnsignedInt(left[i]),
					Byte.toUnsignedInt(right.get(right.position() + i)));
			if (comparison != 0) {
				return comparison;
			}
		}
		return Integer.compare(leftLength, right.remaining());
	}

	/**
	 * Populate every configured RDF-star term index from exact assigned IDs.
	 */
	@InternalUseOnly
	public void appendBulkTripleTerms(BulkLongQuadSource source, int maxTransactionRecords) throws IOException {
		invalidateRefCountIntegrity("raw RDF-star term-index bulk append");
		if (maxTransactionRecords <= 0) {
			throw new IllegalArgumentException("Bulk transaction record limit must be positive");
		}
		long[][] batch = new long[maxTransactionRecords][4];
		boolean exhausted = false;
		while (!exhausted) {
			int count = 0;
			while (count < batch.length) {
				if (!source.next(batch[count])) {
					exhausted = true;
					break;
				}
				count++;
			}
			if (count == 0) {
				break;
			}
			reserveWriteCapacity(Math.multiplyExact((long) count, Math.max(1, tripleTermIndexes.size()) * 64L));
			startTransaction(false);
			try (MemoryStack stack = stackPush()) {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal empty = MDBVal.calloc(stack);
				ByteBuffer keyBuffer = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				for (int row = 0; row < count; row++) {
					long[] triple = batch[row];
					for (TripleIndex index : tripleTermIndexes) {
						keyBuffer.clear();
						index.toKey(keyBuffer, triple[0], triple[1], triple[2], triple[3]);
						key.mv_data(keyBuffer.flip());
						E(mdb_put(writeTxn, index.getDB(true), key, empty, 0));
					}
				}
				commit();
			} catch (Throwable failure) {
				rollback();
				throw failure;
			}
		}
	}

	/**
	 * Populate the optional byte-native RDF value hash cache in increasing ID order.
	 */
	@InternalUseOnly
	public void appendBulkHashes(BulkHashSource source) throws IOException {
		long[] idAndHash = new long[2];
		long previousId = 0L;
		while (source.next(idAndHash)) {
			if (idAndHash[0] <= previousId) {
				throw new IOException("Value hash records are not in increasing ID order");
			}
			writeHashNow(idAndHash[0], (int) idAndHash[1]);
			previousId = idAndHash[0];
		}
	}

	public void rollback() throws IOException {
		try {
			endTransaction(false, false);
		} finally {
			replayDecision = null;
		}
	}

	private void refreshCommittedHighWater() throws IOException {
		committedHighWaterBytes = Long.MAX_VALUE;
		committedHighWaterBytes = occupiedBytes();
	}

	/**
	 * Stores the supplied value and returns the ID that has been assigned to it. In case the value was already present,
	 * the value will not be stored again and the ID of the existing value is returned.
	 *
	 * @param value The Value to store.
	 * @return The ID that has been assigned to the value.
	 * @throws IOException If an I/O error occurred.
	 */
	public long storeValue(Value value) throws IOException {
		return getId(value, true);
	}

	/** Resolves only one bounded, lexically captured statement batch; no state is retained across calls. */
	void storeValues(Value[] values, long[] ids, int count) throws IOException {
		checkReplayFailure();
		if (count == 0) {
			return;
		}
		if (writeTxn != 0 && !isWriteTransactionOwner()) {
			withWriterLookupContext((stack, txn) -> {
				storeValues(values, ids, count);
				return null;
			});
			return;
		}
		if (!isWriteTransactionOwner()) {
			// A dictionary-only batch still owns one authoritative writer, including publication and abort cleanup.
			startTransaction(true);
			try {
				storeValues(values, ids, count);
				commit();
			} catch (IOException | RuntimeException | Error failure) {
				try {
					rollback();
				} catch (IOException | RuntimeException | Error cleanup) {
					if (cleanup != failure) {
						failure.addSuppressed(cleanup);
					}
				}
				throw failure;
			}
			return;
		}
		byte[][] data = new byte[count][];
		CoreDatatype[] coreDatatypes = new CoreDatatype[count];
		int[] indexes = new int[count];
		int unresolved = 0;
		boolean[] cacheAfterLookup = new boolean[count];
		for (int i = 0; i < count; i++) {
			Value value = values[i];
			long id = knownMutationId(value);
			if (id == LmdbValue.UNKNOWN_ID && (value.isTripleTerm()
					|| format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
							&& LegacySemanticScope.containsLanguage(value))) {
				// Raw batch keys cannot discover an RDF-equal language owner; recursive term indexes and
				// legacy semantic owners keep the existing authoritative writer path.
				id = storeValue(value);
			}
			ids[i] = id;
			if (id != LmdbValue.UNKNOWN_ID) {
				cacheTransactionValueId(value, id);
				continue;
			}
			byte[] encoded = value2data(value, true);
			if (encoded != null) {
				data[unresolved] = encoded;
				coreDatatypes[unresolved] = value instanceof Literal literal ? literal.getCoreDatatype()
						: CoreDatatype.NONE;
				indexes[unresolved++] = i;
				cacheAfterLookup[i] = true;
			}
		}
		if (unresolved > 0) {
			findIds(data, coreDatatypes, indexes, ids, unresolved);
		}
		for (int i = 0; i < count; i++) {
			if (cacheAfterLookup[i] && ids[i] != LmdbValue.UNKNOWN_ID) {
				cacheStoredId(values[i], ids[i], isOwnValue(values[i]));
			}
		}
	}

	private long knownMutationId(Value value) throws IOException {
		LmdbValue.InternalIdentity identity = value instanceof LmdbValue nativeValue
				? nativeValue.getInternalIdentity()
				: null;
		if (identity != null && identity.revision().getValueStore() == this
				&& ((LmdbValue) value).getSemanticVersion() != LmdbValue.UNKNOWN_ID) {
			WriterPublication publication = writerPublication;
			if ((publication == null || publication.owner == Thread.currentThread() && isWriteTransactionOwner())
					&& revision.equals(completedRevision(identity.revision()))
					&& identity.id() != LmdbValue.UNKNOWN_ID) {
				return identity.id();
			}
		}
		long transactionId = getTransactionValueId(value);
		if (transactionId != LmdbValue.UNKNOWN_ID) {
			return transactionId;
		}
		FreshValueSession fresh = activeFreshValueSession;
		if (fresh != null && isWriteTransactionOwner()) {
			long id = fresh.valueIds.getIfAbsent(value, LmdbValue.UNKNOWN_ID);
			if (id != LmdbValue.UNKNOWN_ID) {
				return id;
			}
		}
		ReverseIdCache.Entry<?> cached = cachedValueId(value, true, ValuePosition.NONE, null, valueIDCache.state());
		if (cached != null) {
			return cached.id();
		}
		// A stored legacy language owner takes precedence over a possible inline representation. Preserve
		// ready native/transaction/cache hits above without forcing getters or decoding a lazy native value.
		return format.isLegacy() && languageTagKeyMode == LanguageTagKeyMode.CANONICAL
				&& LegacySemanticScope.containsLanguage(value) ? LmdbValue.UNKNOWN_ID : getInlineId(value);
	}

	/**
	 * Computes a hash code for the supplied data.
	 *
	 * @param data The data to calculate the hash code for.
	 * @return A hash code for the supplied data.
	 */
	private long hash(byte[] data) {
		return ValueStoreRecordCodec.hash(data);
	}

	/**
	 * Removes all values from the ValueStore.
	 *
	 * @throws IOException If an I/O error occurred.
	 */
	public void clear() throws IOException {
		while (true) {
			awaitWriterStartsForShutdown();
			synchronized (this) {
				if (!confirmWriterStartsFinished()) {
					continue;
				}
				if (closeInProgress) {
					throw new IOException("Cannot clear ValueStore during shutdown");
				}
				// Retire paired authority before an explicit native generation replacement can reset transaction IDs.
				RdfTermDomainQualification.withdraw(properties, null);
				if (!closeUnderMonitor()) {
					continue;
				}

				new File(dir, "data.mdb").delete();
				new File(dir, "lock.mdb").delete();
				ValueStoreHashFile.deleteIfPresent(dir);

				clearCaches();
				// clear() reopens the native environment. The closed registry/worker must not be reused;
				// old leased publications remain charged to the same process-wide budget until released.
				seededDatatypeIds.clear();
				compressedValues = valueOverlayEnabled ? ValueOverlayRegistry.configured() : null;
				tripleTermIndexes.clear();
				tripleTermSpocIndex = null;
				tripleTermCspoIndex = null;
				unusedRevisionIds.clear();
				bulkAppendedTripleTermIndexes.clear();
				freeIdsAvailable = false;
				lazyRevisions.nextValueEvictionTime = -1L;
				refCountIntegrityEstablished = false;
				refCountRecoveryRequired = false;
				refCountRecoveryInProgress = false;
				valueStoreInitializationComplete = false;
				deferNextIdPersistence = false;
				// Existing native value shells can outlive clear. A new generation must not reuse their IDs.
				open(false, true);
				setNewRevision();
				try {
					initializeAfterOpen(storeConfig);
				} catch (IOException | RuntimeException | Error e) {
					try {
						close();
					} catch (IOException | RuntimeException cleanup) {
						e.addSuppressed(cleanup);
					}
					throw e;
				}
				return;
			}
		}
	}

	protected void clearCaches() {
		valueCaches = new ValueCacheEpoch(valueIdentity.revision, valueCacheMask + 1);
		Arrays.fill(predicateCache, null);
		Arrays.fill(datatypeCache, null);
		Arrays.fill(valueHashCacheId, 0);
		Arrays.fill(valueHashCacheHash, 0);
		valueIDCache.clear();
		namespaceCache.clear();
		namespaceIDCache.clear();
		commonVocabulary.clear();
		PREVIOUS_NAMESPACE_HANDLE.setRelease(this, null);
	}

	/** The paired store supplies only its last owned native triple commit, after its writers have drained. */
	void prepareCleanClose(long tripleTransactionId) {
		closingTripleTransactionId = tripleTransactionId;
	}

	void prepareDomainQualificationClose() {
		forceDomainQualificationSyncOnClose = true;
	}

	boolean closedForDomainQualification() {
		return env == 0L;
	}

	boolean domainQualificationSyncSucceeded() {
		return domainQualificationSyncSucceeded;
	}

	void syncForDomainQualification(long environment) throws IOException {
		E(mdb_env_sync(environment, true));
	}

	void invalidateCleanCloseAfterUnknownTripleWriter() {
		closingTripleTransactionId = -1L;
		invalidateRefCountIntegrity("an intervening native triple writer before clean close");
	}

	long trustedClosedTransactionId() {
		return refCountIntegrityEstablished && !refCountRecoveryRequired && !refCountRecoveryInProgress
				? lastTrustedNativeTransactionId
				: -1L;
	}

	private void writeCleanRefCountMarker() {
		if (bulkCompletionSynced) {
			return;
		}
		if (!refCountRepairEnabled || !valueStoreInitializationComplete || !auxiliaryDatabasesInitialized
				|| !refCountIntegrityEstablished
				|| refCountRecoveryRequired
				|| refCountRecoveryInProgress || writeTxn != 0 || lastTrustedNativeTransactionId < 0L) {
			return;
		}
		try {
			writeTransaction((stack, txn) -> {
				if (closingTripleTransactionId >= 0L) {
					int metadata = openDatabaseWithTxn(txn, "gc_meta", 0);
					MDBVal key = MDBVal.calloc(stack)
							.mv_data(stack.bytes(PreparedBulkStore.CLEAN_TRIPLE_TRANSACTION_KEY));
					MDBVal value = MDBVal.calloc(stack)
							.mv_data(stack.bytes(ByteBuffer.allocate(Long.BYTES)
									.putLong(closingTripleTransactionId)
									.array()));
					E(mdb_put(txn, metadata, key, value, 0));
					key.mv_data(stack.bytes(PreparedBulkStore.CLEAN_PROPERTIES_FINGERPRINT_KEY));
					value.mv_data(stack.bytes(PreparedBulkStore.cleanPropertiesFingerprint(properties)));
					E(mdb_put(txn, metadata, key, value, 0));
				}
				writeRefCountMarker(stack, txn, REFCOUNT_MARKER_CLEAN);
				return null;
			});
		} catch (IOException | RuntimeException markerFailure) {
			// A failed final marker is conservative: the next open will reconstruct counts. Preserve normal close/error
			// handling rather than turning an otherwise closed store into an unusable one.
			refCountIntegrityEstablished = false;
			logger.warn("Could not persist clean ValueStore ref-count marker; recovery will run on next open",
					markerFailure);
		}
	}

	private void writeRefCountMarker(MemoryStack stack, long txn, byte state) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(stack.bytes(new byte[] { REFCOUNT_MARKER_KEY }));
		MDBVal value = MDBVal.calloc(stack);
		value.mv_data(stack.bytes(encodeRefCountMarker(state, mdb_txn_id(txn))));
		E(mdb_put(txn, refCountsDbi, key, value, 0));
	}

	/**
	 * Closes the ValueStore, releasing any file references, etc. Once closed, the ValueStore can no longer be used.
	 *
	 * @throws IOException If an I/O error occurred.
	 */
	public void close() throws IOException {
		while (true) {
			awaitWriterStartsForShutdown();
			synchronized (this) {
				if (!confirmWriterStartsFinished()) {
					continue;
				}
				if (!closeUnderMonitor()) {
					continue;
				}
				return;
			}
		}
	}

	/** Waits outside the store monitor and native barrier needed by admission maintenance and resize restart. */
	private void awaitWriterStartsForShutdown() throws IOException {
		boolean interrupted = Thread.interrupted();
		try {
			synchronized (writerAdmission) {
				if (writerStartsInFlight != 0 && writerStartOwner == Thread.currentThread()) {
					throw new IOException("Cannot close ValueStore during write transaction admission");
				}
				WriterPublication current = writerPublication;
				if (current != null && current.consumer == Thread.currentThread() && !current.failedCleanup) {
					throw new IOException("Cannot close ValueStore during write transaction publication");
				}
				shuttingDown = true;
				while (writerStartsInFlight != 0 || hasActiveWriterConsumer()) {
					WriterPublication publication = writerPublication;
					if (publication != null && publication.consumer == Thread.currentThread()) {
						throw new IOException("Cannot close ValueStore during write transaction publication");
					}
					try {
						writerAdmission.wait();
					} catch (InterruptedException e) {
						interrupted = true;
					}
				}
			}
		} finally {
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
		}
		// A borrowed writer can need the native exclusive barrier to resize. Drain its association ownership
		// before taking either that barrier or the store monitor, which its checkpoint may also need.
		associationGate.lock();
		associationGate.unlock();
	}

	/** Rechecks after taking the store monitor, since another clear may have reopened writer admission. */
	private boolean confirmWriterStartsFinished() {
		synchronized (writerAdmission) {
			shuttingDown = true;
			return writerStartsInFlight == 0 && !hasActiveWriterConsumer();
		}
	}

	private boolean hasActiveWriterConsumer() {
		WriterPublication publication = writerPublication;
		return publication != null && publication.consumer != null && !publication.failedCleanup;
	}

	private boolean closeUnderMonitor() throws IOException {
		assert Thread.holdsLock(this);
		if (env == 0 || closeInProgress) {
			return true;
		}
		closeInProgress = true;
		try {
			synchronized (valueOverlayBuildAdmission) {
				valueOverlayBuildAdmissionClosed = true;
				initialImportOverlayRebuildRequest = null;
				publiclyReleasedOverlayGeneration = null;
				valueOverlayBuildAdmission.notifyAll();
			}
			beginValueLookupMutation();
			awaitAndStopValueOverlayWarmup();
			writeCleanRefCountMarker();
			Throwable failure = null;
			for (ValueResolutionScope scope : valueResolutionScopes) {
				try {
					scope.close();
				} catch (Throwable closeFailure) {
					failure = appendFailure(failure, closeFailure);
				}
			}
			boolean nativeQuiesced = false;
			try (TxnManager.CloseBarrier ignored = txnManager.acquireCloseBarrier()) {
				nativeQuiesced = true;
				if (env != 0) {
					if (!associationGate.tryLock()) {
						// Release the exclusive barrier and monitor before waiting for a borrowed writer to finish.
						return false;
					}
					try {
						try {
							// Capture/claim under the association gate before freezing values or retiring readers.
							// A commit that wins this race owns all native refresh and publication cleanup.
							endTransaction(false, false);
						} catch (Throwable closeFailure) {
							failure = appendFailure(failure, closeFailure);
						}
						if (hasActiveWriterConsumer()) {
							// Retry outside both locks. The winning consumer may need native access to finish.
							return false;
						}
					} finally {
						associationGate.unlock();
					}
					try {
						sharedLazyValues.freezeForMaterialization();
					} catch (Throwable closeFailure) {
						failure = appendFailure(failure, closeFailure);
					}
					try {
						flushPendingHashUpdates();
					} catch (Throwable closeFailure) {
						failure = appendFailure(failure, closeFailure);
					}
					try {
						txnManager.closeUnderExclusiveLock();
					} catch (Throwable closeFailure) {
						failure = appendFailure(failure, closeFailure);
					}
				}
			} catch (Throwable closeFailure) {
				failure = appendFailure(failure, closeFailure);
			}
			if (nativeQuiesced && env != 0) {
				// An application getter may own a value monitor while waiting for the native read barrier.
				// Drain outside that barrier so the getter can observe the closed manager and release its monitor.
				// This synchronized close prevents another close from freeing the environment during the raw read.
				try {
					materializeSharedLazyValues();
				} catch (Throwable closeFailure) {
					failure = appendFailure(failure, closeFailure);
				} finally {
					try {
						sharedLazyValues.finishMaterialization();
					} catch (Throwable closeFailure) {
						failure = appendFailure(failure, closeFailure);
					}
				}
			}
			try (TxnManager.CloseBarrier ignored = txnManager.acquireCloseBarrier()) {
				if (nativeQuiesced && env != 0) {
					long environment = env;
					if (forceDomainQualificationSyncOnClose) {
						try {
							syncForDomainQualification(environment);
							domainQualificationSyncSucceeded = true;
						} catch (Throwable syncFailure) {
							failure = appendFailure(failure, syncFailure);
						}
					}
					try {
						closeEnvironment(environment);
					} catch (Throwable closeFailure) {
						failure = appendFailure(failure, closeFailure);
					} finally {
						env = 0;
						writerPublication = null;
					}
				}
			} catch (Throwable closeFailure) {
				failure = appendFailure(failure, closeFailure);
			}
			if (compressedValues != null) {
				compressedValues.close();
				compressedValues = null;
			}
			if (hashFile != null) {
				try {
					hashFile.close();
				} catch (Throwable closeFailure) {
					failure = appendFailure(failure, closeFailure);
				} finally {
					hashFile = null;
				}
			}
			rethrowFailure(failure);
			return true;
		} finally {
			closeInProgress = false;
		}
	}

	/** Runs during serialized close after managed readers have released all native reader slots. */
	private void materializeSharedLazyValues() throws IOException {
		LmdbUtil.readTransaction(env, (stack, txn) -> {
			ReadContext context = readContext.get();
			long previousTxn = context.borrowedTxn;
			context.borrowedTxn = txn;
			try {
				Throwable failure = null;
				while (true) {
					List<LmdbValue> liveValues = sharedLazyValues.drainLiveValues();
					if (liveValues.isEmpty()) {
						rethrowFailure(failure);
						return null;
					}
					for (LmdbValue value : liveValues) {
						try {
							materializeSharedLazyValue(value);
						} catch (Throwable materializationFailure) {
							failure = appendFailure(failure, materializationFailure);
						}
					}
				}
			} finally {
				context.borrowedTxn = previousTxn;
			}
		});
	}

	private void materializeSharedLazyValue(LmdbValue value) {
		ArrayDeque<Value> pending = new ArrayDeque<>();
		pending.add(value);
		while (!pending.isEmpty()) {
			Value next = pending.removeLast();
			if (next instanceof LmdbValue lmdb) {
				if (lmdb.getValueStoreRevision() instanceof ValueStoreRevision.Lazy lazy
						&& lazy.association() != null && lazy.association().isAborted()) {
					// A ready parent can contain unpublished children. Each child's own capability decides
					// whether shutdown may materialize it; aborted IDs must never read a replacement record.
					continue;
				}
				lmdb.init();
				lmdb.visitValueChildren(child -> {
					if (child != null) {
						pending.add(child);
					}
				});
			} else if (next instanceof TripleTerm triple) {
				pending.add(triple.getSubject());
				pending.add(triple.getPredicate());
				pending.add(triple.getObject());
			} else if (next instanceof Literal literal && literal.getDatatype() != null) {
				pending.add(literal.getDatatype());
			}
		}
	}

	private static Throwable retainCleanupFailure(Throwable primary, Throwable cleanup) {
		if (primary == null) {
			return cleanup;
		}
		if (primary != cleanup) {
			primary.addSuppressed(cleanup);
		}
		return primary;
	}

	boolean isNativeEnvironmentOpen() {
		return env != 0;
	}

	private void storeHashIfAbsent(long id, Value value) {
		if (!valueHashCacheEnabled || !hasStoredHashSlot(id)) {
			return;
		}
		if (getStoredHash(id) == 0) {
			storeHash(id, value.hashCode());
		}
	}

	private void writeHashNow(long id, int hash) {
		if (hashFile == null || !hasStoredHashSlot(id)) {
			return;
		}
		try {
			hashFile.put(id, hash);
		} catch (IOException e) {
			resetHashFileQuietly("write", e);
		}
	}

	private void flushPendingHashUpdates() {
		if (!valueHashCacheEnabled) {
			return;
		}
		Map<Long, Integer> updates;
		synchronized (pendingHashUpdates) {
			if (pendingHashUpdates.isEmpty()) {
				return;
			}
			updates = new HashMap<>(pendingHashUpdates);
			pendingHashUpdates.clear();
		}

		for (Map.Entry<Long, Integer> entry : updates.entrySet()) {
			writeHashNow(entry.getKey(), entry.getValue());
		}
	}

	private void clearPendingHashUpdates() {
		if (!valueHashCacheEnabled) {
			return;
		}
		synchronized (pendingHashUpdates) {
			pendingHashUpdates.clear();
		}
	}

	private void resetHashFileQuietly(String operation, IOException cause) {
		logger.warn("Resetting LMDB hash cache after {} failure", operation, cause);
		clearPendingHashUpdates();
		if (!valueHashCacheEnabled) {
			hashFile = null;
			return;
		}
		ValueStoreHashFile currentHashFile = hashFile;
		hashFile = null;
		try {
			if (currentHashFile != null) {
				currentHashFile.delete();
			} else {
				ValueStoreHashFile.deleteIfPresent(dir);
			}
		} catch (IOException deleteFailure) {
			logger.warn("Could not delete LMDB hash cache", deleteFailure);
		}
		openHashFileQuietly();
	}

	private static final class ReadersFullException extends IOException {

		private static final long serialVersionUID = 1L;

		private ReadersFullException() {
			super("MDB_READERS_FULL: Environment maxreaders limit reached");
		}
	}

	/**
	 * Checks if the supplied Value object is a LmdbValue object that has been created by this ValueStore.
	 */
	private boolean isOwnValue(Value value) {
		return value instanceof LmdbValue lmdbValue
				&& lmdbValue.getInternalIdentity().revision().getValueStore() == this;
	}

	private byte[] value2data(Value value, boolean create) throws IOException {
		return value2data(value, create, null);
	}

	private byte[] value2data(Value value, boolean create, ValueLookupContext lookup)
			throws IOException {
		Value.Type type = value.getType();
		return switch (type) {
		case Value.Type.IRI -> uri2data((IRI) value, create, lookup);
		case Value.Type.BNode -> bnode2data((BNode) value, create);
		case Value.Type.Literal -> literal2data((Literal) value, create, lookup);
		default -> throw new IllegalArgumentException("value parameter should be a URI, BNode or Literal");
		};

	}

	private byte[] uri2data(IRI uri, boolean create, ValueLookupContext lookup) throws IOException {
		long nsID = getNamespaceID(uri.getNamespace(), create, lookup);

		if (nsID == -1) {
			// Unknown namespace means unknown URI
			return null;
		}

		return ValueStoreRecordCodec.iriData(uri, nsID);
	}

	private byte[] bnode2data(BNode bNode, boolean create) {
		return ValueStoreRecordCodec.bnodeData(bNode);
	}

	private byte[] literal2data(Literal literal, boolean create, ValueLookupContext lookup) throws IOException {
		return literal2data(literal.getLabel(), literal.getLanguage(), literal.getBaseDirection(),
				literal.getDatatype(), create, lookup);
	}

	private byte[] literal2data(String label, Optional<String> lang, Literal.BaseDirection baseDirection, IRI dt,
			boolean create, ValueLookupContext lookup) throws IOException {
		// Get datatype ID
		long datatypeID = 0L;

		if (dt != null) {
			datatypeID = getId(dt, create, ValuePosition.NONE, lookup);

			if (datatypeID == LmdbValue.UNKNOWN_ID) {
				// Unknown datatype means unknown literal
				return null;
			}
		}

		return ValueStoreRecordCodec.literalData(label, lang, baseDirection, datatypeID, canonicalLanguageTags);
	}

	/** Immutable value identity and writer capabilities captured before this dictionary was opened. */
	@InternalUseOnly
	public LmdbStoreFormat getFormat() {
		return format;
	}

	/**
	 * Whether newly written language tags are canonicalized (lowercased), making value-to-id resolution unique per RDF
	 * term. Stores written before the {@code canonical-language-tags} store property existed answer {@code false} and
	 * may hold distinct ids for one language-tagged literal.
	 */
	public boolean usesCanonicalLanguageTags() {
		return canonicalLanguageTags;
	}

	/**
	 * Whether this store's inline integer-family ids use the value-ordered (biased) encoding recorded as
	 * {@code numeric-id-encoding=ordered-v1} in the store properties. Anything minting inline ids meant to be id-equal
	 * to store ids must honor this flag.
	 */
	public boolean usesOrderedNumericIds() {
		return orderedNumericIds;
	}

	@InternalUseOnly
	public boolean usesZeroFractionDateTimeIds() {
		return zeroFractionDateTimeIds;
	}

	/** Whether this store inlines literals into ids at all; when false, no inline literal id is ever minted. */
	public boolean inlinesLiterals() {
		return inlineLiterals;
	}

	private Optional<String> canonicalLanguage(Optional<String> language) {
		if (!canonicalLanguageTags || language.isEmpty()) {
			return language;
		}
		return Optional.of(language.get().toLowerCase(Locale.ROOT));
	}

	private LmdbValue data2value(long id, byte[] data, LmdbValue value) throws IOException {
		return data2value(id, data, value, currentReadRevision(id));
	}

	private LmdbValue data2value(long id, byte[] data, LmdbValue value, ValueStoreRevision valueRevision)
			throws IOException {
		return switch (data[0]) {
		case URI_VALUE -> data2uri(id, data, (LmdbIRI) value, valueRevision);
		case BNODE_VALUE -> data2bnode(id, data, (LmdbBNode) value, valueRevision);
		case LITERAL_VALUE -> data2literal(id, data, (LmdbLiteral) value, valueRevision);
		default -> throw new IllegalArgumentException("Invalid type " + data[0] + " for value with id " + id);
		};
	}

	private LmdbValue data2value(long id, long dataAddress, int dataLength, LmdbValue value,
			ValueStoreRevision valueRevision) throws IOException {
		byte type = memGetByte(dataAddress);
		return switch (type) {
		case URI_VALUE -> data2uri(id, dataAddress, dataLength, (LmdbIRI) value, valueRevision);
		case BNODE_VALUE -> data2bnode(id, dataAddress, dataLength, (LmdbBNode) value, valueRevision);
		case LITERAL_VALUE -> data2literal(id, dataAddress, dataLength, (LmdbLiteral) value, valueRevision);
		default -> throw new IllegalArgumentException("Invalid type " + type + " for value with id " + id);
		};
	}

	private LmdbValue data2value(ReadSnapshot snapshot, long txn, long id, byte[] data) throws IOException {
		return data2value(snapshot, txn, id, data, null);
	}

	private LmdbValue data2value(ReadSnapshot snapshot, long txn, long id, byte[] data, LmdbValue value)
			throws IOException {
		return switch (data[0]) {
		case URI_VALUE -> data2uri(snapshot, txn, id, data, (LmdbIRI) value);
		case BNODE_VALUE -> data2bnode(snapshot, id, data, (LmdbBNode) value);
		case LITERAL_VALUE -> data2literal(snapshot, txn, id, data, (LmdbLiteral) value);
		default -> throw new IllegalArgumentException("Invalid type " + data[0] + " for value with id " + id);
		};
	}

	private LmdbIRI data2uri(ReadSnapshot snapshot, long txn, long id, byte[] data, LmdbIRI value)
			throws IOException {
		ByteBuffer bb = ByteBuffer.wrap(data);
		bb.get();
		long nsID = Varint.readUnsignedHeap(bb);
		byte[] namespaceData = getData(txn, nsID);
		if (namespaceData == null) {
			return null;
		}
		String namespace = data2namespace(namespaceData);
		String localName = new String(data, bb.position(), bb.remaining(), StandardCharsets.UTF_8);
		if (value == null) {
			return new LmdbIRI(snapshot.completedRevision(), namespace, localName, id);
		}
		value.setNamespaceAndIri(namespace, localName);
		return value;
	}

	private LmdbBNode data2bnode(ReadSnapshot snapshot, long id, byte[] data, LmdbBNode value) {
		String nodeID = new String(data, 1, data.length - 1, StandardCharsets.UTF_8);
		if (value == null) {
			return new LmdbBNode(snapshot.completedRevision(), nodeID, id);
		}
		value.setID(nodeID);
		return value;
	}

	private LmdbLiteral data2literal(ReadSnapshot snapshot, long txn, long id, byte[] data, LmdbLiteral value)
			throws IOException {
		ByteBuffer bb = ByteBuffer.wrap(data);
		bb.get();
		long datatypeID = Varint.readUnsignedHeap(bb);
		DatatypeCacheEntry datatypeEntry = datatypeID > 0 ? getDatatype(snapshot, txn, datatypeID) : null;
		IRI datatype = datatypeEntry == null ? null : datatypeEntry.value();
		CoreDatatype coreDatatype = datatypeEntry == null ? null : datatypeEntry.coreDatatype();
		if (datatypeID > 0 && datatype == null) {
			return null;
		}

		int directionAndLangLength = bb.get() & 0xFF;
		int directionValue = directionAndLangLength >> 6;
		int langLength;
		if (directionValue == 3) {
			directionValue = directionAndLangLength & 0x3F;
			langLength = (int) Varint.readUnsignedHeap(bb);
		} else {
			langLength = directionAndLangLength & 0x3F;
		}
		String lang = langLength > 0 ? new String(data, bb.position(), langLength, StandardCharsets.UTF_8) : null;
		Literal.BaseDirection baseDirection = switch (directionValue) {
		case 1 -> Literal.BaseDirection.LTR;
		case 2 -> Literal.BaseDirection.RTL;
		default -> Literal.BaseDirection.NONE;
		};
		String label = new String(data, bb.position() + langLength, data.length - bb.position() - langLength,
				StandardCharsets.UTF_8);

		if (value == null) {
			if (lang != null) {
				return new LmdbLiteral(snapshot.completedRevision(), label, lang, baseDirection, id);
			} else if (datatype != null) {
				return new LmdbLiteral(snapshot.completedRevision(), label, datatype, coreDatatype, id);
			}
			return new LmdbLiteral(snapshot.completedRevision(), label, org.eclipse.rdf4j.model.vocabulary.XSD.STRING,
					id);
		}
		value.setLabel(label);
		if (lang != null) {
			value.setLanguage(lang);
			value.setBaseDirection(baseDirection);
			value.setDatatype(baseDirection != Literal.BaseDirection.NONE ? CoreDatatype.RDF.DIRLANGSTRING
					: CoreDatatype.RDF.LANGSTRING);
		} else if (datatype != null) {
			value.setDatatype(datatype, coreDatatype);
		} else {
			value.setDatatype(CoreDatatype.XSD.STRING);
		}
		return value;
	}

	private LmdbIRI data2uri(long id, byte[] data, LmdbIRI value, ValueStoreRevision valueRevision) throws IOException {
		ByteBuffer bb = ByteBuffer.wrap(data);
		// skip type marker
		bb.get();
		long nsID = Varint.readUnsignedHeap(bb);
		String namespace = getNamespace(nsID);
		String localName = new String(data, bb.position(), bb.remaining(), StandardCharsets.UTF_8);

		if (value == null) {
			return new LmdbIRI(completedRevision(valueRevision), namespace, localName, id);
		} else {
			value.setNamespaceAndIri(namespace, localName);
//			value.setIRIString(namespace + localName);
			return value;
		}
	}

	private LmdbIRI data2uri(long id, long dataAddress, int dataLength, LmdbIRI value, ValueStoreRevision valueRevision)
			throws IOException {
		int position = 1;
		long nsID = readUnsignedFromMemory(dataAddress, position);
		position += varintLengthFromMemory(dataAddress, position);
		String namespace = getNamespace(nsID);
		String localName = stringFromMemory(dataAddress, position, dataLength - position);

		if (value == null) {
			return new LmdbIRI(completedRevision(valueRevision), namespace, localName, id);
		} else {
			value.setNamespaceAndIri(namespace, localName);
//			value.setIRIString(namespace + localName);
			return value;
		}
	}

