	private LmdbLiteral data2literal(long id, byte[] data, LmdbLiteral value, ValueStoreRevision valueRevision)
			throws IOException {
		ByteBuffer bb = ByteBuffer.wrap(data);
		// skip type marker
		bb.get();
		// Get datatype
		long datatypeID = Varint.readUnsignedHeap(bb);
		DatatypeCacheEntry datatypeEntry = datatypeID > 0 ? getDatatype(datatypeID, valueRevision) : null;
		IRI datatype = datatypeEntry == null ? null : datatypeEntry.value();
		CoreDatatype coreDatatype = datatypeEntry == null ? null : datatypeEntry.coreDatatype();

		int directionAndLangLength = bb.get() & 0xFF;
		int directionValue = directionAndLangLength >> 6;
		int langLength;
		if (directionValue == 3) {
			directionValue = directionAndLangLength & 0x3F;
			langLength = (int) Varint.readUnsignedHeap(bb);
		} else {
			langLength = directionAndLangLength & 0x3F;
		}

		// Get language tag
		String lang = null;
		if (langLength > 0) {
			lang = new String(data, bb.position(), langLength, StandardCharsets.UTF_8);
		}

		Literal.BaseDirection baseDirection = baseDirection(directionValue);

		// Get label
		String label = new String(data, bb.position() + langLength, data.length - bb.position() - langLength,
				StandardCharsets.UTF_8);

		if (value == null) {
			if (lang != null) {
				return new LmdbLiteral(completedRevision(valueRevision), label, lang, baseDirection, id);
			} else if (datatype != null) {
				return new LmdbLiteral(completedRevision(valueRevision), label, datatype, coreDatatype, id);
			} else {
				return new LmdbLiteral(completedRevision(valueRevision), label,
						org.eclipse.rdf4j.model.vocabulary.XSD.STRING, id);
			}
		} else {
			value.setLabel(label);
			if (lang != null) {
				value.setLanguage(lang);
				value.setBaseDirection(baseDirection);
				if (baseDirection != Literal.BaseDirection.NONE) {
					value.setDatatype(CoreDatatype.RDF.DIRLANGSTRING);
				} else {
					value.setDatatype(CoreDatatype.RDF.LANGSTRING);
				}
			} else if (datatype != null) {
				value.setDatatype(datatype, coreDatatype);
			} else {
				value.setDatatype(CoreDatatype.XSD.STRING);
			}
			return value;
		}
	}

	private LmdbLiteral data2literal(long id, long dataAddress, int dataLength, LmdbLiteral value,
			ValueStoreRevision valueRevision) throws IOException {
		int position = 1;
		long datatypeID = readUnsignedFromMemory(dataAddress, position);
		position += varintLengthFromMemory(dataAddress, position);
		DatatypeCacheEntry datatypeEntry = datatypeID > 0 ? getDatatype(datatypeID, valueRevision) : null;
		IRI datatype = datatypeEntry == null ? null : datatypeEntry.value();
		CoreDatatype coreDatatype = datatypeEntry == null ? null : datatypeEntry.coreDatatype();

		int directionAndLangLength = memGetByte(dataAddress + position) & 0xFF;
		position++;
		int directionValue = directionAndLangLength >> 6;
		int langLength;
		if (directionValue == 3) {
			// extended header: the low bits hold the direction, a varint follows with the language tag length
			directionValue = directionAndLangLength & 0x3F;
			langLength = (int) readUnsignedFromMemory(dataAddress, position);
			position += varintLengthFromMemory(dataAddress, position);
		} else {
			langLength = directionAndLangLength & 0x3F;
		}
		Literal.BaseDirection baseDirection = baseDirection(directionValue);

		// Get language tag
		String lang = null;
		int langPosition = position;
		if (langLength > 0) {
			lang = stringFromMemory(dataAddress, langPosition, langLength);
		}

		// Get label
		int labelPosition = langPosition + langLength;
		String label = stringFromMemory(dataAddress, labelPosition, dataLength - labelPosition);

		if (value == null) {
			if (lang != null) {
				return new LmdbLiteral(completedRevision(valueRevision), label, lang, baseDirection, id);
			} else if (datatype != null) {
				return new LmdbLiteral(completedRevision(valueRevision), label, datatype, coreDatatype, id);
			} else {
				return new LmdbLiteral(completedRevision(valueRevision), label,
						org.eclipse.rdf4j.model.vocabulary.XSD.STRING, id);
			}
		} else {
			value.setLabel(label);
			if (lang != null) {
				value.setLanguage(lang);
				value.setBaseDirection(baseDirection);
				value.setDatatype(baseDirection == Literal.BaseDirection.NONE
						? CoreDatatype.RDF.LANGSTRING
						: CoreDatatype.RDF.DIRLANGSTRING);
			} else if (datatype != null) {
				value.setDatatype(datatype, coreDatatype);
			} else {
				value.setDatatype(CoreDatatype.XSD.STRING);
			}
			return value;
		}
	}

	private static Literal.BaseDirection baseDirection(int directionValue) {
		return switch (directionValue) {
		case 1 -> Literal.BaseDirection.LTR;
		case 2 -> Literal.BaseDirection.RTL;
		default -> Literal.BaseDirection.NONE;
		};
	}

	private String stringFromMemory(long address, int position, int length) {
		if (length == 0) {
			return "";
		}
		return memUTF8(address + position, length);
	}

	private int varintLengthFromMemory(long address, int position) {
		return Varint.firstToLength(memGetByte(address + position));
	}

	private long readUnsignedFromMemory(long address, int position) {
		int a0 = memGetByte(address + position) & 0xFF;

		if (a0 <= 240) {
			return a0;
		} else if (a0 <= 248) {
			int a1 = memGetByte(address + position + 1) & 0xFF;
			return 240 + 256L * (a0 - 241) + a1;
		} else if (a0 == 249) {
			int a1 = memGetByte(address + position + 1) & 0xFF;
			int a2 = memGetByte(address + position + 2) & 0xFF;
			return 2288 + 256L * a1 + a2;
		} else {
			int bytes = a0 - 250 + 3;
			long result = 0;
			for (int i = 0; i < bytes; i++) {
				result = (result << 8) | (memGetByte(address + position + 1 + i) & 0xFFL);
			}
			return result;
		}
	}

	private DatatypeCacheEntry getDatatype(long datatypeID, ValueStoreRevision valueRevision) throws IOException {
		DatatypeCacheEntry cached = cachedDatatypeEntry(datatypeID, valueRevision);
		if (cached != null) {
			return cached;
		}
		LmdbIRI datatype = (LmdbIRI) getValue(datatypeID, valueRevision);
		return datatype == null ? null : admitDatatype(datatypeID, datatype);
	}

	private DatatypeCacheEntry getDatatype(ReadSnapshot snapshot, long txn, long datatypeID) throws IOException {
		DatatypeCacheEntry cached = cachedDatatypeEntry(datatypeID, snapshot.completedRevision());
		if (cached != null) {
			return cached;
		}
		LmdbIRI datatype = (LmdbIRI) getValue(snapshot, txn, datatypeID);
		return datatype == null ? null : admitDatatype(datatypeID, datatype);
	}

	private String data2namespace(byte[] data) {
		return new String(data, 1, data.length - 1, StandardCharsets.UTF_8);
	}

	private long getNamespaceID(String namespace, boolean create, ValueLookupContext lookup) throws IOException {
		if (isWriteTransactionOwner()) {
			long transactionId = transactionNamespaceIds.getIfAbsent(namespace, LmdbValue.UNKNOWN_ID);
			if (transactionId != LmdbValue.UNKNOWN_ID) {
				return transactionId;
			}
			FreshValueSession freshSession = activeFreshValueSession;
			if (freshSession != null) {
				long freshId = freshSession.namespaceIds.getIfAbsent(namespace, LmdbValue.UNKNOWN_ID);
				if (freshId != LmdbValue.UNKNOWN_ID) {
					return freshId;
				}
			}
		}

		Object generation = valueLookupGeneration;
		ReverseIdCache.State<NamespaceKey> cacheState = namespaceIDCache.state();
		if (generation != null) {
			ReverseIdCache.Entry<NamespaceKey> cached = namespaceIDCache.get(cacheState, namespace, ValuePosition.NONE);
			if (cached != null && sameRevision(cached.revision(), revision)) {
				if (cached.id() != LmdbValue.UNKNOWN_ID) {
					if (namespaceIDCache.isCurrent(cacheState) && valueLookupGeneration == generation) {
						return cached.id();
					}
				} else if (!create) {
					Object scope = lookup == null ? valueLookupScope() : lookup.scope();
					if (scope != null && cached.negativeScope() == scope && namespaceIDCache.isCurrent(cacheState)
							&& valueLookupGeneration == generation) {
						return LmdbValue.UNKNOWN_ID;
					}
				}
			}
		}

		byte[] namespaceBytes = namespace.getBytes(StandardCharsets.UTF_8);
		byte[] namespaceData = new byte[namespaceBytes.length + 1];
		namespaceData[0] = NAMESPACE_VALUE;
		System.arraycopy(namespaceBytes, 0, namespaceData, 1, namespaceBytes.length);

		long id = findId(namespaceData, create, CoreDatatype.NONE, lookup);
		if (id != LmdbValue.UNKNOWN_ID) {
			if (isWriteTransactionOwner() && transactionNamespaceIds.size() < transactionValueCacheLimit) {
				transactionNamespaceIds.put(namespace, id);
			}
			cacheNamespaceId(namespace, id, generation, cacheState);
		} else if (lookup != null) {
			lookup.missingNamespace(namespace, cacheState);
		}

		return id;
	}

	static int calculateTransactionValueCacheLimit(long maxHeapBytes) {
		long heapScaledLimit = maxHeapBytes / TRANSACTION_VALUE_CACHE_BYTES_PER_ENTRY;
		return (int) Math.clamp(heapScaledLimit, MIN_TRANSACTION_VALUE_CACHE_SIZE,
				MAX_TRANSACTION_VALUE_CACHE_SIZE);
	}

	private boolean isWriteTransactionOwner() {
		long borrowed = readContext.get().borrowedTxn;
		long transaction = writeTxn;
		// A nonowner's empty borrowed context must not become an owner when the shared writer is cleared.
		return transaction != 0
				&& (writeTxnOwner == Thread.currentThread() || borrowed != 0 && borrowed == transaction);
	}

	/** Mutating APIs already admitted to the serialized writer must also resolve its uncommitted dependencies. */
	private <T> T withWriterLookupContext(Transaction<T> transaction) throws IOException {
		return withBorrowedReadContext(writeTxn, currentReadRevision(LmdbValue.UNKNOWN_ID), false, transaction);
	}

	private long getTransactionValueId(Value value) {
		if (!isWriteTransactionOwner()) {
			return LmdbValue.UNKNOWN_ID;
		}
		return transactionValueIds.getIfAbsent(RdfTermKey.of(value), LmdbValue.UNKNOWN_ID);
	}

	private void cacheTransactionValueId(Value value, long id) {
		if (isWriteTransactionOwner() && transactionValueIds.size() < transactionValueCacheLimit) {
			transactionValueIds.put(RdfTermKey.of(value), id);
		}
	}

	private void clearTransactionValueCaches() {
		transactionValueIds.clear();
		transactionNamespaceIds.clear();
	}

	/*-------------------------------------*
	 * Methods from interface ValueFactory *
	 *-------------------------------------*/

	private String getNamespace(long id) throws IOException {
		Object[] cached = (Object[]) PREVIOUS_NAMESPACE_HANDLE.getAcquire(this);
		if (cached != null && (long) cached[0] == id) {
			return (String) cached[1];
		}

		Long cacheID = id;
		String namespace = namespaceCache.get(cacheID);

		if (namespace == null) {
			byte[] namespaceData = getData(id);
			if (namespaceData != null) {
				namespace = data2namespace(namespaceData);
				namespaceCache.admit(cacheID, namespace);
			}
		}

		PREVIOUS_NAMESPACE_HANDLE.setRelease(this, new Object[] { cacheID, namespace });

		return namespace;
	}

